NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: "Ma tagna'anna to'ongan, Tuhan ya bay amapanjari dunya maka langit.",
        2: "Na, ma waktu kapamapanjari, in dunya halam gi' aniya' pangluwahanna maka halam gi' aniya' ai-aina. Aheya kal'ddoman ma sakalibutna maka alimun e' bohe' tegob-tegoban. Ina'an isab Rū Tuhan magpehē'-pi'itu min diyata' bohe' inān.",
        3: "Na angallam Tuhan, yukna, “Subay aniya' sawa.” Magtūy paniya' sawa.",
        4: "Pag'nda' Tuhan ma sawa inān, kasulutan iya. Puwas e' pinasaddī e'na sawa maka l'ddom.",
        5: "Ya pangōnna ma sawa ‘llaw’, ati ya pangōnna ma l'ddom ‘sangom’. Puwas pa'in sangom bo' llaw na, ya na tagna'an llaw.",
        6: "Puwas e' angallam Tuhan pabīng, yukna, “Subay aniya' pagtonga'an ma llot bohe' min deyo' maka bohe' min diyata'.” Magtūy paniya'.",
        7: "Puwas e' angallam Tuhan pabīng, yukna, “Subay aniya' pagtonga'an ma llot bohe' min deyo' maka bohe' min diyata'.” Magtūy paniya'.",
        8: "Na, ya pangōn Tuhan ma pagtonga'an e' ‘langit’. Puwas pa'in sangom bo' llaw, llaw karuwana na.",
        9: "Angallam na isab Tuhan, yukna, “Ya bohe' ma deyo'an langit subay pinagtimuk ma dakayu' pat'nna'an supaya aniya' tana' atoho'.” Magtūy paniya'.",
        10: "‘Tana'’ ya pangōn Tuhan ma gintana'an, ati ‘tahik’ ya pangōnna ma bohe' pinagtimuk e'. Pag'nda' Tuhan ma hinangna inān, kasulutan iya.",
        11: "Manjari itu, angallam na Tuhan, yukna, “Subay patomo' ai-ai ma tana' itu, kaginisan tinanom magbibinhi' maka kaginisan kayu magbubuwa', ya taga-binhi' isab.” Magtūy aniya' paltomo'-tomo'an indaginis ma gintana'an,",
        12: "saga tinanom magbibinhi' maka saga kakayuhan magbubuwa' ma ginis-ginisanna. Pag'nda' Tuhan, kasulutan iya.",
        13: "Puwas pa'in sangom bo' llaw, llaw kat'lluna na.",
        14: "Angallam isab Tuhan, yukna, “Subay aniya' saga sawa ma diyata' langit pamasaddī llaw min sangom, manjari aniya' pamandogahan llaw maka tahun maka musim.",
        15: "Saga sawa he' subay asinag ma diyata' langit supaya amasawa dunya.” Magtūy paniya' sawa.",
        16: "Aniya' tahinang e' Tuhan duwa sawa a'aslag, ya na mata llaw maka bulan. Mata llaw ya akosog amuwan sawa ma waktu llaw, bo' bulan ya amuwan sawa ma waktu sangom. Tapaniya'na isab saga bitu'un.",
        17: "Manjari saga sawa itu pinat'nna' e' Tuhan ma diyata' langit supaya pamasawa dunya",
        18: "ma waktu llaw maka ma waktu sangom, bo' aniya' pagbidda'an sawa maka l'ddom. Na, pag'nda' Tuhan ma bay hinangna itu, kasulutan iya.",
        19: "Puwas pa'in sangom bo' llaw, llaw ka'mpatna na.",
        20: "Angallam isab Tuhan, yukna, “Ya tahik maka bohe' subay ap'nno' e' ginisan sattuwa anahut-a'aslag. Subay isab aheka ginisan manuk-manuk magleyangan ma tonga'an ayan.”",
        21: "Manjari itu pinapanjari e' Tuhan saga sattuwa aheya ya maglahat ma tahik, maka ai-ai maglangihan atawa maglelehan ma tahik maka ma bohe'. Pinapanjari isab e'na kamemon ginisan manuk-manuk magleyangan. Na, pag'nda' Tuhan, kasulutan iya.",
        22: "Manjari itu binarakatan e' Tuhan bay pinapanjari e'na inān kamemon. Yukna ma ai-ai ma tahik, “Bang pa'in kam paheka supaya ap'nno' e'bi tahik ilu.” Yukna isab ma saga manuk-manuk, “Bang pa'in kam paheka.”",
        23: "Puwas pa'in sangom bo' llaw, llaw kalimana na.",
        24: "Angallam Tuhan, yukna, “Subay aniya' ba'anan kaginisan ma deya, saga hayop ni'ipat maka saga sattuwa talun, maka ai-ai isab maglelehan ma tana'.” Magtūy paniya' na.",
        25: "Hatina tahinang e' Tuhan saga kasattuwahan talun maka kahayopan maka ba'anan ai-ai ya maglelehan ma tana'. Pag'nda' Tuhan ma bay tahinangna, kasulutan iya.",
        26: "Manjari angallam isab Tuhan, yukna, “Papanjarita manusiya' pinasali' ni kita. Sigām ya pinapagbaya' ma ai-ai kamemon ma kaluha'an dunya itu, ma saga daing, ma saga ai-ai magleyangan, ma saga hayop maka sattuwa, maka ma sasuku isab maglelehan ma tana'.”",
        27: "Manjari pinapanjari manusiya' e' Tuhan ma buwat kajarihanna. Pinas'ppu sigām ni iya, nihinang sigām l'lla maka d'nda.",
        28: "Binarakatan sigām e' Tuhan. Yukna ma sigām, “Anganak kam paheka bo' pasaplag panubu'bi ma kaluha'an dunya ilu. Jari ka'am ya subay magbaya' ma dunya. Pagbaya'inbi saga daing maka saga manuk-manuk, sampay ai-ai kamemon ya taga-napas ma kareya-reyahan.”",
        29: "Angallam lagi' Tuhan, yukna, “Na, buwananta kam takakanbi saga tinanom magbibinhi' maka saga kayu magbubuwa', ya taga-binhi' isab.",
        30: "Pamuwanku isab kaparangan maka dahun kayu takakan e' saga sattuwa talun maka saga manuk-manuk sampay sasuku maglelehan ma tana'.” Magtūy tahinang buwat bay panoho'an Tuhan e'.",
        31: "Manjari pag'nda' Tuhan ma kamemon bay pinapanjari e'na, kasulutan to'ongan iya. Puwas pa'in sangom bo' llaw, llaw ka'nnomna na.",
    },
    2: {
        1: "Buwattē' bay pamapanjari dunya maka langit maka kamemon ai-aina.",
        2: "Ta'abut llaw kapitu'na, aubus na Tuhan ma kamemon hinangna ati pahali na iya.",
        3: "Binarakatan e' Tuhan llaw kapitu' he', minulliya e'na, sabab ya he' llaw bay kahalina min hinangna amapanjari ma kamemon ai-ai.",
        4: "Na, buwattē' ya pamapanjari langit maka dunya. Tagna' bay kapamapanjari PANGHŪ' Tuhan ma langit maka dunya,",
        5: "halam gi' aniya' tinanom patomo', halam gi' aniya' pasaha', sabab halam gi' aniya' ulan bay pinabeya' e' PANGHŪ' Tuhan ni dunya. Halam gi' aniya' manusiya' isab angisbat ma tana' pagtanoman,",
        6: "sagō' abase' tana' e' bohe' ya patubud min deyo'.",
        7: "Manjari itu aniya' tana' niā' e' PANGHŪ' Tuhan, kinompol e'na nihinang baran a'a. Ninapasan e'na napas kallum ni ūng a'a inān ati tahinang iya manusiya' taga-napas na.",
        8: "Na aniya' kabbun bay pinatomo' e' PANGHŪ' Tuhan ma lahat Eden, tampal ni sobangan. Manjari in manusiya' bay hinangna inān tapat'nna' e'na maina'an ma kabbun.",
        9: "Aniya' isab pinatomo' e' Tuhan ma kabbun inān kamemon ginisan kayu ya ahāp ni'nda' maka ahāp kinakan buwa'na. Ina'an isab ma t'ngnga' kabbun dampo'on kayu ya makabuwan kallum, maka ina'an isab dampo'on kayu makabuwan pangita'u pasal kahāpan maka kala'atan.",
        10: "Aniya' sapa' anasahan min lahat Eden amohe'an kakayuhan ma kabbun. Paluwas pa'in min Eden, in sapa' inān magsanga mpat.",
        11: "Dakayu' sangana inān, ya na sapa' Peson, anasahan pehē' tudju ni kaluha'an lahat Habila. Aniya' dī bulawan ma lahat ina'an-i",
        12: "maka aniya' du isab maina'an saga palmata maka bulitik kayu pahamut.",
        13: "Ya sanga karuwana, ya na sapa' Gehon, anasahan pehē' ni kaluha'an lahat Kūs.",
        14: "Sanga kat'lluna, ya na sapa' Tigris, anasahan pehē' tudju ni lahat Assiriya min bihingna tampal ni sobangan. Maka sanga ka'mpatna inān, ya na sapa' Alpurati.",
        15: "Sakali in manusiya' binowa e' PANGHŪ' Tuhan bo' pinat'nna' ma lahat Eden. Sinō' iya maghuma maka angisbat kabbunna.",
        16: "Magpanoho'an PANGHŪ' Tuhan ma iya, yukna, “Makajari ka amangan buwa' kayu ai-ai kabaya'annu mailu.",
        17: "Ya sadja mbal takakannu buwa' kayu ya makabuwan pangita'u pasal kahāpan maka kala'atan. Ebot-ebot to'ongan, da'a ka amangan. Ya llaw kapamangannu, ya na llaw kamataynu.”",
        18: "Manjari ah'lling PANGHŪ' Tuhan, yukna, “Mbal ahāp bang l'lla itu karangan-danganan. Hinanganku iya limbang makatōp ma iya bo' aniya' sehe'na makatabang.”",
        19: "Jari binowa e' PANGHŪ' Tuhan kamemon saga hayop maka sattuwa maka kamemon saga manuk-manuk ya bay hinangna min tana'. Binowa e'na pehē' ni l'lla inān supaya kinata'uwan bang ai pangōnna ma ba'anan sattuwa, hayop maka manuk-manuk e'. Manjari ai-ai pangōnna ma sasuku taga-napas inān, ya na he' ōnna.",
        20: "Sakali kaōnan e' l'lla inān kamemon saga sattuwa maka hayop maka saga manuk-manuk, malaingkan halam aniya' minsan dakayu' makatōp ma iya.",
        21: "Angkan pinatuli a'a itu e' PANGHŪ' Tuhan. Ahaluk pa'in tulina, niā' e' Tuhan dakayu' gusukna, ati tinaplok pabīng maka isi ya bay pangā'an gusuk.",
        22: "Jari aniya' d'nda nihinang e' PANGHŪ' Tuhan min gusuk l'lla, ati binowa e'na pehē' ni l'lla.",
        23: "Angabtang magtūy l'lla, yukna, “Ndū', itiya' na sali'ku. Bokog sin bokogku, isi sin isiku. Ōnanku iya ‘d'nda’ sabab bay iya ningā' min l'lla.”",
        24: "Ya ilu sababanna angkan l'lla pabutas min okoman ina'-mma'na bo' parakayu' ni h'ndana. Manjari tahinang sigām dabaran.",
        25: "Na, in l'lla maka d'nda itu anantang sali'-sali', sagō' halam sigām aiya'.",
    },
    3: {
        1: "Na, ma kamemon sattuwa bay pinapanjari e' PANGHŪ' Tuhan, sowa ya ataha' akkalna. Manjari atilaw sowa inān ma d'nda, yukna, “B'nnal bahā'? Bay kam nilāng e' Tuhan, sinō' da'a amangan buwa' kayu ai-ai ma kabbun ilu?”",
        2: "Ya sambung d'nda, “Makajari kami amangan min saga buwa' kayu ma kabbun itu,",
        3: "sagō' aniya' pangalāngan kami e' Tuhan. Sinō' kami da'a amangan buwa' kayu ya ma t'ngnga' kabbun itu. Minsan hal ni'ntanan buwa' inān, na amatay kami.”",
        4: 'Yuk sowa, “Ā! Mbal du kam amatay.',
        5: "Angkan buwattē' pamissala Tuhan, sabab kata'uwanna asal bang kam ganta' makakakan, makata'u kam kahāpan maka kala'atan, hatina tahinang kam sali' Tuhan.”",
        6: "Sakali itu, pag'nda' d'nda ni buwa' kayu-i, kalingkatan iya. Buwa'na inān ahāp kinakan, ahāp isab pangā'an pangita'u. Jari ang'ttu' iya buwa' min kayu inān bo' kinakan e'na. Binuwanan isab e'na h'llana, ati kinakan e'na.",
        7: "Aubus pa'in sigām amangan, magtūy aniya' panayu sigām in sigām anantang sali'-sali'. Manjari angā' sigām dahun kayu igira tinuhug-tuhug e' sigām nihinang panambun.",
        8: "Na, akohap-kohap pa'in lahat, takale e' sigām bahonos PANGHŪ' Tuhan pal'ngngan min deyom kakabbunan e'. Magtūy sigām patapuk karuwangan ma deyom kakayu-kayuhan supaya mbal ta'nda' e' Tuhan.",
        9: "Sagō' angalingan PANGHŪ' Tuhan ma l'lla, yukna, “Maingga na ka?”",
        10: "Ya sambung l'lla, “Takaleku bahonosnu mailu ma kabbun ati tināw aku ma sabab anantang aku. Angkan aku patapuk.”",
        11: "Atilaw Tuhan, yukna, “Sai bay amata'u ka'a ya ka'a ilu anantang? Bay ka makakakan bahā' min buwa' kayu, ya bay pangalānganku ma ka'a?”",
        12: "Yuk sambung l'lla, “O'o, ya d'nda bay pamalimbangnu aku, iya ya bay amuwanan aku, angkan aku bay makakakan.”",
        13: "Tinilaw d'nda isab e' PANGHŪ' Tuhan, yukna, “Angay ka makahinang buwattilu?” Ya sambung d'nda, “O'o, ya sowa e'. Pinarupang aku e'na, ya angkan aku makakakan.”",
        14: "Manjari amissala PANGHŪ' Tuhan ma sowa he', yukna, “Pagka tahinangnu ina'an-i, ka'a ya taluwa' mulka' labi lagi' min kamemon sattuwa maka hayop. Sat'ggolnu allum palele du ka maka b'ttongnu, bagunbun isab ya pagkakannu.",
        15: "Pagbantata ka maka d'nda itu. Panubu'nu maka panubu'na magbanta du saumul-umul. Kōknu ya gini'ikan e' panubu'na, maka buli' tape'na ya tanghabnu.”",
        16: "Amissala isab Tuhan ma d'nda, yukna, “Na, buwattitu pangangganta'ku ma ka'a, ganapanku to'ongan kasusahannu bang ka ab'ttong, kap'ddi'an to'ongan ka bang ka anganak. Daipara minsan buwattē', h'llanu ya kabilahiannu na pa'in, maka iya ya makapagbaya' ma ka'a.”",
        17: "Ya pamissala Tuhan ma l'lla, “Ka'a isab, ma sabab kapameya'nu ma lling h'ndanu, ati kakannu buwa' kayu ya bay pangalānganku ka'a, Na, sapdahanku tana' ma sababannu. Subay ka kahunitan to'ongan amiha kalluman min tana' sat'ggolnu allum.",
        18: "Patomo' kasagmotan indaginis ma tana'nu, kasagmotan aheka itingna. Jari maghulas-sangsā' du ka supaya aniya' takakannu sampay ni llaw pamole'nu ni deyom tana'. Tana' asal bay pamapanjarihan ka'a, maka tana' ya pamole'annu.”",
        19: "Patomo' kasagmotan indaginis ma tana'nu, kasagmotan aheka itingna. Jari maghulas-sangsā' du ka supaya aniya' takakannu sampay ni llaw pamole'nu ni deyom tana'. Tana' asal bay pamapanjarihan ka'a, maka tana' ya pamole'annu.”",
        20: "Manjari ya pangōn si Adam ma h'ndana ‘Hawa’.",
        21: "Na, aniya' kuwit hayop nihinang s'mmek e' PANGHŪ' Tuhan panambun baran si Adam maka h'ndana.",
        22: "Manjari angallam PANGHŪ' Tuhan, yukna, “In manusiya' itu sali' kita na, pagka makata'u na ahāp-ala'at. Mbal iya makajari ama'abut tanganna ang'ttu' buwa' kayu ya makabuwan kallum. Mbal iya subay pinarūl allum salama-lama.”",
        23: "Angkan na disi Adam pinaluwas e' PANGHŪ' Tuhan min kabbun Eden. Sinō' iya maghuma ma tana' bay pangahinangan iya.",
        24: "Tapaluwas pa'in, aniya' mala'ikat taga-pikpik pinat'nna' e' Tuhan ma bihing kabbun Eden inān tampal ni sobangan. Aniya' isab pinat'nna' maina'an dakayu' kalis magsuleyab keyatna. Maglabad sadja, supaya halam aniya' palabayan tudju ni po'on kayu ya makabuwan kallum salama-lama.",
    },
    4: {
        1: "Na, maghulid na si Adam maka h'ndana si Hawa, jari ab'ttong iya ati anganak l'lla, ōnna si Kabil. Ya lling si Hawa, “Min tabang-tulung PANGHŪ' -Yawe kabuwanan aku anak l'lla.”",
        2: "Puwas e' ab'ttong si Hawa pabīng ati anganak isab l'lla, ōnna si Habil. Na, asangpot pa'in sigām, si Habil tahinang a'a magi'ipat bili-bili, bo' si Kabil ya tahinang a'a maghuhuma.",
        3: "Na, ta'abut pa'in ajatu tanoman si Kabil, aniya' saga buwa' binowa e'na panukbalna ni PANGHŪ'.",
        4: "Ya tinukbal e' si Habil dakayu' bili-bili ya bay dahū nianakan ma ba'anan bili-bilina. Sinumbali' e'na bo' yampa tukbalanna ni PANGHŪ' isina ya ahāp to'ongan. Na, kasulutan PANGHŪ' ma hinang si Habil buwattē' ati tinaima' tutukbalanna.",
        5: "Malaingkan si Kabil maka saga buwa' ya tutukbalanna halam tinaima' e' Tuhan. Jari akagit magtūy atay si Kabil, ala'at isab s'mmuna.",
        6: "Manjari ah'lling PANGHŪ' ma si Kabil, yukna, “Otō', angay akagit ataynu? Angay angkan ala'at s'mmunu?",
        7: "Bang taluwa' hinangnu tantu du aku kasulutan ma ka'a. Damikiyanna bang mbal taluwa', na, ilu mailu dusa angagad anasat ma ka'a. Ya kabaya'anna subay ang'ntanan ka'a, sagō' subay atuhannu.”",
        8: "Manjari itu ah'lling si Kabil ma siyalina si Habil, yukna, “Otō', sūng kita pehē' ni huma.” Ma huma pa'in, binono' si Habil e' si Kabil pinapatay.",
        9: "Atilaw PANGHŪ' ma si Kabil, yukna, “Maingga siyalinu?” Ya sambung si Kabil, “Sitta'a. Angay? Hinangku bahā' anganjagahan danakanku?”",
        10: "Manjari ah'lling PANGHŪ', yukna, “Angay angkan tahinangnu ilu-i! Sumbang ko' ilu! O'ō, ilu laha' siyalinu sapantun a'a mikibalos ma aku min deyom tana'.",
        11: "Na, taluwa' sapda du ka. Mbal na ka makabāk kalluman min tana' ilu sabab kasobsoban na e' laha' siyalinu.",
        12: "Minsan buwattingga pagtuyu'nu maghinang ma tana', mbal ajatu tinanomnu. Maglunsulan sadja ka pi'ingga-pi'ingga ma dunya itu, sagō' mbal ka makabāk lahat pat'ttogannu.”",
        13: "Ah'lling si Kabil ma PANGHŪ', “Arōy! Abuhat makalandu' ya paniksa'nu ma aku!",
        14: "Itiya' aku pala'annu min tana' bay paghuma'anku, maka palawaknu aku min matahannu. Halam du aniya' lahat pat'ttoganku ma dunya itu, tahinang aku a'a magsampig-manampig sadja. Bang aku ganta' talanggal e' sai-sai, binono' du aku pinapatay.”",
        15: "Sagō' ya sambung PANGHŪ' ma iya, “Mbal du. Bang aniya' amono' ka'a subay iya binalosan min pitu'.” Magtūy aniya' gindan pinat'nna' e' PANGHŪ' ma si Kabil supaya iya takilā e' sai-sai makalanggal ma iya. Hatina mbal iya makajari binono'.",
        16: "Manjari itu ala'an na si Kabil min alopan PANGHŪ' pehē' ni lahat Nōd ma dambila' Eden tampal ni sobangan, ati mahē' iya pat'nna'.",
        17: "Na, magdakayu' si Kabil maka h'ndana ati angiram iya. Maka'anak iya l'lla ōnna si Idris. Manjari si Kabil ya bay makahinang kauman, niōnan e'na Idris buwat ōn anakna he'.",
        18: "Si Idris itu taga-anak l'lla, ōnna si Irad ya mma' si Mihuja'il. Si Mihuja'il taga-anak isab l'lla, ōnna si Mitusail ya mma' si Lamek.",
        19: "Si Lamek itu duwa h'ndana, si Ada maka si Silla.",
        20: "Manjari anganak si Ada l'lla, ōnna si Jabal. Si Jabal itu panagna'an saga manusiya' magi'ipat hayop maka magluma' tolda ma masa awal e'.",
        21: "Aniya' isab siyali si Jabal ōnna si Jubal. Si Jubal ya panagna'an manusiya' apanday magsuling maka maggitara.",
        22: "Na, si Silla isab anganak l'lla, ōnna si Tubal-Kabil. Apanday iya magsasal tumbaga maka basi' nihinang kapanyapan kaginisan. Aniya' isab siyali si Tubal-Kabil d'nda, ōnna si Na'ama.",
        23: "Manjari amissala si Lamek ma saga h'ndana, yukna, “O Ada, O Silla, ka'am h'ndaku, kalehunbi kabtanganku. Bay aku makapatay subul ma sabab kapangalagutna ma aku.",
        24: "Na, bang bineya' bissala Tuhan ma si Kabil in iya subay binalosan min pitu', ya lagi'na bang aniya' amono' aku, a'a inān subay binalosan min pitumpū' maka pitu'.”",
        25: "Jari maghulid isab si Adam maka h'ndana, ati kabuwanan na isab sigā anak l'lla. Yuk si Hawa, “Itiya' aku pinasuku'an anak l'lla e' Tuhan, pangangganti' ma si Habil ya bay binono' e' si Kabil.” Sakali niōnan e'na Sēt.",
        26: "Na, si Sēt taga-anak l'lla ōnna si Enos. Masa si Enos e', ya na masa panagna'an manusiya' anabbut ōn Yawe pagtuhanan sigām.",
    },
    5: {
        1: "Ya na itu salsila panugsugan si Adam. Ma waktu pamapanjari Tuhan ma manusiya' bay sigām pina'anggil ma iya.",
        2: "Pinapanjari sigām e'na d'nda maka l'lla. Binarakatan sigām e'na ati manusiya' ya pangōnna ma sigām.",
        3: "Na, pagabut dahatus maka t'llumpū' tahun umul si Adam, aniya' anakna l'lla an'ppu iya, ōnna si Sēt.",
        4: "Aubus pa'in min bay panganak ma si Sēt, aniya' gi' walu' hatus tahun umul si Adam, maka aniya' gi' anakna d'nda-l'lla.",
        5: "Manjari pagabut siyam hatus maka t'llumpū' tahun umul si Adam, awapat na iya.",
        6: "Na si Sēt isab, dahatus pa'in maka limantahun umulna, aniya' anakna l'lla, ōnna si Enos.",
        7: "Aubus pa'in min bay panganak ma si Enos e', aniya' gi' walu' hatus maka pituntahun umul si Sēt, maka aniya' gi' anakna d'nda-l'lla.",
        8: "Jari pagabut siyam hatus maka sangpū' maka duwantahun umul si Sēt, amatay na iya.",
        9: "Na, si Enos isab, pagabut siyampū' tahun umulna, taga-anak iya l'lla, ōnna si Kenan.",
        10: "Aubus pa'in min bay panganak ma si Kenan, aniya' gi' walu' hatus maka sangpū' maka limantahun umul si Enos, maka aniya' lagi' anakna d'nda-l'lla.",
        11: 'Na, pagabut siyam hatus maka limantahun umul si Enos, amatay na iya.',
        12: "Si Kenan isab, pagabut umulna pitumpū' tahun, aniya' anakna l'lla, ōnna si Mahalalel.",
        13: "Aubus pa'in min bay panganak ma si Mahalalel, aniya' gi' walu' hatus maka mpatpū' tahun umul si Kenan, maka aniya' lagi' anakna d'nda-l'lla.",
        14: "Jari pagabut siyam hatus maka sangpū' tahun umul si Kenan, amatay na iya.",
        15: "Si Mahalalel isab, pagabut nnompū' maka limantahun umulna, taga-anak iya l'lla, ōnna si Jared.",
        16: "Aubus pa'in min bay panganak ma si Jared e', aniya' gi' walu' hatus maka t'llumpū' tahun umul si Mahalalel, maka aniya' lagi' anakna d'nda-l'lla.",
        17: "Jarina, pagabut walu' hatus maka siyampū' maka limantahun umul si Mahalalel, amatay na iya.",
        18: "Na, si Jared isab, pagabut dahatus maka nnompū' maka duwantahun umulna, aniya' anakna l'lla, ōnna si Idris.",
        19: "Manjari aubus pa'in min bay panganak ma si Idris, aniya' gi' walu' hatus tahun umul si Jared, maka aniya' lagi' anakna d'nda-l'lla.",
        20: "Manjari pagabut siyam hatus maka nnompū' maka duwantahun umul si Jared, amatay na iya.",
        21: "Si Idris isab, pagabut umulna nnompū' maka limantahun, taga-anak iya l'lla, ōnna si Mitusala.",
        22: "Puwas e', ma deyom t'llu hatus tahun, magda'atay si Idris maka Tuhan. Aniya' gi' isab saga anakna d'nda-l'lla. Sakali itu, ta'abut pa'in t'llu hatus maka nnompū' maka limantahun umulna, palanyap sadja iya pagka niā' e' Tuhan.",
        23: "Puwas e', ma deyom t'llu hatus tahun, magda'atay si Idris maka Tuhan. Aniya' gi' isab saga anakna d'nda-l'lla. Sakali itu, ta'abut pa'in t'llu hatus maka nnompū' maka limantahun umulna, palanyap sadja iya pagka niā' e' Tuhan.",
        24: "Puwas e', ma deyom t'llu hatus tahun, magda'atay si Idris maka Tuhan. Aniya' gi' isab saga anakna d'nda-l'lla. Sakali itu, ta'abut pa'in t'llu hatus maka nnompū' maka limantahun umulna, palanyap sadja iya pagka niā' e' Tuhan.",
        25: "Na si Mitusala isab, pagabut umulna dahatus maka walumpū' maka pituntahun, taga-anak iya l'lla, ōnna si Lamek.",
        26: "Aubus pa'in min bay panganak ma si Lamek, aniya' gi' pitu' hatus maka walumpū' maka duwantahun umul si Mitusala, maka taga-anak lagi' iya d'nda-l'lla.",
        27: "Jari ta'abut pa'in siyam hatus maka nnompū' maka siyam tahun umul si Mitusala, amatay na iya.",
        28: "Si Lamek isab, pagabut umulna dahatus maka walumpū' maka duwantahun, taga-anak iya l'lla.",
        29: "Ya pangōnna ma iya Nū ati aniya' pagkallam si Lamek ma pasalna. “Onde' itu,” yukna, “amowa kahāpan du luwas min tana' ya bay sinapdahan e' PANGHŪ', jari kabuwanan kitam pahalian min hulas-sangsā'tam.”",
        30: "Aubus pa'in min bay panganak ma si Nū, aniya' gi' lima hatus maka siyampū' maka limantahun umul si Lamek, maka aniya' gi' anakna d'nda-l'lla.",
        31: "Manjari pagabut pitu' hatus maka pitumpū' maka pituntahun umul si Lamek, amatay na iya.",
        32: "Na, in si Nū itu, aniya' na lima hatus tahun umulna bo' yampa iya taga-anak. Manjari t'llu anakna l'lla, ya na si Sēm, si Hām maka si Japet.",
    },
    6: {
        1: "Manjari itu, salta' angaheka na bangsa manusiya' ma deyom dunya, aniya' isab anak sigām budjang.",
        2: "Ta'nda' pa'in saga budjang itu e' kal'llahan ya ngga'i ka a'a dunya, na, kalingkatan sigām. Jari sasuku budjang kinabaya'an e' saga l'lla inān, ningā' h'nda e' sigām.",
        3: "Manjari angallam PANGHŪ' -Yawe, yukna, “Mbal na pataptap Rū-ku ma saga manusiya' itu, subay sigām buwananku ganta'an. Mbal na pinalabi umul sigām min dahatus maka duwampū' tahun.”",
        4: "Na, ma waktu he'-i sampay ma tahun damuli gi' minnē', aniya' maitu ma dunya saga a'a kosogan maka alanjang, ya niōnan bangsa Nipilim. Aesog sigām maka abantug ma kalahat-lahatan. Panubu' asal sigām min saga l'lla ngga'i ka a'a dunya ya bay makah'nda budjang a'a dunya.",
        5: "Na, in binangsa manusiya' ma dunya itu ta'nda' e' PANGHŪ' ap'nno' e' dusa maka ala'at lullun hona'-hona' sigām.",
        6: "Pag'nda'na, magkarukka'an iya ati magsusun na ma pasal pamapanjarina manusiya' maitu ma dunya.",
        7: "Angkan angallam PANGHŪ', yukna, “Pahalamku na binangsa manusiya' ya bay papanjariku. Pahalamku sigām sampay ba'anan sattuwa maka hayop, pahalamku isab ai-ai maglelehan maka manuk-manuk magleyangan. Sababna magsusun to'ongan aku ma bay papanjariku.”",
        8: "Daipara pag'nda' PANGHŪ' ma si Nū, kasulutan iya.",
        9: "Ya itu salsila panugsugan si Nū. T'llu du anakna l'lla, ya si Sēm, si Hām maka si Japet. Luwal si Nū halam dusahan ma waktu he'-i, magda'atay isab iya maka Tuhan.",
        10: "Ya itu salsila panugsugan si Nū. T'llu du anakna l'lla, ya si Sēm, si Hām maka si Japet. Luwal si Nū halam dusahan ma waktu he'-i, magda'atay isab iya maka Tuhan.",
        11: "Malaingkan saga pagkahina manusiya' kumarukan kala'atan sigām ma matahan Tuhan. Ap'nno' deyom dunya e' kajahulaka'an sigām.",
        12: "Angkan ta'nda' e' Tuhan in dunya itu alumu' na ma sabab kasabulan ya nihinang e' saga manusiya' kamemon.",
        13: "Manjari magkallam Tuhan ma si Nū, yukna, “Pahalamku na saga manusiya' kamemon ma sabab kajahulaka'an sigām maingga-maingga ma dunya. Pagmulka'anku na sigām kamemon, maka lubuku isab sampay baran dunya.",
        14: "Na, angahinang na ka adjung ma ka'am,” yukna ma si Nū. “Subay kayu apagon ya pangahinangnu. Hinangin saga bilik ma deyom, bo' kitlanun lullun deyom-luwasanna.",
        15: "Ya sukuranna subay buwattitu: taha'na pitumpū' maka limand'ppa, luhana sangpū' maka duwand'ppa maka tonga', maka langkawna subay pitund'ppa maka tonga'.",
        16: "Hinangin olangan duwa h'kka langana ma llot diyata' dinding maka bihing atop. Hinangin t'llu angkap, angkap deyo', angkap t'ngnga' maka angkap diyata'. Hinangin isab dakayu' lawang ma bihingna.",
        17: "Hatiun pahāp,” yuk Tuhan. “Itiya' na aku song amaniya' latap ma kaluha'an dunya itu pamahalamku kamemon indaginis, sasuku taga-napas. Manjari kamemon ai-ai ma dunya itu amatay du.",
        18: "Malaingkan pat'nna'anta ka paljanji'an, in ka'am magtai'anak sampay ayuwannu d'nda pariyata' du ni adjung ya hinangnu ilu.",
        19: "Subay duwa'nu isab min ba'anan ai-ai taga-napas bo' pinakallum sambeya' maka ka'am. Patimuk du ni ka'am kamemon ginisan manuk-manuk, kamemon ginisan sattuwa maka hayop, sampay ginisan ai-ai maglelehan ma tana'. Magbeya' du sigām duwa-ruwa maglimbang.",
        20: "Subay duwa'nu isab min ba'anan ai-ai taga-napas bo' pinakallum sambeya' maka ka'am. Patimuk du ni ka'am kamemon ginisan manuk-manuk, kamemon ginisan sattuwa maka hayop, sampay ginisan ai-ai maglelehan ma tana'. Magbeya' du sigām duwa-ruwa maglimbang.",
        21: "Bowahun isab takakan indaginis. Tau'un pagkakanbi maka pagkakan saga sattuwa maka hayop maka kamanuk-manukan.”",
        22: "Manjari bineya' e' si Nū kamemon bay panoho'an Tuhan ma iya.",
    },
    7: {
        1: "Na, aubus pa'in nihinang adjung e', magsuwala PANGHŪ' -Yawe ma si Nū, yukna, “Pariyata' na kam magtai'anak, sabab hal ka'a ya ta'nda'ku halam dusahan ma kaluha'an dunya.",
        2: "Pasambeya'un ma ka'am kamemon ginisan hayop halal, pitu' l'lla pitu' d'nda ma ginis-ginisanna. Bang sattuwa ya mbal tahalal, duwa-ruwa sadja ya niruwa', dakayu' l'lla dakayu' d'nda maglimbang.",
        3: "Damikiyanna du isab ginisan manuk-manuk, pitu' l'lla pitu' d'nda ma ginis-ginisanna. Hinangun buwattilu supaya aniya' anatas allum min ginisan binangsa ai-ai kamemon bo' angaheka du pa'in pabalik ma kaluha'an dunya.",
        4: "Pitung'llaw minnitu patumbukku ulan alandos ma deyom mpatpū' ng'llaw, mpatpū' bahangi. Jari pahalamku na kamemon taga-napas ya bay papanjariku.”",
        5: "Na, bineya' e' si Nū kamemon bay panoho'an PANGHŪ' ma iya.",
        6: "Ta'abut pa'in kapangalatap dunya, aniya' na nnom hatus tahun umul si Nū.",
        7: "In iya maka anak-h'ndana sampay ayuwanna d'nda bay pariyata' ni adjung bo' mbal ta'abut e' latap.",
        8: "Manjari patimuk ni si Nū kamemon ginisan hayop maka sattuwa, halal maka ngga'i ka halal, sampay saga manuk-manuk maka kamemon maglelehan ma kuwit tana', duwa-ruwa maglimbang. Pariyata' na kamemon ni deyom adjung e' buwat bay panoho'an Tuhan ma si Nū.",
        9: "Manjari patimuk ni si Nū kamemon ginisan hayop maka sattuwa, halal maka ngga'i ka halal, sampay saga manuk-manuk maka kamemon maglelehan ma kuwit tana', duwa-ruwa maglimbang. Pariyata' na kamemon ni deyom adjung e' buwat bay panoho'an Tuhan ma si Nū.",
        10: "Sakali itu, ta'abut pa'in pitung'llaw minnē', yampa patumbuk ulan.",
        11: "Pagabut pa'in nnom hatus tahun si Nū, bulan karuwana, sangpū' maka pitu' kasobangan ma tahun ina'an, abustak kamemon tuburan bohe' ya asal ma deyom tana'. Taukab isab taplok langit bo' patumbuk ulan alandos.",
        12: "Halam aniya' hondonganna ma deyom mpatpū' bahangi.",
        13: "Ma llaw katagna' ulan inān, ina'an asal disi Nū ma deyom adjung, iya maka h'ndana sampay saga anakna t'llungan si Sēm, si Hām maka si Japet sampay h'nda sigām.",
        14: "Tabeya' isab ma sigām kamemon ginisan sattuwa maka hayop aheya-ariki', sattuwa talun maka hayop ni'ipat, sampay saga maglelehan ma tana'. Tabeya' isab kamemon ginisan manuk-manuk maka ai-ai magleyangan.",
        15: "Manjari aniya' patipun ni si Nū l'lla maka d'nda maglimbang min binangsa kaginisan kamemon sasuku taga-napas, pinariyata' ni adjung.",
        16: "Ya na ina'an panoho'an Tuhan asal ma si Nū inān. Na, mahē' pa'in sigām kamemon ma deyom adjung, magtūy sigām tinambolan lawang e' PANGHŪ' -Yawe.",
        17: "Ma deyom mpatpū' bahangi pasōng na pa'in latap e', pasōng palalom bohe', sampay pagūng na adjung e'.",
        18: "Pasōng palalom bohe' sampay talaran na adjung.",
        19: "Palalom na pa'in bo' palalom bohe', sampay aletop na kamemon saga kabūd-būran.",
        20: "Palalom na pa'in bohe' sampay pa'abut saga mpat d'ppa lalomna min diyata' saga pussuk būd.",
        21: "Manjari maglembohan to'ongan sasuku bay taga-napas ma dunya, ba'anan kamanuk-manukan, kasattuwahan talun, kahayop-hayopan maka ai-ai maglelehan ma tana'. Magpatayan kamemon sampay binangsa manusiya'.",
        22: "Kamemon ai-ai bay taga-napas ma gintana'an wa'i magpatayan lullun.",
        23: "Alaglag sasuku taga-napas kamemon, saga manusiya', kasattuwahan, kamanuk-manukan maka saga ai-ai maglelehan ma kuwit tana'. Ya du takapin allum si Nū maka saga kamemon bay ameya' ma iya ma deyom adjung.",
        24: "Na, in latap inān halam bay pakō' ma deyom dahatus maka limampū' bahangi.",
    },
    8: {
        1: "Malaingkan nientom e' Tuhan disi Nū sampay saga sattuwa maka hayop ya ma deyom adjung, ati aniya' baliyu akosog pinatiyup e' Tuhan, manjari pakulang bohe' he'.",
        2: "Tinambol pabīng e' Tuhan saga bohe' bay min deyom tana' maka bohe' min langit bo' pahondong na angulan.",
        3: "In bohe' latap-i pakō'-kō' na pa'in ma deyom dahatus maka limampū' bahangi.",
        4: "Sakali itu, ta'abut pa'in bulan kapitu'na ma tahun e'-i, sangpū' maka pitu' kasobangan, yamboho' sumanglad adjung e' pehē' ni dakayu' būd ma jadjahan Ararat.",
        5: "Pakō'-kō' na pa'in bohe' sampay ni panagna'an bulan ma bulan sangpū' he', jari ta'nda'an di-na na saga pussuk kabūd-būran.",
        6: "Na, palabay pa'in mpatpū' bahangi min bay katuwa' pussuk būd e', niukab e' si Nū tandawan bay tahinangna ma adjung",
        7: "bo' paleyangna dakayu' owak ni luwasan. Jari paleyang na pa'in owak e' pi'ingga-pi'ingga sampay aniya' katoho'an pat'ppakanna.",
        8: "Mbal at'ggol pinaleyang na isab e' si Nū dakayu' assang bo' kata'uwanna bang pakō' na bohe' min kareyahan.",
        9: "Sagō' masi aletop e' bohe', maka assang e' mbal makabāk pat'ppakanna. Manjari paleyang pabīng ni adjung. Na niabut e' si Nū assang e' labay min tandawan bo' pinasōd pabīng ni deyom adjung e'.",
        10: "Angagad lagi' si Nū pitumbahangi bo' yampa paleyangna assang e' pabīng.",
        11: "Pagkohap pa'in, na, ilu na assang pabalik ni iya, ananga' dahun kayu jaitun baha'u bay k'ttu'na. Minnē' kinata'uwan agtūy e' si Nū ya bohe' latap pakō' na.",
        12: "Angagad gi' iya pitumbahangi bo' yampa paleyangna assang e' pabīng. Jari ma l'ngngan itu halam na makabīng ni adjung.",
        13: "Ta'abut pa'in nnom hatus maka dantahun umul si Nū, bo' sahali bulan ma bulan dakayu' ma tahun e'-i, pakō' na latap. Manjari nila'anan e' si Nū sapaw adjung e'. Ang'nda' iya paluwas ati ta'nda'na atoho'-toho' na kuwit tana'.",
        14: "Ta'abut pa'in ni t'llu kamatayan bulan ma bulan karuwana, atoho' na to'ongan.",
        15: 'Manjari magkallam Tuhan ma si Nū, yukna,',
        16: "“Pareyo' na kam magtai'anak maka saga ayuwannu.",
        17: "Pareyo'un isab ma ka'am saga kamanuk-manukan kamemon maka kahayop-hayopan, maka ai-ai maglelehan ma tana', supaya anganak paheka ma kaluha'an dunya itu.”",
        18: "Manjari magdeyo'an na si Nū maka anak-h'ndana sampay ayuwanna.",
        19: "Pareyo' du isab saga kahayop-hayopan maka saga kamanuk-manukan sampay ai-ai maglelehan ma tana'. Pareyo' sigām daginis maka daginis.",
        20: "Manjari amangkat batu si Nū nihinang pagkukulbanan ni PANGHŪ' -Yawe. Pagubus, angā' iya hayop maka manuk-manuk halal daginis maka daginis. Sinumbali' e'na bo' yampa tinunu' ma pagkukulbanan.",
        21: "Kasulutan PANGHŪ' ma hamut kukulbanan inān, manjari yukna ma deyom atayna, “Mbal na pagmulka'anku pabalik dunya itu ma sababan manusiya', minsan ala'at asal hona'-hona' sigām sangay min kanahut sampay ni kaheya sigām. Mbal na paka'atku pabīng kamemon ya sasuku taga-napas buwat bay hinangku itu.",
        22: "Sat'ggol anatas dunya itu, sat'ggol isab mags'lle'-s'lle' musim maka waktu, musim pagtanom maka musim pagani, waktu haggut maka waktu pasu', pang'llaw maka pangulan, llaw maka sangom.”",
    },
    9: {
        1: "Manjari si Nū maka saga anakna l'lla binarakatan na e' Tuhan. Magkallam iya ma sigām, yukna, “Anganak kam paheka supaya ap'nno' e'bi kaluha'an dunya ilu.",
        2: "Ka'am ilu kinatāwan du e' kamemon sattuwa maka hayop, manuk-manuk maka ai-ai maglelehan ma tana', sampay saga daing. Buwananta kam kapatut magdūl-baya' ma sigām.",
        3: "Manjari takakanbi na ai-ai taga-napas ilu. Ma waktu dahū inān, tinanom ya bay pamuwanku ma ka'am, sagō' buwattitu pamuwanku na kamemon.",
        4: "“Saguwā' aniya' pangalānganku ma ka'am subay mbal kakanbi, ya na sumbali'an halam tapaluwas laha'na, sabab laha' ya pameya'an nyawa.",
        5: "Damikiyanna laha'bi manusiya', pameya'an nyawa isab angkan subay tinungbasan to'ongan. Sai-sai a'a amahuddud laha' pagkahina manusiya' sampay amatay, tungbasanku du. Minsan sattuwa, bang aniya' amapatay ma manusiya', subay du papatayku.",
        6: "Sabab aku ya bay amapanjari manusiya' pina'anggil ni aku, angkan na bang aniya' a'a amahuddud laha' pagkahina, binalosan du a'a inān, pinahuddud isab laha'na e' pagkahina manusiya'.",
        7: "Na, ka'am ilu subay anganak paheka supaya asaplag kaluha'an dunya e' saga panubu'bi magsuring-magsaingsing.”",
        8: "Manjari itu magkallam isab Tuhan ma si Nū maka saga anakna l'lla, yukna,",
        9: "“Itiya' aku amat'nna' paljanji'anku ma ka'am sampay ma saga panubu'bi magpangkat-mamangkat.",
        10: "Ya du ai-ai taga-napas kamemon ya bay tabeya' ma ka'am ma adjung e', talapay du isab pinat'nna'an paljanji'an, ai na ka manuk-manuk, ai na ka hayop, ai na ka sattuwa.",
        11: "Ya na itu pagkallamku pasal paljanji'anku ma ka'am: tinagna'an minnitu in dunya itu mbal na taluwa' latap pabalik, maka ai-ai taga-napas kamemon mbal du alaglag e' latap.",
        12: "Aniya' isab tanda' palsaksi'an pat'nna'ku ma ka'am magtubu'-manubu' sampay ma sasuku taga-napas kamemon.",
        13: "Pat'nna'ku biradaliku ma kagabunan, bo' aniya' paltanda'an pamaentom saga manusiya' ma pasal paljanji'anku ma kamemon ya ma dunya.",
        14: "Bang pa'andomku lahat bo' aniya' biradali patuwa' min deyom andom,",
        15: "entomku du paljanji'anku ma ka'am saga manusiya' sampay ma kamemon taga-napas mailu ma dunya. Janji'anta kam, halam na aniya' latap makalaglag pabīng.”",
        16: "Yuk Tuhan isab, “Bang patuwa' biradali ma kagabunan sumiyan-sumiyan, nda'ku maka entomku paljanji'anku ma ai-ai taga-napas ma babaw dunya, paljanji'an anatas ni kasaumulan.”",
        17: "Buwattē' pagkallam Tuhan ma si Nū, yukna, “Ya na ina'an tanda' sin paljanji'an ya tahinangku ma sasuku taga-napas mailu ma dunya.”",
        18: "Na, saga anak si Nū ya bay sehe'na ma adjung e', ya na disi Sēm, si Hām maka si Japet. (Si Hām ya mma' si Kana'an.)",
        19: "In anak si Nū kat'llungan itu, ya na pang'mbo'an ma kamemon manusiya' ya pasaplag ma kaluha'an dunya.",
        20: "Na si Nū itu a'a maghuhuma asal, jari anagna' iya magtanom anggul.",
        21: "Manjari itu, aniya' inuman makalango nihinang e' si Nū min bohe' anggul e'. Paginumna, nilango iya ati ahurusan di-na saga s'mmekna. Ati pabahak iya anantang ma deyom tolda ya pagluma'anna.",
        22: "Mahē' pa'in iya pabahak, makasōd pehē' anakna si Hām, ya mma' si Kana'an. Manjari tapandang e'na harapan mma'na. Pagpandangna itu, magtūy iya paluwas anuli-nulihan saga danakanna",
        23: "si Sēm maka si Japet. Sigā duwangan itu bay angā' s'mmek magtūy. Pinasablay ma baha sigā bo' yampa pasōd dahū bukut anambunan mma' sigā. Halam sigā palingi' bo' mbal ta'nda' kaiya'anna.",
        24: "Na, pagsayu si Nū min bay kalangona, bo' kata'uwanna bay hinang anakna kasiyalihan ma iya,",
        25: "magtūy pabukaganna. Yukna, “Si Kana'an itu t'kkahan sukna'. Tahinang iya ata ma deyo'an saga danakanna.”",
        26: "Ah'lling isab si Nū, “Pudjiku PANGHŪ' ya pagtuhanan si Sēm! Bang pa'in pa'ata ni iya si Kana'an sampay panubu'na.",
        27: "Si Japet isab, bang pa'in angaluha paglahatan saga panubu'na. Bang pa'in sigām palamud sangkahāpan ma saga panubu' si Sēm. Bang pa'in isab pa'ata ni sigām si Kana'an maka panubu'na.”",
        28: "Na, damuli pa'in min latap e' aniya' gi' t'llu hatus maka limampū' tahun kallum si Nū.",
        29: "Ta'abut pa'in siyam hatus maka limampū' tahun umulna, awapat na iya.",
    },
    10: {
        1: "Ya na itu salsila panugsugan si Sēm, si Hām maka si Japet, ya anak si Nū. Aniya' na anak sigām puwas bay min latap.",
        2: "Na, ya na itu saga anak si Japet l'lla, maka ōn bangsa isab ya patubu' min sigām: si Gomer, si Magog, si Maday, si Jaban, si Tubal, si Mesek maka si Tiras.",
        3: "Tubu'an si Gomer ya na saga a'a Askenas, a'a Ripat maka a'a Togarma.",
        4: "Tubu'an si Jaban ya na saga a'a Elisa, Tarsis, Kīt, maka Rodan.",
        5: "Manjari tubu'an si Jaban tahinang saga bangsa ya maglahat ma bihing tahik maka ma kapū'-pū'an. Kaniya-kaniya sigām magsaddī-saddī lahat maka bahasa sigām.",
        6: "Na, ya na itu saga anak si Hām l'lla, maka ōn bangsa isab ya patubu' min sigām: si Kūs, si Misil, si Pūt maka si Kana'an.",
        7: "Tubu'an si Kūs, ya na saga a'a Seba, Habila, Sabta, Ra'ama maka Sabteka. Tubu'an si Ra'ama isab ya na saga a'a Seba maka Dedan.",
        8: "Aniya' isab anak si Kūs dakayu', ōnna si Nimrud. In si Nimrud itu dahū min a'a kamemon akosog angagaw lahat maitu ma dunya.",
        9: "Abantug isab iya ma sabab kosogna magpana' sattuwa. Angkan na pinagbahasa h'lling itu, “Bang pa'in ka pasali' ni si Nimrud ya akosog magpapana' ma sabab tabang min PANGHŪ' -Yawe.”",
        10: "Na, ya tagna'an da'ira pinagbaya'an e' si Nimrud itu, ya na Babilon, Erek, Akkad maka Kalne, ya bay mahē' ma lahat Babilon.",
        11: "Pinaluha isab pagnakura'na sampay ni lahat Assiriya ati mahē' iya amahinang da'ira Niniba maka Rehobot-Ēl maka Kala.",
        12: "Bay pahinangna isab da'ira Resen ma tonga'an Niniba maka Kala, ya da'ira aheya ōnna.",
        13: "Manjari panubu' si Misil isab, ya na saga a'a Lūd, Anam, Lehab, Naptu,",
        14: "Patrus, Kaslu maka Kiriti. A'a Kiriti itu ya na paluwasan bangsa Pilistin.",
        15: "Si Kana'an taga-anak l'lla, si Sidun ya siyaka, bo' pasunu' si Hīt.",
        16: "Si Kana'an isab ya pang'mbo'an saga a'a Jibus, Amor, Gilgas,",
        17: 'Hīb, Arka, Sīn,',
        18: "Arbad, Semar maka Hamat. Pasaplag asal saga bangsa paltubu'an si Kana'an itu,",
        19: "min lahat Sidun sampay ta'abut lahat Gerar ya ma kasekotan lahat Gasa. Pasampay isab sigām tudju ni lahat Sodom, Gomora, Adma maka Seboyim, ya ma kasekotan lahat Lasa.",
        20: "Na, ya du ilu saga panubu' si Hām ya tahinang palbangsa-bangsahan. Kaniya-kaniya sigām magsaddī-saddī lahat maka bahasa.",
        21: "Na, si Sēm isab, siyaka si Japet, ya na pang'mbo'an si Eber sampay panubu'na kamemon.",
        22: "Saga anak si Sēm l'lla ya na si Elam, si Assur, si Alpaksad, si Lūd maka si Aram.",
        23: "Saga panubu' si Aram ya na saga a'a Ūs, Hūl, Geter maka Mesek.",
        24: "Manjari si Alpaksad ya mma' si Sela, bo' si Sela ya mma' si Eber.",
        25: "Si Eber itu duwa anakna l'lla. Ya pangōn ma anakna dangan inān si Peleg sabab binangsa manusiya' bay abahagi' ma deyom masana. Si Joktan ya danakan si Peleg.",
        26: "Manjari ya panubu' si Joktan ya na saga a'a Almodad, Selep, Hasamabet, Jera,",
        27: 'Hadoram, Usal, Dikla,',
        28: 'Obal, Abimail, Seba,',
        29: "Opir, Habila, maka Jobab. Panubu' si Joktan asal sigām kamemon itu.",
        30: "Ya paglahatan sigām ma lahat Mesa sampay ta'abut lahat Separ, ya lahat kabūd-būran tampal ni sobangan.",
        31: "Ya na ina'an saga panubu' si Sēm. Kaniya-kaniya sigām magsaddī-saddī lahat maka bahasa.",
        32: "Na, panubu' si Nū saga a'a kamemon ya tasabbut inān, kaniya-kaniya sigām magsaddī-saddī panugsugan. Lāgi, damuli pa'in min latap, pasaplag ma dunya saga kabangsa-bangsahan kamemon, luwas min panganak si Nū.",
    },
    11: {
        1: "Na, ma masa awal e' dakayu' du bahasa pah'lling saga manusiya' kamemon ma sakalingkal dunya.",
        2: "Maglatun-latun na pa'in sigām ma lahat sobangan sampay ta'abut e' sigām karatagan aluha ma lahat Babilon.",
        3: "Maina'an pa'in, magisun-isun sigām, yuk-i, “Sūng kitam angahinang tisa' paheka, tinapa ma api bo' patuwas.” Ngga'i ka batu ya ginuna e' sigām pangahinang luma' sagō' tisa' pinagpikit maka kitlan.",
        4: "Yuk sigām isab, “Gom na kitam maghinang da'ira taga-luma' pamantawan. Pamantawan itu subay alangkaw to'ongan sa'agon-agon maka'abut langit. Manjari abantug kitam, maka mbal tapulak-palik ni mpat pidju alam.”",
        5: "Manjari pareyo' PANGHŪ' -Yawe pina'an ang'nda' da'ira maka luma' pamantawan ya nihinang e' saga a'a inān.",
        6: "“Na,” yukna, “Dabangsa asal manusiya' itu kamemon, maka bahasa sigām dakayu' du isab, ya angkan sigām makarapat angahinang da'ira buwattitu. Tagna'anna sadja ko' itu, gana-gana angahinang du sigām ai-ai kamaksuran sigām.",
        7: "Gom gi' kita patulun pehē' amapaglamud-lamugay bahasa sigām pakaniya-kaniya supaya sigām mbal maghati-hiyatihi dansehe'an.”",
        8: "Manjari kinanat-kanat e' PANGHŪ' saga manusiya' kamemon ni mpat pidju alam ati pahali sigām maghinang da'ira he'.",
        9: "Ya he' sababna angkan lahat inān niōnan Babel sabab ya ina'an lahat paglamud-lamugayan bahasa saga manusiya', lahat isab pagkanat-kanatan sigām e' PANGHŪ' ni kalahat-lahatan ma mpat pidju alam.",
        10: "Na, balikta salsila panugsugan si Sēm. Duwantahun palabay min bay latap ma dunya, bo' dahatus tahun na umul si Sēm, aniya' anakna l'lla ōnna si Alpaksad.",
        11: "Palabay pa'in min bay kapaganak ma si Alpaksad aniya' gi' lima hatus tahun umul si Sēm, maka aniya' lagi' anakna d'nda-l'lla bo' yampa iya amatay.",
        12: "Na si Alpaksad isab, pagabut t'llumpū' maka limantahun umulna, aniya' anakna l'lla ōnna si Sela.",
        13: "Palabay pa'in min kapaganak ma si Sela, aniya' gi' mpat hatus maka t'lluntahun umul si Alpaksad, maka aniya' lagi' anakna d'nda-l'lla bo' yampa iya amatay.",
        14: "Na si Sela isab, pagabut t'llumpū' tahun umulna, aniya' anakna l'lla ōnna si Eber.",
        15: "Puwas e', aniya' gi' mpat hatus maka t'lluntahun umul si Sela, maka aniya' lagi' anakna d'nda-l'lla bo' yampa iya amatay.",
        16: "Na si Eber isab, pagabut t'llumpū' maka mpat tahun umulna, taga-anak iya l'lla ōnna si Peleg.",
        17: "Palabay pa'in min bay kapaganak ma si Peleg, aniya' gi' mpat hatus maka t'llumpū' tahun umul si Eber maka aniya' lagi' anakna d'nda-l'lla bo' yampa iya amatay.",
        18: "Na si Peleg isab, pagabut t'llumpū' tahun umulna, taga-anak iya l'lla ōnna si Riyu.",
        19: "Palabay pa'in min bay kapaganak ma si Riyu, aniya' gi' duwa hatus maka siyam tahun umul si Peleg, maka aniya' lagi' anakna d'nda-l'lla bo' yampa iya amatay.",
        20: "Na si Riyu isab, ta'abut pa'in umulna t'llumpū' maka duwantahun, taga-anak iya l'lla ōnna si Serog.",
        21: "Palabay pa'in min bay kapaganak ma si Serog, aniya' gi' duwa hatus maka pituntahun umul si Riyu. Taga-anak lagi' iya d'nda-l'lla bo' yampa iya amatay.",
        22: "Na, ta'abut pa'in t'llumpū' tahun umul si Serog, aniya' anakna l'lla ōnna si Nahor.",
        23: "Palabay pa'in min bay kapaganak ma si Nahor, aniya' gi' duwa hatus tahun umul si Serog. Taga-anak lagi' iya d'nda-l'lla bo' yampa iya amatay.",
        24: "Na si Nahor isab, ta'abut pa'in umulna duwampū' maka siyam tahun, aniya' anakna l'lla ōnna si Tera.",
        25: "Manjari min bay kapaganak ma si Tera, aniya' gi' dahatus maka sangpū' maka siyam tahun umul si Nahor. Taga-anak gi' iya d'nda-l'lla bo' yampa iya amatay.",
        26: "Na si Tera itu, pitumpū' tahun umulna bo' yampa iya taga-anak. Si Ibram ya anakna siyaka, bo' pasunu' si Nahor, bo' si Haran ya kasiyalihan.",
        27: "Na, ya na itu salsila pasal si Tera maka saga panubu'na. Si Tera itu mma' disi Ibram, si Nahor maka si Haran. Si Haran itu aniya' anakna ōnna si Lōt.",
        28: "Saguwā' ma allum lagi' mma'na si Tera, amatay na si Haran ma lahat Uru, ya lahat paglahatan bangsa Kaldiya, lahat bay kapanganakan iya asal.",
        29: "Na si Ibram maka si Nahor taga-h'nda karuwangan. Si Saray ya h'nda si Ibram, sagō' halam aniya' anak sigā sabab si Saray mbal to'ongan maka'anak. Si Milka anak si Haran ya h'nda si Nahor. Aniya' danakan si Milka niōnan si Iska.",
        30: "Na si Ibram maka si Nahor taga-h'nda karuwangan. Si Saray ya h'nda si Ibram, sagō' halam aniya' anak sigā sabab si Saray mbal to'ongan maka'anak. Si Milka anak si Haran ya h'nda si Nahor. Aniya' danakan si Milka niōnan si Iska.",
        31: "Manjari magla'anan na disi Tera min Uru ya bay paglahatan bangsa Kaldiya. Tabeya' ma iya anakna si Ibram maka mpuna si Lōt anak si Haran. Tabeya' isab ayuwanna si Saray h'nda si Ibram. Ya tinudju e' sigām lahat Kana'an sagō' at'kka pa'in sigām ni da'ira Haran, mahē' sigām maglahat.",
        32: "Na, kat'ddasan sigām ma Haran sampay amatay na si Tera, duwa hatus maka limantahun umulna.",
    },
    12: {
        1: "Na aniya' palman PANGHŪ' -Yawe ma si Ibram, yukna, “Ala'an ka min lahatnu luggiya' ilu. Ala'an ka min saga lūng-kampungnu maka min okoman mma'nu bo' ka pehē' ni lahat dakayu' ya pa'nda'anku ni ka'a ma sinosōng.",
        2: "Hinangta ka po'onan bangsa aheya maka abantug. Buwananta ka kahāpan maka pabantugku ōnnu. Saga pagkahinu manusiya' isab kabuwanan kahāpan ma sababnu.",
        3: "Sasuku anabbut ōnnu ni kahāpan buwananku isab kahāpan. Sasuku anabbut ōnnu ni kala'atan pagmulka'anku du. Manjari saga kabangsa-bangsahan kamemon maitu ma dunya pinasuku'an kahāpan ma sababnu.”",
        4: "Sakali ta'abut pa'in pitumpū' maka limantahun umul si Ibram, ala'an iya min lahatna Haran tudju ni lahat Kana'an, buwat bay panoho'an PANGHŪ' ma iya. Ameya' isab si Lōt.",
        5: "Manjari ya binowa e' si Ibram h'ndana si Saray, kamanakanna si Lōt, sampay saga ata bay b'llina ma lahat Haran. Binowa isab pangalta'na kamemon bay tausahana mahē'.",
        6: "Na pagt'kka sigām ni lahat Kana'an, nilanjalan na pa'in l'ngngan sigām sampay ta'abut kayu pagduwa'ahan ma More, ma tongod lahat Sekem. (Kabangsa-bangsahan Kana'an ya tag-lahat ma masa inān.)",
        7: "Manjari magpa'nda' PANGHŪ' ma si Ibram bo' magkallam ma iya, yukna, “Ma sinosōng pamuwanku lahat Kana'an itu ma saga panubu'nu.” Magtūy si Ibram angahinang tambak batu panukbalanna kulban tudju ni PANGHŪ', ya bay magpa'nda' ma iya.",
        8: "Puwas e' palanjal iya tudju ni kabūran ma jadjahan Betel tampal ni sobangan. Mahē' iya pahanti' ma tonga'an kauman Betel maka kauman Ayi. Aniya' isab panukbalan kulban tahinangna maina'an pagsumbahanna ni PANGHŪ'.",
        9: "Puwas e' pauntas na si Ibram tudju ni lahat Negeb.",
        10: "Na aniya' gotom maina'an ma lahat Kana'an, asigpit to'ongan, angkan palūd disi Ibram ni lahat Misil bo' pahanti' mahē'.",
        11: "Manjari itu, song pa'in sigām at'kka ni lahat Misil, ah'lling si Ibram ma h'ndana si Saray, yukna, “Saray, ka'a ilu ahāp d'nda.",
        12: "Bang ka ganta' ta'nda' e' saga a'a Misil, kinata'uwan e' sigām in ka'a h'ndaku. Jari pinapatay aku e' sigām bo' ka'a ya pinakallum.",
        13: "Gom na yuknu ma sigām magdanakan kita, supaya aku kinahāpan e' sigām ma sababnu. Manjari aku itu mbal ni'inay.”",
        14: "Na, pagt'kka sigām ni lahat Misil, bo' pag'nda' saga a'a maina'an ma si Saray, b'nnal alingkat.",
        15: "Ta'nda' pa'in iya e' saga a'a pangandolan Pira'un, magtūy sigām angahaka pehē' ni Pira'un-i pasal kalingkatna. Sakali binowa si Saray pehē' ni deyom astana'.",
        16: "Bo' si Ibram ya kinahāpan e' Pira'un ma sabab si Saray. Binuwanan iya ba'anan bili-bili, kambing, sapi', kura' maka unta', sampay isab saga ata d'nda-l'lla.",
        17: "Sagō' in Pira'un pinat'kkahan saki aheya e' PANGHŪ' ma sabab pangā'na ma si Saray. Talapay isab saga a'a kamemon ma deyomanna.",
        18: "Angkanna pinalinganan si Ibram e' Pira'un bo' tilawna bang ai sababna. “Angay aku putingannu?” yuk Pira'un. “Angay aku halam pata'unu in iya h'ndanu?",
        19: "Yuknu ma aku in si Saray ilu danakannu, angkan iya arak ta'ā'ku h'nda. O'o, h'ndanu itu, ā! Ngā'un iya pabalik bo' kam ala'an minnitu!”",
        20: "Manjari magpanoho'an Pira'un ma saga tendogna ma pasal disi Ibram. Sinō' iya pinala'an ma sigām min lahat Misil, iya baranna maka h'ndana sampay ai-aina kamemon.",
    },
    13: {
        1: "Manjari ala'an na disi Ibram min lahat Misil bo' pabīng ni Negeb mahē' ma lahat Kana'an. Ameya' isab h'ndana maka pangalta'na kamemon sampay isab kamanakanna si Lōt.",
        2: "Magkarayahan na to'ongan si Ibram. Aheka to'ongan ba'anan kahayop-hayopanna maka aheka isab pamulawanna indaginis.",
        3: "Manjari palintas sigām min Negeb bo' maglatun-latun tudju ni kauman Betel, ni bay pahanti'an sigām tagna' ma tonga'an Betel maka da'ira Ayi.",
        4: "Asal aniya' bay maina'an pagtukbalan kulban bay tahinang e' si Ibram ma waktu palabay. Maina'an isab iya anabbut ma ōn Yawe.",
        5: "Na si Lōt isab, ya sehe' si Ibram maglatun-latun, aniya' anak-h'ndana maka saga sosoho'anna. Aheka isab kahayopanna, saga kambing, bili-bili maka sapi'.",
        6: "Jari aheka sidda kahayopan sigām karuwangan, angkan mbal s'ddong ma kaparangan lahat inān bang masi na pa'in sigām dambeya'an.",
        7: "Ya he' sababna angkan magsasaw saga magi'ipat hayop si Ibram maka saga a'a magipat hayop si Lōt. Masi isab aniya' saga a'a bangsa Kana'an maka bangsa Peres maglahat maina'an ma masa disi Ibram inān.",
        8: "Sakali si Ibram bay amowa si Lōt maggara', yukna, “Otō', dalaha' du kita angkan aku mbal bilahi bang aniya' pagsasawan, ai na ka ma kita, atawa ma saga tendogta.",
        9: "Gom kita magokat sabab aluha lahat itu. Ka'a ya amene' maingga-maingga kabaya'annu paglahatan. Bang kabaya'annu tana' tampal ni gibang, ma aku na tampal ni kowan. Bang kabaya'annu tana' tampal ni kowan, ma aku na tampal ni gibang.”",
        10: "Na amantaw si Lōt ni kapantayan ma bihing sapa' Jordan tobtob ni lahat Sowar. Pag'nda'na ma kapantayan inān, na, aheka bohe'na, buwat lahat Eden ya bay pinaniya' e' PANGHŪ' ma awal jaman. Dahāp isab maka lahat Misil. (Ma waktu ītu halam gi' bay minulka'an e' PANGHŪ' da'ira Sodom maka Gomora.)",
        11: "Manjari ya tapene' e' si Lōt palsuku'anna tana' kapantayan kamemon ya ma bihing sapa' Jordan. Pagubus, papinda na iya pehē' tudju ni sobangan. Na buwattē' ya kapag'bba si Ibram maka si Lōt.",
        12: "Si Ibram ya pat'nna' maina'an ma kabūran lahat Kana'an, bo' si Lōt ya pat'nna' ma kapantayan asekot ni da'ira Sodom. Mahē' na iya amat'ngge tolda pagluma'an sigām.",
        13: "Na, saga a'a Sodom itu asal jahulaka' maka lumandu'an dusa sigām ni si Yawe.",
        14: "Makala'an pa'in si Lōt, angallam PANGHŪ' -Yawe ma si Ibram, yukna, “Ang'nda' ka ni katilibutnu ilu.",
        15: "Ya kaluha'an lahat ta'nda'nu ilu, pamuwanku du ma ka'a sampay ma saga panubu'nu salama-lama.",
        16: "Buwananta ka tubu' paheka, mbal taitung, sapantun heka gusung ma gintana'an.",
        17: "Na, pehē' na ka, latagun kaluha'an lahat ilu, sabab pamuwanku du ma ka'a ma sinosōng.”",
        18: "Jari papinda si Ibram pehē' ni Hebron, ati mahē' iya maglahat ma tongod saga kakayuhan Mamre, ya pagduwa'ahan a'a kasehe'an. Aniya' isab pagtunu'an kulban nihinang e' si Ibram maina'an panumbahanna ni PANGHŪ'.",
    },
    14: {
        1: "Na, ma masa he', aniya' mpat sultan magbono' maka lima pagkahi sigām sultan. Ya itu ōn mpat sultan maka lahat bay pagnakura'an sigām: si Amdapel sultan min lahat Babilon, si Areyok sultan min da'ira Ellasal, si Kedollomer sultan min Elam, maka si Tidal sultan min Goyem. Aniya' isab lima sultan saddī ya kuntara sigām: si Bera sultan min da'ira Sodom, si Bilsa sultan min da'ira Gomora, si Sinab sultan min Adma maka si Semeber sultan min Seboyim. Kalimana sultan min kauman Bela (hatina Sowar).",
        2: "Na, ma masa he', aniya' mpat sultan magbono' maka lima pagkahi sigām sultan. Ya itu ōn mpat sultan maka lahat bay pagnakura'an sigām: si Amdapel sultan min lahat Babilon, si Areyok sultan min da'ira Ellasal, si Kedollomer sultan min Elam, maka si Tidal sultan min Goyem. Aniya' isab lima sultan saddī ya kuntara sigām: si Bera sultan min da'ira Sodom, si Bilsa sultan min da'ira Gomora, si Sinab sultan min Adma maka si Semeber sultan min Seboyim. Kalimana sultan min kauman Bela (hatina Sowar).",
        3: "Na, lima sultan itu bay amatimuk kasundaluhan sigām ma Kapantayan-Siddim, ya niōnan isab Tahik Ma'asin.",
        4: "Sangpū' maka duwantahun ya t'ggol sigām ma pang'ntanan sultan Kedollomer, sagō' ta'abut pa'in sangpū' ka t'lluntahun, anawakkal sigām angatu ma iya.",
        5: "Na, ta'abut pa'in sangpū' maka mpat tahun, at'kka pina'an si Kedollomel maka saga sultan ya gapi'na. Jari tara'ug e' sigām bangsa Repa ma lahat Asterot Karnaim, tara'ug bangsa Sūs ma lahat Hām, maka bangsa Ēm ma Kapantayan Kiriyataim.",
        6: "Tara'ug isab bangsa Hōr ma kabūd-būran lahat Se'er ati taturul sigām sampay ta'abut jadjahan Elparan ya ma bihing lahat paslangan.",
        7: "Puwas e', pabīng isab saga sundalu disi Kedollomel inān pehē' ni lahat Kades, ya bay pinagōnan En-Mispat ma waktu tagna'. Tara'ug isab e' sigām bangsa Amalek, ati ta'agaw kaluha'an lahat sigām. Ya du bangsa Amor ya maglahat ma da'ira Hasason-Tamar, ka'agawan isab.",
        8: "Na, balikta sultan lima hekana, hatina sultan min da'ira Sodom, min Gomora, min Adma, min Seboyim maka min Bela. Bay sigām magtimuk ma Kapantayan-Siddim magbono'",
        9: "maka si Kedollomel sultan Elam maka saga sultan ya gapi'na. Ya na si Tidal sultan Goyem, si Amdapel sultan ma lahat Babilon, maka si Areyok sultan Ellasal. Hatina lima sultan min dambila', mpat isab min dambila'.",
        10: "Aheka asal lowang ma Kapantayan-Siddim e', ap'nno' e' kitlan. Na, maglahian pa'in sultan Sodom maka sultan Gomora min pagbono'an, aniya' saga tendog sigām bay ahūg ni deyom lowang e', maka aniya' isab bay makalahi pehē' ni kabūd-būran.",
        11: "Manjari itu, anganda'ug pa'in saga sultan mpat hekana he', ta'agaw e' sigām kamemon pangalta' maka balanja' bay ma deyom da'ira Sodom maka da'ira Gomora. Pagubus, magla'anan sigām minnē'.",
        12: "Tabowa isab e' sigām si Lōt kamanakan si Ibram, iya baranna sampay alta'na kamemon, pagka da'ira Sodom ya paglahatanna.",
        13: "Sakali itu aniya' a'a makal'ppa min pang'ntanan disi Kedollomel amowa lapal ni si Ibram, ya bangsa Hibrani. Ina'an iya maglahat ma tongod kakayuhan pagduwa'ahan, ya ma si Mamre a'a bangsa Amor. Aniya' isab danakan si Mamre, si Eskol maka si Aner. Pagapi' asal sigām magdanakan itu ma si Ibram.",
        14: "Na, pagta'u si Ibram wa'i tasaggaw kamanakanna si Lōt, magtūy iya amatipun saga tendogna ya bay asal ma deyomanna, a'a ata'u magbono'. T'llu hatus maka sangpū' maka walu' puhu' ya heka sigām. Atimuk pa'in, magtūy sigām paturul ni mpat sultan inān sampay ta'abut lahat Dān.",
        15: "Sangom pa'in, pinagbahagi' e' si Ibram saga tendogna bo' parugpak ni kuntara sigām. Aga'os disi Ibram inān ati anurul saga kuntara sigām sampay ni kauman Hoba, ya ma dambila' da'ira Damaskus tampal ni uttala'.",
        16: "Ta'abut pa'in kauman Hoba, magtūy ta'ā' pabalik saga pangalta' kamemon bay tataban e' mpat sultan e'. Ta'ā' isab pabīng e' si Ibram kamanakanna si Lōt maka alta'na, sampay saga kar'ndahan maka a'a kasehe'an ya bay tasaggaw inān.",
        17: "Sakali tara'ug e' si Ibram sultan Kedollomel maka saga sultan gapi'na. Ma labayan pa'in iya tudju amole', bo' ta'abut L'bbak Sabe, ya pinagōnan isab L'bbak sin Kasultanan, sinampang iya e' sultan min da'ira Sodom.",
        18: "Sinampang isab iya e' si Malkisadik, sultan ma lahat Salem maka imam maghinang ni Tuhan Mahatinggi. Aniya' tinapay maka binu-anggul binowa e'na pangalabotna ma si Ibram,",
        19: "bo' yampa angamu'-amu'an iya kahāpan, yukna, “Bang pa'in si Ibram kabuwanan kahāpan e' Tuhan Mahatinggi, ya magpapanjari dunya maka langit!",
        20: "Pudjiku Tuhan Mahatinggi, ya bay anukbal saga bantanu ni deyom pang'ntanannu!” Manjari saga alta' bay ta'agaw pabīng e' si Ibram, binahagi' e'na pasangpū', ati dabahagi' he' pangahulmatna ma si Malkisadik.",
        21: "Ah'lling isab sultan min da'ira Sodom ma si Ibram, yukna, “Ma ka'a na kamemon pangalta'ku ilu. Sagō' amu'ku pole'in sadja ni aku saga tendogku ya bay tabowanu pal'ppa ilu.”",
        22: "Ya sambung si Ibram, “Saksi'ku si Yawe, ya Tuhan Mahatinggi bay magpapanjari dunya maka langit. Bay aku makasapa ma iya,",
        23: "mbal aku anaima' ai-ai palsuku'annu, minsan la'a dalamba salbannu atawa engkot taumpa'nu bo' mbal ka makapah'lling ka'a ya bay makaparaya ma aku.",
        24: "Mbal aku anambut ai-ai min ka'a, luwal ya bay panganggastu saga a'aku. Sagō' aniya' a'a bay makarapit ma aku amono', ya na disi Aner, si Eskol maka si Mamre. Patut sigām pinahampitan.”",
    },
    15: {
        1: "Pagubus ina'an-i, takale e' si Ibram suwala PANGHŪ' -Yawe magkallam ma iya hinabuna atuli, yuk-i, “O Ibram, da'a ka tināw. Aku ya anampanan ka'a, sali' hantang taming. Ahāp to'ongan panungbasku ma ka'a.”",
        2: "Anambung si Ibram, yukna, “O Yawe, ka'a Panghū'ku, ai pūsna bang aku tungbasannu bo' halam aniya' anakku? Ya pinusaka'an alta'ku ya na si Ele'eser, a'a Damaskus.",
        3: "Halam aku bay buwanannu anak, angkan dakayu' ipatanku itu ya pinasuku'an pusaka'.”",
        4: "Na, takalena suwala PANGHŪ' pabīng, yukna, “Ngga'i ka ipatannu ya pamusaka'annu, sagō' anaknu lissi.”",
        5: "Sakali binowa iya e' Tuhan paluwas min luma'na bo' ah'lling ma iya, yuk-i, “Pahangad ka ni diyata' langit, sulayin ni'itung saga bitu'un ilu. Saheka-heka taitungnu ilu, ya isab heka panubu'nu.”",
        6: "Na, am'nnal to'ongan si Ibram ma pangallam PANGHŪ' e'. Jari minnē', min pam'nnalna, kasulutan Tuhan ma iya ati ni'itung iya a'a abontol.",
        7: "Magkallam isab Tuhan ma si Ibram, yukna, “Aku si Yawe, ya Tuhan bay amowa ka'a pi'itu min Uru lahat bangsa Kaldiya bo' supaya pamasuku'ku lahat itu ma ka'a.”",
        8: "Atilaw gi' si Ibram ma PANGHŪ', yukna, “O Yawe, ka'a Tuhanku, buwattingga e'ku makatantu in lahat itu ma aku du?”",
        9: "Anambung PANGHŪ', yukna, “Angā' ka dakayu' sapi' d'nda, dakayu' kambing d'nda maka dakayu' bili-bili l'lla, t'llu-t'llun tahun pangumulanna. Angā' ka isab dakayu' manuk-manuk malapati maka dakayu' anak assang ati bowahun pi'itu ni aku.”",
        10: "Jari binowa saga hayop itu ni Tuhan e' si Ibram. Binila' duwa bo' yampa pinapagalop bila'anna. Sagō' halam binila' saga manuk-manuk, hal pinat'nna' sadja.",
        11: "Sakali aniya' saga belle' pat'ppak ma sumbali'an inān arak amangan, daipara tin'ggal e' si Ibram.",
        12: "Pags'ddop mata llaw tatuli si Ibram, ahaluk to'ongan tulina. Kal'ddoman iya sidda maka sinōd tāw aheya.",
        13: "Manjari angallam PANGHŪ' ma iya, yukna, “Ma tahun sinōng in panubu'nu tahinang a'a liyu ma lahat ngga'i ka lahat sigām. Tahinang sigām banyaga' ma lahat e' ati pinissoko' sigām to'ongan ma deyom mpat hatus tahun.",
        14: "Saguwā',” yuk Tuhan, “pat'kkaku mulka' ma bangsa ya amanyaga' sigām. Ta'abut pa'in waktu katulak sigām min lahat inān, makabowa du isab sigām alta' lumandu'an hekana.",
        15: "Sagō' in pasalnu, Ibram, pataha'ku du umulnu ati amatay du ka ma deyom kasannangan, maka takubul ka pahāp.",
        16: "In pasal panubu'nu isab, subay palabay mpat masa bo' yampa sigām pabīng ni lahat Kana'an itu sabab in paldusahan bangsa Amor subay pinajukup dahū.”",
        17: "Manjari, pas'ddop pa'in llaw bo' angal'ddom na lahat, aniya' sali' hantang lapohan maka suwariyan palabay ma tonga'an saga sumbali'an bay pinagdambila' inān. Maghumbu asal lapohan maka arokot suwariyan.",
        18: "Magtūy ma waktu ina'an, aniya' paljanji'an pamat'nna' e' PANGHŪ' ma si Ibram, yuk-i, “Pamuwanku du katibu'ukan lahat itu ma saga panubu'nu, tobtob min sapa' lahat Misil sampay ni sapa' Alpurati ya sapa' aheya.",
        19: "Tabeya' isab tana' saga bangsa Kēn, Kenes, Kadmon,",
        20: 'Hīt, Pirissi, Repa,',
        21: "Amor, Kana'an, Gilgas maka Jibus.”",
    },
    16: {
        1: "Na, si Saray h'nda si Ibram halam anakan. Sagō' aniya' ipatanna d'nda Misil, ōnna si Hajara.",
        2: "Manjari itu, ta'abut pa'in sangpū' tahun kapaglahat si Ibram ma Kana'an, ah'lling ma iya si Saray, yukna, “Kahandak min PANGHŪ' ya angkan aku mbal maka'anak. Bang bahā' hulidnu ipatanku itu. Kalu aniya' anakku labay min iya.” Kasulutan isab si Ibram ma h'lling si Saray. Jari binowa e' si Saray ipatanna si Hajara pamah'ndana ma h'llana.",
        3: "Manjari itu, ta'abut pa'in sangpū' tahun kapaglahat si Ibram ma Kana'an, ah'lling ma iya si Saray, yukna, “Kahandak min PANGHŪ' ya angkan aku mbal maka'anak. Bang bahā' hulidnu ipatanku itu. Kalu aniya' anakku labay min iya.” Kasulutan isab si Ibram ma h'lling si Saray. Jari binowa e' si Saray ipatanna si Hajara pamah'ndana ma h'llana.",
        4: "Manjari maghulid si Ibram maka si Hajara ati angiram na iya. Makananam pa'in si Hajara in iya angiram na, magtūy pareyo'-deyo'na si Saray.",
        5: "Anumbung magtūy si Saray ma si Ibram, yukna, “Dusanu ya angkan aku pinareyo'-deyo' e' si Hajara itu. Ya b'nnalna, aku ya bay amuwan iya ma ka'a. Sagō' pagta'una ab'ttong na iya, mbal na iya magaddat ma aku. Na, baya'-baya' si Yawe angahukum ma kita duwangan.”",
        6: "Anambung si Ibram, yukna, “Ipatannu ko' ilu, baya'-baya'nu na minsan ai hinangnu ma iya.” Manjari alahi si Hajara pagka kinabigsi'an e' si Saray.",
        7: "Sakali itu, hinabu si Hajara ma lahat paslangan, tabāk iya e' mala'ikat PANGHŪ' ma atag dakayu' tuburan bohe', ina'an ma labayan tudju ni lahat Sūr.",
        8: "Ya lling mala'ikat ma iya, “O Hajara, ka'a ipatan si Saray, bay ka minningga? Maka pi'ingga isab ka?” Ya sambung si Hajara, “Itiya' aku alahi min si Saray ya bay pagipatanku.”",
        9: "Yuk mala'ikat-i, “Subay ka amole' pehē' ni nakura'nu magpa'ata ma iya pabīng.”",
        10: "Ah'lling isab mala'ikat ma si Hajara, yukna, “Buwananta ka tubu' paheka, mbal taitung hekana.",
        11: "Ilu ka ab'ttong, jari anganak du ka l'lla. Si Isma'il ya pangōnnu iya sabab takale e' PANGHŪ' kasusahannu.",
        12: "Malaingkan anaknu ilu tahinang sali' kura' talun mbal tasoho'. Pinagsagga' e'na saga pagkahina manusiya', maka anagga' isab saga a'a kamemon ma iya. Jari mbal iya makapagdakayu' lahat maka saga kakampunganna.”",
        13: "Yuk si Hajara ma deyom atayna, “Arī! Masi bahā' aku allum minsan ta'nda'ku Tuhan?” Manjari ya pangōnna ma PANGHŪ' ya bay ah'lling ma iya, “Tuhan ya Maka'nda' ma aku.”",
        14: "Angkan na tuburan bohe' inān pinagōnan Be'er-Lahai-Ruwi, hatina ‘Bohe' Tuhan ya Maka'nda' ma aku.’ Bohe' itu, ina'an ma tonga'an lahat Kades maka kauman Bered.",
        15: "Na anganak na si Hajara, angkan aniya' anak si Ibram l'lla. Si Isma'il ya pangōn si Ibram ma iya.",
        16: "Walumpū' maka nnom tahun ya umul si Ibram ma waktu panganak si Hajara ma si Isma'il-i.",
    },
    17: {
        1: "Manjari pagabut siyampū' maka siyam tahun umul si Ibram, magpa'nda' PANGHŪ' -Yawe ma iya. “Aku ya Tuhan Sangat Kawasa,” yukna. “Beya'un panoho'anku, maka pabontolun isab hinangnu kamemon,",
        2: "ati tumanku paljanji'anku ma ka'a. Pahekaku to'ongan isab paltubu'annu.”",
        3: 'Na, pasujud magtūy si Ibram. Ya palman Tuhan ma iya,',
        4: "“Buwattitu ya paljanji'anku ma ka'a, hinangta ka pagmatto'ahan ma kabangsa-bangsahan.",
        5: "Maka pindahanku isab ōnnu. Puwas itu ngga'i ka na si Ibram ya pangōn ka'a, sagō' si Ibrahim na, sabab hinangta ka pagmatto'ahan saga bangsa kaginisan.",
        6: "Aho', pahekaku to'ongan saga panubu'nu ati tahinang sigām kabangsa-bangsahan. Ma sinosōng isab aniya' saga sultan patubu' min ka'a.",
        7: "Pahogotku to'ongan paljanji'anku itu ma ka'a sampay ma saga panubu'nu magpangkat-mamangkat. Janji' itu mbal magbaluba ni kasaumulan. Aku ya Tuhannu, maka pagtuhanan saga panubu'nu.",
        8: "In katibu'ukan lahat Kana'an itu, ya paghanti'annu ma buwattina'an, pamuwanku du ma ka'a sampay ma saga panubu'nu saumul-umul. Aku ya pagtuhanan sigām.”",
        9: "Magkallam isab Tuhan ma si Ibrahim, yukna, “Na ka'a isab, subay bogbogannu paljanji'anta itu, damikiyanna isab saga panubu'nu magpangkat-mamangkat salama-lama.",
        10: "Buwattitu ya pamogbogbi ma janji' pagsulutanta itu, kamemon kal'llahan ma deyomanbi subay ni'islam.",
        11: "Ya du ilu tanda' ma paljanji'an ya pagsulutanta itu, in ka'am kal'llahan subay ni'islam.",
        12: "Puwas min waktu itu sampay ma waktu sinōng, in l'lla kamemon ya nianakan ma deyomanbi tahun ni tahun, ai na ka anakbi, ai na ka isab anak ata, subay ni'islam bang ta'abut walung'llaw ma luwasan.Ya du isab saga ata bay b'llinu min a'a liyu subay ni'islam isab. Aho',” yuk Tuhan, “kamemon kal'llahanbi ilu subay ni'islam, manjari aniya' pangilāhan ma baranbi in janji' pagsulutanta itu kakkal saumul-umul.",
        13: "Puwas min waktu itu sampay ma waktu sinōng, in l'lla kamemon ya nianakan ma deyomanbi tahun ni tahun, ai na ka anakbi, ai na ka isab anak ata, subay ni'islam bang ta'abut walung'llaw ma luwasan.Ya du isab saga ata bay b'llinu min a'a liyu subay ni'islam isab. Aho',” yuk Tuhan, “kamemon kal'llahanbi ilu subay ni'islam, manjari aniya' pangilāhan ma baranbi in janji' pagsulutanta itu kakkal saumul-umul.",
        14: "Saguwā' sai-sai l'lla halam taislam, mbal iya taitung suku'ku sabab halam bogboganna paljanji'anku itu.”",
        15: "Magkallam lagi' Tuhan ma si Ibrahim, yukna, “Na, ya pasal h'ndanu si Saray, ngga'i na ka si Saray ya pangōnnu iya puwas itu, sagō' si Sara na.",
        16: "Buwananku iya kahāpan bo' aniya' anaknu l'lla min iya. Aho', tantu iya buwananku kahāpan manjari tahinang iya ina' ma kabangsa-bangsahan. Aniya' isab saga sultan luwas min panubu'na.”",
        17: "Na, pasujud magtūy si Ibrahim maka e'na anittowa. Yukna ma baranna, “Arī! Makabuwan tubu' gi' bahā' bang a'a dahatus tahun umulna? Maka'anak bahā' si Sara minsan siyampū' tahun umulna!”",
        18: "Yukna isab ma Tuhan, “O Tuhan, bang pa'in mura-murahan pagka'inagonannu anakku si Isma'il!”",
        19: "Anambung Tuhan ma si Ibrahim, “Aho', makajari. Sagō' aniya' du anaknu l'lla min h'ndanu si Sara. Si Isa'ak ya pangōnnu iya. Pahogotku paljanji'anku ma iya sampay ma paltubu'anna salama-lama.",
        20: "Na, ya pasal si Isma'il, takaleku isab bay pangamu'nu-i. Buwananku iya kahāpan, pahekaku panganakna bo' aheka to'ongan saga panubu'na. Manjari aniya' sangpū' a'a min panubu'na makapagdatu' ma sinosōng. Saga panubu'na isab nihinang e'ku bangsa ga'osan.",
        21: "Saguwā' anaknu si Isa'ak ya pahogotanku janji'ku. Nianakan du iya e' si Sara ma tahun balik sali' bulan itu.”",
        22: "Aubus pa'in e' Tuhan amalman ma si Ibrahim, magtūy iya ala'an.",
        23: "Na ma llaw ina'an-i, bineya' e' si Ibrahim panoho'an Tuhan ma iya. Taislam e'na anakna si Isma'il sampay kal'llahan kamemon ma deyomanna. Ya du isab saga ata bay nianakan ma deyomanna sampay saga ata bay tab'llina.",
        24: "Ya umul si Ibrahim ma waktu pagislam ma iya maka si Isma'il, siyampū' maka siyam tahun.",
        25: "Ya umul si Isma'il sangpū' maka t'lluntahun.",
        26: "Jari magdongan si Ibrahim maka anakna si Isma'il ni'islam ma dang'llaw du.",
        27: "Tabeya' isab ni'islam ma llaw ina'an-i saga atana kamemon, a'a bay nianakan ma deyomanna sampay ata bay tab'llina.",
    },
    18: {
        1: "Manjari aniya' llaw magpa'nda' PANGHŪ' -Yawe ma si Ibrahim ma tongod kakayuhan pagduwa'ahan, ina'an ma tana' si Mamre. Alanga na llaw, maka ina'an si Ibrahim aningkō'-ningkō' ma bowa' lawang luma'na tolda.",
        2: "Na, ta'nda' e'na t'llungan a'a an'ngge-n'ngge ma dahuanna. Pag'nda'na itu, magtūy iya magdai'-dai' anampang sigām, maka e'na pasujud.",
        3: "Yukna ma sigām, “Saga tuwan, pahapit gi' kam ni luma' kami minsan mbal na apatut.",
        4: "Pabowahanta kam bohe' pangose' tape'bi bo' kam pahali-hali ma sindungan kayu itu.",
        5: "Bowahanta pa'in kam saga pagkakan isab minsan mbal na apatut. Subay na ahāp palasahanbi pabīng bo' yampa kam palanjal ni pal'ngngananbi.” Ya sambung sigām ma si Ibrahim, “Aho', magsukul.”",
        6: "Na, magdai'-dai' si Ibrahim pasōd ni deyom luma' tolda angalinganan si Sara. “Dāng,” yukna, “angā' ka tirigu ahāp, t'llu t'ppongna, bo' ka angahinang tinapay. Dai'-dai'un pa'in.”",
        7: "Pagubus, magdai'-dai' si Ibrahim pehē' ni buluyan hayopna amene' dakayu' anak sapi' ahāp isina. Sinoho' sinumbali' ma sosoho'anna bo' niadjal saru'un-du'un.",
        8: "Jari asakap pa'in kamemon, binowa e' si Ibrahim gatas maka sapi' pangalabotna ma saga a'a-i. Hinabu sigām amangan, si Ibrahim magbaran amuhatan sigām ma lindung kayu.",
        9: "Na, tinilaw e' sigām si Ibrahim, “Ma'ai h'ndanu si Sara?” Ya sambung si Ibrahim, “Ina'an ma deyom.”",
        10: "Manjari angallam PANGHŪ' -Yawe, “Ma tahun sinōng ilu, buwat bulan itu, pabalik du aku pi'itu. H'ndanu si Sara anganak du, l'lla ya anakna.” Na maina'an asal si Sara pakale-kale ma bukut lawang.",
        11: "Ato'a iya, mbal na pinaglaha'. Maka si Ibrahim isab, ato'a na asal.",
        12: "Angkanna, pagkale si Sara ma bissala inān, tatittowa iya ati yukna ma deyom atayna, “Ē, buwattingga lagi' pagkōg kami maglakibini pagka ato'a na kami sali'-sali'?”",
        13: "Sakali angallam PANGHŪ' ma si Ibrahim, yukna “Angay si Sara tatittowa? Angay buwattē' llingna, ya yukna, ‘Buwattingga e'ku anganak pagka aku ato'a na?’",
        14: "Aniya' bahā' ahunit ma si Yawe? Pahati ka, pagabut bulan bay pangahakaku ma ka'a pabalik du aku pi'itu, bo' h'ndanu si Sara anganak l'lla.”",
        15: "Na, tināw si Sara angkan iya maglimbung, yukna, “Halam aku bay atittowa.” Sagō' anambung Tuhan, yukna, “Allā! Bay ka anittowa.”",
        16: "Sakali itu palanjal na a'a t'llungan e'. Tinūran e' si Ibrahim sampay taromol e' sigām lahat Sodom.",
        17: "Manjari ah'lling PANGHŪ', yukna, “Mbal limbunganku min si Ibrahim ya song hinangku ma lahat Sodom.",
        18: "Sababna in iya po'onan bangsa aheya maka abantug. Buwananku isab kahāpan saga bangsa manusiya' kamemon labay min iya.",
        19: "Tapene'ku iya supaya iya amandu'an saga anak-mpuna ameya' ma kabaya'anku. Subay sigām angahinang ni kahāpan maka ni kabontolan, manjari tumanku to'ongan paljanji'anku ma iya.”",
        20: "Manjari amissala PANGHŪ' ma si Ibrahim, yukna, “Aniya' takaleku sumbungan pasal saga a'a ma da'ira Sodom maka Gomora, lumandu'an kono' la'at dusa sigām.",
        21: "Subay aku pehē' ang'nda' bang b'nnal saga sumbungan e'. Jari kata'uwanku bang b'nnal ka atawa mbal.”",
        22: "Sakali palanjal na duwangan min sigām-i pehē' ni lahat Sodom, sagō' pa'bba gi' Tuhan maina'an ma si Ibrahim.",
        23: "Na pasekot si Ibrahim pehē' ni PANGHŪ', yukna, “O Panghū'ku, palamudnu bahā' a'a halam aniya' dusana pinagmulka'an sali'-sali' maka a'a taga-dusa?",
        24: "Bang saupama,” yukna, “aniya' limampū' a'a abontol ma lahat e', pagmulka'annu bahā' kamemon? Mbal bahā' ka ma'ase' ma lahat inān ma sabab limampū' a'a abontol maina'an?",
        25: "Bang pa'in du mbal pagsali'nu a'a halam aniya' dusana maka a'a taga-dusa, bang pa'in sigām mbal pagmulka'annu. Ka'a ya maghuhukum ma saga manusiya' kamemon ma deyom dunya, maka hukumannu subay abontol sadja.”",
        26: "Manjari ya sambung PANGHŪ' ma si Ibrahim, “Aho', bang aniya' tabākku ma lahat Sodom ilu limampū' a'a halam aniya' dusana, mbal du pagmulka'anku lahat ilu ma sababan sigām.”",
        27: "Manjari angallam si Ibrahim pabīng, yukna, “O Panghū'ku, manusiya' du aku, halam aniya' kawasaku, sagō' anawakkal aku angamu' ma ka'a pabīng.",
        28: "Bang saupama aniya' mpatpū' maka lima a'a abontol ma lahat inān, pagmulka'annu lagi' bahā' ma saukat kulang lima min heka a'a bay amu'ku-i?” Anambung isab PANGHŪ', “Bang aniya' tabākku mpatpū' maka lima a'a abontol, mbal pagmulka'anku lahat ilu.”",
        29: "Na, ah'lling si Ibrahim pabalik, yukna, “O Panghū'ku, bang saupama aniya' mpatpū' du?” Ya sambung PANGHŪ', “Aho', ma sabab mpatpū' a'a abontol, mbal pagmulka'anku lahat ilu.”",
        30: "Angamu' lagi' si Ibrahim, “Ndū' Panghū'ku, da'a akagit ataynu, dūlin aku angamu' pabīng. Bang saupama aniya' du t'llumpū' a'a tabāknu abontol, pagmulka'annu bahā'?” Ya sambung Tuhan, “Bang aniya' tabākku t'llumpū' a'a abontol, na, mbal pagmulka'anku lahat ilu.”",
        31: "Manjari angamu' na pa'in si Ibrahim, “Ampunun lagi' aku, O Panghū'ku, anawakkal gi' aku angamu' ma ka'a pabīng. Bang saupama aniya' tabāknu duwampū' du a'a halam magdusa, pagmulka'annu lagi' bahā'?” Ya sambung Tuhan, “Ma sabab duwampū' a'a abontol ilu, mbal du pagmulka'anku lahat ilu.”",
        32: "Manjari ya katapusan niamu' e' si Ibrahim, yukna, “O Panghū'ku, ndū', da'a akagit ataynu, ya sadja itu amu'ku ma ka'a. Bang saupama aniya' sangpū' sadja tabāknu mailu halam magdusa?” Na, ya sambung Tuhan, “Ma sabab sangpū' a'a, sagarin na, mbal na pagmulka'anku lahat ilu.”",
        33: "Manjari aubus pa'in kapagbissala PANGHŪ' maka si Ibrahim, ala'an na iya minnē'. Amole' isab si Ibrahim.",
    },
    19: {
        1: "Na, song na sangom, at'kka na duwa mala'ikat e' ni da'ira Sodom, hinabu si Lōt aningkō'-ningkō' ma atag lawang da'ira. Pag'nda' si Lōt ma duwangan itu, pasampang iya ma sigām maka e'na pasujud.",
        2: "Yuk si Lōt, “Saga tuwan, pahapit lagi' kam pi'itu ni luma'ku minsan mbal na apatut. Ngā'anta kam bohe' pangose' tape'bi. Labotta kam, ati maitu na kam atuli. Subay na subu bo' yampa kam palanjal.” Ya sambung sigām, “Sagarin na, maitu sadja kami atuli ma halaman itu.”",
        3: "Sagō' pinogos sigām e' si Lōt subay pinasōd ni luma'na, manjari ameya' na sigām. Magpanoho'an si Lōt ma saga sosoho'anna, sinō' magadjal sampay angahinang tinapay halam pinasuligan pangalabot ma sigām. Atahak pa'in, amangan na sigām.",
        4: "Na, halam lagi' sigām atuli, alibut na luma' si Lōt e' saga kal'llahan kamemon onde'-matto'a min sakalibutan da'ira Sodom inān.",
        5: "Angalingan sigām ma si Lōt, yuk sigām, “Oy, Lōt! Ma'ai na saga a'a bay bowanu ni luma'nu insini'-i? Paluwasun sigām pi'itu ni kami. Bilahi kami angusiba'an sigām duwangan.”",
        6: "Pagkale si Lōt, magtūy iya paluwas min luma'na. Tinambol e'na lawang",
        7: "ati yukna ma kal'llahan inān, “Saga tuwan, angamu' aku junjung ma ka'am. Da'a kam maghinang jahulaka' ilu.",
        8: "Pakale lagi' kam. O'o, itiya' duwangan anakku budjang. Soho'ku sigām paluwas pi'ilu ati baya'-baya'bi na. Da'a sadja saga a'a itu sabab itiya' sigām ma deyomanku, subay sigām halli'anku.”",
        9: "Saguwā' ya sambung saga kal'llahan Sodom e' ma si Lōt, yuk-i, “Pasebog ka minnilu! Sai sa ka'a ilu amituwa ma kami? Ka'a ilu ngga'i ka a'a minnitu. Na, bang ka mbal pasebog minnilu, hinang kami ma ka'a akalap lagi' min duwangan a'a ilu.” Magtūy nijudjalan si Lōt e' sigām ni bihing lawang, song to'ongan nilarak e' sigām tambolna inān.",
        10: "Daipara ya duwangan ma deyom-i makaukab lawang supaya tahella' si Lōt pareyom. Ma deyom pa'in, tinambol magtūy e' sigām lawang.",
        11: "Manjari saga l'lla kamemon ma luwasan luma', ai na ka onde'-onde', ai na ka matto'a, bay kasilawan e' a'a duwangan-i bo' mbal makabāk lawang.",
        12: "Manjari atilaw duwangan mala'ikat e' ma si Lōt, yuk sigām, “Aniya' lagi' kampungnu maitu ma lahat Sodom, anaknu d'nda-l'lla ka, atawa ayuwannu? Bang aniya', subay sigām bowanu alahi min da'ira itu",
        13: "sabab lubu kami lahat itu. Takale asal e' PANGHŪ' -Yawe sumbungan pasal kala'atan saga a'a Sodom, makalandu' na to'ongan. Angkan kami sinoho' pi'itu e'na amaka'at katibu'ukan lahat itu.”",
        14: "Magtūy pehē' si Lōt ni duwangan l'lla ya tunang anakna budjang ati yukna, “O, pal'kkas kam, ala'an kam minnitu sabab lahat itu song nilubu e' PANGHŪ'.” Saguwā' mbal sigām am'nnal ma si Lōt. Pangannal sigām in iya hal maglata.",
        15: "Pagdai' llaw pinogos si Lōt e' saga mala'ikat-i, yuk sigām, “Pal'kkas ka magmomos. Bowahun anak-h'ndanu ala'an min lahat itu bo' supaya kam mbal talapay pinagmulka'an e' Tuhan.”",
        16: "Saguwā' magduwa-ruwa lagi' si Lōt angkan iya arak taluwa' mulka', daipara ma'ase' PANGHŪ' ma iya. Niambit iya e' mala'ikat, iya baranna sampay h'ndana maka duwangan anakna budjang. Jari binowa sigām paluwas min da'ira he'.",
        17: "Ma luwasan pa'in, ah'lling mala'ikat dangan, yukna, “Anginosog kam paragan bo' kam mbal magmula. Da'a kam pahogga' ma kapantayan ilu. Da'a kam minsan palingi'. Alahi sadja kam pehē' ni kabūd-būran supaya kam mbal talapay amatay.”",
        18: "Sagō' aniya' pah'lling si Lōt ma iya. “Oy da'a saga tuwanku,” yukna.",
        19: "“Aheya pagsukulanku ma ka'am, tatabangbi ginhawa baranku. Sagō', ndū', alawak makalandu' kabūran e'. Marai' mbal tasampayku ati ta'abut mulka' aku.",
        20: "Nda'un ba kauman inān, anahut asal maka asekot pi'itu. Bang bahā' tugutannu aku alahi pina'an, sabab ta'nda'nu kanahutna. Manjari asalamat du aku.”",
        21: "Na, ya sambung mala'ikat ma si Lōt, “Aho', makajari kam pina'an. Mbal du paka'atku kauman ina'an-i.",
        22: "Saguwā' paragan kam pahāp. Subay kam at'kka pehē' bo' yampa lanjalanku hinangku.” Manjari ya kauman kapē'an disi Lōt inān, kaōnan Sowar ma sabab bissala si Lōt, ya yukna anahut-nahut kono'.",
        23: "Na, pagt'kka disi Lōt ni Sowar yamboho' pasobang mata llaw.",
        24: "Lahat Sodom maka lahat Gomora he' pinatumbukan ulan api e' PANGHŪ' -Yawe.",
        25: "Manjari kamulka'an e'na duwa lahat e'. Talapay isab saga kaluma'an ma kaluha'an kapantayan inān sampay manusiya'na kamemon sampay isab paltomo'-tomo'anna kamemon.",
        26: "Sagō' bay palingi' h'nda si Lōt ni buli'anna ati tahinang iya magtūy batu asin.",
        27: "Na, pagsalung dakayu' bo' subu-subu lagi', magdai'-dai' si Ibrahim pabīng pehē' ni bay pat'nggehanna ma matahan PANGHŪ'.",
        28: "Niromolan e'na karatagan lahat Sodom maka Gomora. Humbu sadja ya ta'nda'na maina'an, sali' humbu tapahan aheya makalandu'.",
        29: "Daipara kinannal si Ibrahim e' Tuhan hinabuna amat'kka mulka' ma saga da'ira bay paglahatan si Lōt. Hatina si Ibrahim ya sababna angkan si Lōt pinapuwas e' Tuhan min mulka'.",
        30: "Na, si Lōt maka duwa anakna budjang inān tināw maglahat ma lahat Sowar. Manjari ala'an sigām pehē' ni kabūd-būran ati mahē' na sigām pat'nna' ma deyom dakayu' songab batu.",
        31: "Dakayu' llaw magsuli-suli anak si Lōt karuwangan. Yuk siyaka ma siyali, “Nneng, ato'a na si Mma' maka halam na aniya' l'lla ma lahat itu tahinangta h'lla buwat kabiyaksahan manusiya'.",
        32: "Gom lagi' palangota si Mma', jari maghulid kita maka iya bo' supaya aniya' tubu'ta.”",
        33: "Na pagsangom pa'in, pinalango si Lōt e' anakna-i ati pabihing ni iya anakna siyaka. Halam tasayu e' si Lōt sabab nilango iya.",
        34: "Pag'llaw, amissala siyaka ma siyali, yukna, “Aku ya bay ma bihing si Mma' dibuhi'. Na, sangom ilu, palangota iya pabīng ati ka'a na ya pabihing atuli. Manjari,” yukna, “sali'-sali' kita makabāk tubu' min mma'ta.”",
        35: "Sakali itu pagsangom pa'in, pinalango si Lōt e' duwangan anakna bo' pabihing ni iya anakna siyali. Halam du isab aniya' ai-ai tasayu e' si Lōt sabab nilango iya.",
        36: "Manjari ab'ttong e' si Lōt duwangan anakna.",
        37: "Siyaka anganak l'lla ati ōnanna Mowab. Si Mowab itu ya na po'onan saga bangsa Mowab buwattina'an.",
        38: "Ya du anak si Lōt siyali, anganak isab l'lla ati niōnan e'na Bin-ammi. Manjari si Bin-ammi itu, ya na po'onan saga bangsa Ammon buwattina'an.",
    },
    20: {
        1: "Na, maglain disi Ibrahim min lahat Mamre tudju ni Negeb ma lahat Kana'an bo' pahanti' ma tonga'an Kades maka Sūr. Puwas e', palanjal sigām ni da'ira Gerar, ati ma Gerar pa'in,",
        2: "angahaka si Ibrahim pasal h'ndana si Sara, in iya danakanna kono'. Manjari pagta'u itu e' si Abimelek, ya sultan ma lahat Gerar, pinabowa e'na si Sara bo' hinangna h'nda.",
        3: "Pagsangom pa'in, pinauppihan si Abimelek e' Tuhan. Yuk Tuhan ma iya ma deyom uppina, “Amatay ko' ka'a ilu sabab d'nda bay ta'ā'nu ilu taga-h'lla asal.”",
        4: "Na, halam gi' makabihing si Abimelek ni si Sara, angkan iya anambung ma Tuhan, yukna, “O Panghū'ku, papataynu aku bahā', sampay saga a'aku, ma halam aniya' dusaku?",
        5: "Bay aku nihaka'an e' si Ibrahim ya d'nda itu danakanna kono'. Ya du d'nda-i, bay angahaka isab in sigām magdanakan kono'. Tu'ud aku a'awam, halam kata'uwanku in iya taga-h'lla, maka halam aku makahinang ala'at.”",
        6: "Manjari ya sambung Tuhan ma si Abimelek ma deyom uppina, “Aho', kata'uwanku a'awam ka. Angkan ka bay sagga'ku bo' mbal makasekot ni iya, maka mbal isab makahinang dusa ma aku.",
        7: "Na, papole'un na d'nda ilu pehē' ni h'llana. Nabi asal iya ati angamu'-ngamu' iya ni aku ma pasalnu supaya ka mbal amatay. Sagō' bang saupama mbal papole'nu, tantu du ka amatay sampay saga a'a ma deyomannu kamemon.”",
        8: "Pagsubu-subu pa'in, pinatimuk e' si Abimelek kamemon saga tendogna supaya pata'una sigām pasal bay tumaluwa' ma iya inān. Magtūy aheya tāw sigām.",
        9: "Si Ibrahim isab sinō' patampal ni si Abimelek bo' tilawna, yukna, “Ala'at pahāp hinangnu ma kami! Ai dusaku ma ka'a ya angkan kami maka bebeya'anku katōngannu dusa landu' aheya itu? Mbal manjari!",
        10: "Ai po'onanna ya angkan ka makahinang buwattilu?”",
        11: "Na, ya sambung si Ibrahim, “Tuwan sultan, pangannalku halam aniya' ma lahat itu tināw ma Tuhan. Angkanna ya ma deyom atayku binono' du aku bo' ta'ā' h'ndaku.",
        12: "B'nnal isab, magdanakan kami, da'mma', duwa ina'. Jari tahinangku iya h'nda.",
        13: "Na, ma masa bay panoho' Tuhan ma aku subay palawak min deyoman mma'ku, bay sa yukku ma h'ndaku, ‘Bang ka sab'nnal-b'nnal ma'ase' ma aku, pi'ingga-pi'ingga lahat kat'kkahanta angahaka ka in kita magdanakan.’”",
        14: "Na, pagkale lling itu e' si Abimelek, pinapole' e'na si Sara ni si Ibrahim. Aniya' isab saga bili-bili, saga sapi' maka saga ata d'nda-l'lla pamuwan e' si Abimelek ma si Ibrahim.",
        15: "Amissala lagi' iya ma si Ibrahim, yukna, “Nda'un luha lahatku itu. Amene' ka maingga-maingga kabaya'annu pat'nna'an.”",
        16: "Yukna isab ma si Sara, “Itiya' buwananku danakannu dangibu pilak dī pilak pangandiyat kasā'anku, paltanda'an in ka'a halam bay makahinang dusa minsan ai.”",
        17: "Na, saga kar'ndahan kamemon ma okoman si Abimelek bay pinatigangan kandang e' PANGHŪ' -Yawe ma sabab kapangā'na ma si Sara h'nda si Ibrahim. Jari angamu'-ngamu' si Ibrahim ni Tuhan ma pasalan disi Abimelek, ati nirūlan pangamu'-ngamu'na. Hatina kauli'an si Abimelek maka h'ndana sampay saga ipatanna d'nda ati maka'anak sigām pabīng.",
        18: "Na, saga kar'ndahan kamemon ma okoman si Abimelek bay pinatigangan kandang e' PANGHŪ' -Yawe ma sabab kapangā'na ma si Sara h'nda si Ibrahim. Jari angamu'-ngamu' si Ibrahim ni Tuhan ma pasalan disi Abimelek, ati nirūlan pangamu'-ngamu'na. Hatina kauli'an si Abimelek maka h'ndana sampay saga ipatanna d'nda ati maka'anak sigām pabīng.",
    },
    21: {
        1: "Na, tinuman e' PANGHŪ' -Yawe bay panganjanji'na ma si Sara, kabuwanan iya kahāpan.",
        2: "Hatina ab'ttong iya ati anganak iya l'lla. Jari taga-anak na si Ibrahim ma kato'ana. Ya waktu kapanganak si Sara ya na waktu asal bay pangallam Tuhan.",
        3: "Manjari si Isa'ak ya pangōn si Ibrahim ma anakna min si Sara.",
        4: "Ta'abut pa'in walumbahangi si Isa'ak ma luwasan, magtūy iya ni'islam e' si Ibrahim buwat bay panoho'an Tuhan ma iya.",
        5: "Dahatus tahun na umul si Ibrahim ma waktu kapanganak ma si Isa'ak e'.",
        6: "Sakali ang'bbat si Sara, yukna, “Itiya' aku kabuwanan kakōgan maka pagtittowahan e' Tuhan. Sasuku isab makakale ma pasal itu-i magbeya' du magtittowa maka aku.”",
        7: "Yukna lagi', “Ma waktu dahū halam aniya' a'a makatawakkal ah'lling ma si Ibrahim in aku itu makaparuru' gi'. Sagō' itiya' aku kabuwanan anak minsan ato'a na h'llaku.”",
        8: "Na, aheya-heya pa'in si Isa'ak, nilutas iya min ina'na. Manjari aheya jajamuhan pinasakap e' si Ibrahim ma llaw kalutas onde' inān.",
        9: "Pagubus, ta'nda' e' si Sara anakna si Isa'ak pinagtittowahan e' onde'-onde' ya anak si Ibrahim min si Hajara ya bangsa Misil.",
        10: "Sakali ah'lling si Sara ni si Ibrahim, yukna, “Tuwanku, pala'anun banyaga' itu maka anakna si Isma'il. Mbal iya subay binahagi'an alta' ya pamusaka'nu ma anakta si Isa'ak.”",
        11: "Na, pagkale si Ibrahim ma lling h'ndana-i, landu' iya asusa sabab anakna du isab si Isma'il.",
        12: "Saguwā' magsuwala Tuhan ma si Ibrahim, yukna, “Da'a ka asusa pasal onde' ilu maka ina'na ya atanu. Beya'un sadja pah'lling si Sara ma ka'a, sabab si Isa'ak ya po'onan paltubu'annu.",
        13: "Ya pasal anak si Hajara, pahekaku panubu'na sampay sigām tahinang bangsa, sabab anaknu du iya.”",
        14: "Sakali pagsalung, subu-subu pa'in, aniya' sinakap e' si Ibrahim kinakan maka kuwit kambing isihan bohe'. Pinatanggung e'na ma baha si Hajara bo' yampa pinatulak e'na, iya maka anakna si Isma'il. Jari pal'ngngan-l'ngngan sigām ma paslangan lahat Be'erseba bo' halam sali' aniya' patudjuhan sigām tantu.",
        15: "Na, aubus pa'in bohe' bay lutu' sigām, ka'bbahan e' si Hajara anakna ma lindung kayu areyo'-deyo'.",
        16: "Paokat iya saga limampū' d'ppa lawakna aningkō'. Ya ma pikilanna, “Arōy, mbal aku makasandal ang'nda' bang amatay anakku.” Jari magdohon iya pagtingkō'na ma tongod ina'an.",
        17: "Daipara takale tangis onde'-onde' inān e' Tuhan. Magtūy aniya' suwala mala'ikat min deyom sulga' ah'lling ni si Hajara, yuk-i, “O Hajara, angay ka asusa? Da'a ka tināw sabab takale e' Tuhan pagtangis anaknu hinabuna palege ma dambila' ilu.",
        18: "Bangunun iya bo' ambitun pahāp, sabab ma sinosōng hinangku paltubu'anna bangsa ga'osan.”",
        19: "Sakali itu aniya' bohe' pama'nda' Tuhan ma si Hajara. Magtūy iya pehē' anauk bo' pin'nno'an kuwit kambing ya bay bowana, ati pamainum e'na ma anakna inān.",
        20: "Manjari si Isma'il itu halam bay pinasagaran e' Tuhan hinabuna pasulig. Ina'an iya maglahat ma Paslangan Paran. Apanday asal si Isma'il magpana' hayop talun.",
        21: "Mahē' pa'in sigām ma lahat Paran, aniya' d'nda niā' min lahat Misil e' si Hajara pamah'ndana ma si Isma'il.",
        22: "Na ma masa ina'an-i, pinehē' si Ibrahim e' sultan Abimelek maka si Pikul, nakura' kasundaluhanna. Yuk si Abimelek ma si Ibrahim, “Tuwan, kata'uwanku in ka'a tinabang sadja e' Tuhan ma ai-ai hinangnu.",
        23: "Manjari aniya' maksudku ni ka'a. Anapa ka maitu ma matahan Tuhan in ka'a mbal angakkal ma aku sampay ma anak-mpuku tubu'-manubu'. Bay aku amogbogan ka'a, manjari ka'a isab subay amogbogan aku sampay saga a'a kamemon ma deyom lahat ya pahanti'annu itu.”",
        24: "Anambung si Ibrahim, yukna, “Aho' tuwan, anapa aku.”",
        25: "Sakali itu aniya' palkala' pagdugalan si Ibrahim ma si Abimelek. Aniya' kono' bohe' kali si Ibrahim bay niagaw e' saga tendog si Abimelek.",
        26: "Ya sambung si Abimelek, “Tuwan, mbal kata'uwanku bang sai magkahinangan ya yuknu ilu. Halam aku asal bay pata'unu, yamboho' takaleku ma buwattina'an.”",
        27: "Manjari aniya' saga bili-bili maka sapi' binowa e' si Ibrahim pamuwanna ma si Abimelek bo' aniya' kapagsulutan sigām ahogot.",
        28: "Aniya' isab pitu' anak bili-bili, d'nda lullun, pinasaddī pa'ataganna min ba'anan bili-bilina kasehe'.",
        29: "Magtūy iya tinilaw e' si Abimelek, yukna, “Pamagaynu anak bili-bili pitu' hekana ya pasaddīnu ilu?”",
        30: "Ya sambung isab si Ibrahim, “Tuwan sultan, taima'un kono' pitu' anak bili-bili itu paltanda'an in aku bay amakali bohe' he'.”",
        31: "Ya he' sababna angkan lahat inān kaōnan Be'erseba, sabab bay pagsapahan si Ibrahim maka si Abimelek.",
        32: "Aubus pa'in sigām maghinang paljanji'an maina'an ma lahat Be'erseba, amole' na disi Abimelek maka si Pikul ni lahat sigām bangsa Pilistin.",
        33: "Na aniya' po'on kayu tamaris tinanom e' si Ibrahim ma lahat Be'erseba-i ati maina'an iya anabbut ma ōn Yawe, ya Tuhan kakkal salama-lama.",
        34: "Manjari at'ggol kapaglahat disi Ibrahim ma lahat bangsa Pilistin e'.",
    },
    22: {
        1: "Na, at'ggol-t'ggol pa'in, sinulayan si Ibrahim e' Tuhan. Nilinganan iya, “O Ibrahim!” Magtūy anaul si Ibrahim, yukna, “Itiya' aku.”",
        2: "Ya lling Tuhan ma iya, “Bowahun anaknu tunggal ilu, si Isa'ak ya kalasahannu to'ongan, pehē' ni lahat Muriya. Tō'anta ka būd ya pamowahannu iya. Jari pagt'kkabi pehē', sumbali'un iya bo' tunu'un pagkulbannu ma aku.”",
        3: "Dai' llaw pa'in, abati' na si Ibrahim an'tta' kayu panunu' sumbali'an. Niruwa' magtūy ni kura'na maka binowa isab anakna si Isa'ak maka duwa sosoho'anna. Jari palintas sigām tudju pehē' ni atag bay panoho'an Tuhan ma iya.",
        4: "Ta'abut pa'in kat'llu llawna, ta'nda' e' si Ibrahim būd ya patudjuhan sigām min kalawakan lagi'.",
        5: "Yuk si Ibrahim ma duwangan sosoho'anna, “Angagad kam maitu maka kura' ilu. Aku maka onde' itu palanjal gi' ni atag e' maghinang ni Tuhan. Pabīng du kami pi'itu bang aubus na.”",
        6: "Manjari nihawas e' si Ibrahim kayu panunu' kukulbanan, ati pinatanggung e'na ma baha si Isa'ak. Si Ibrahim ya amowa lahut maka baga pangapi ati magbeya' sigā patukad.",
        7: "Pasalta', ah'lling si Isa'ak ni mma'na, yukna, “Mma'!” Anambung si Ibrahim, “Ai, Otō'?” Ya lling si Isa'ak, “Mma', ilu ma ka'a baga pangandokot api, maka itiya' ma aku saga kayu. Sagō' maingga bahā' anak bili-bili ya sinumbali' maka tinunu' pagkulbanta?”",
        8: "Anambung magtūy si Ibrahim, yukna, “Otō', Tuhan du ya amaniya' bili-bili pagkulbanta.” Manjari palanjal na sigā karuwangan.",
        9: "Na, makat'kka pa'in sigā ni būd bay panō' Tuhan ma si Ibrahim e', magtūy iya anambak batu pagtunu'an kulban. Aubus pa'in, pinat'nna' kayu ma diyata'na ati niengkotan anakna si Isa'ak bo' yampa palegena ma diyata' kayu.",
        10: "Puwas e' niā' bari' e' si Ibrahim panumbali' anakna.",
        11: "Malaingkan aniya' mala'ikat PANGHŪ' angalingan min deyom sulga', yukna “Ibrahim! O Ibrahim!” Anaul magtūy si Ibrahim, “Itiya' aku.”",
        12: "Ah'lling mala'ikat-i, “Da'a sumbali'un anaknu! Da'a iya inayun! Kata'uwanku na in ka'a magmahaltabat sab'nnal-b'nnal ma Tuhan. Sabab minsan anaknu tunggal halam ka'llogannu, gom pa'in tukbalannu ni Tuhan.”",
        13: "Na palingi' si Ibrahim ati aniya' ta'nda'na dakayu' bili-bili l'lla sumagnat tandukna ma kayu. Magtūy ningā' e'na bo' yampa sinumbali'. Jari tinunu' pagkulban ni Tuhan, pangangganti' baran anakna.",
        14: "Ya pangōn si Ibrahim ma lugal inān ‘Yawe-Yiri,’ hatina, ‘Pinaniya'an kitam e' PANGHŪ'.’ Sampay isab ni kabuwattituhan ya pangōn a'a ma lahat inān, yuk sigām, “Ma būd si Yawe kitam pinaniya'an e'na.”",
        15: "Nilinganan si Ibrahim pabīng min deyom sulga'. Mala'ikat PANGHŪ' ya angalingan, kaminduwana na.",
        16: "Yukna, “Ibrahim, aku itu si Yawe ya angallam itu ma ka'a, maka ōnku luggiya' ya pamahogotan janji'ku. Bay ka ameya' ma panoho'anku ati halam ka'llogannu anaknu tunggal, gom pa'in tukbalannu ni aku.",
        17: "Ya he' sababna angkan aku amat'nna'an ka'a lidjiki' aheya, lidjiki' tuman. Pahekaku du panubu'nu, sali' heka bitu'un ma diyata' langit atawa heka solagan gusung ma bihing tahik. Anganda'ug sadja saga panubu'nu ati ta'agaw e' sigām lahat bay suku' kabantahan sigām.",
        18: "Manjari bangsa kamemon ma deyom dunya angamu' kahāpan du min aku pinasali' ni kahāpan ya pamuwanku ma panubu'nu. Angkan buwattē', sabab bay ka ameya' ma panoho'anku.”",
        19: "Puwas e' pabalik na disi Ibrahim ni saga sosoho'anna. Jari magbeya' sigām amole' pehē' ni lahat Be'erseba ati mahē' sigām pat'nna'.",
        20: "Na at'ggol-t'ggol pa'in, kahaka'an si Ibrahim pasal danakanna si Nahor. Aniya' anakna min h'ndana si Milka, walu' hekana.",
        21: "Ya siyaka to'ongan si Ūs, ya pasunu' si Būs, bo' si Kimuwil mma' si Aram.",
        22: "Puwas si Kimuwil si Kesed, bo' si Haso, bo' si Pildas, bo' si Jidlap, bo' kasiyalihan to'ongan si Bituwil",
        23: "ya mma' si Ripka. Ya na ina'an saga anak l'lla si Milka h'nda si Nahor danakan si Ibrahim.",
        24: "Aniya' isab kalu'a si Milka, ōnna si Rema. Taga-anak isab iya mpat. Ya siyaka si Teba, pasunu' si Gaham, bo' si Tahas, bo' si Ma'aka ya kasiyalihan.",
    },
    23: {
        1: "Na si Sara, ta'abut pa'in dahatus maka duwampū' maka pituntahun umulna,",
        2: "amatay na iya ma lahat Kana'an, ma kauman Hebron, ya kaōnan Kiriyat-Aba ma waktu bay palabay. Manjari pareyom si Ibrahim anangisan h'ndana.",
        3: "Aubus pa'in, pabuhat iya min bihing mayat h'ndana bo' paluwas amowa saga bangsa Hīt maggara'. Yukna ma sigām,",
        4: "“Saga tuwan, aku itu a'a liyu maglihan sadja ma deyomanbi. Ya amu'ku ma ka'am, amab'lli kono' kam tana' bo' aniya' pangubulanku h'ndaku.”",
        5: "Anambung saga a'a bangsa Hīt ma si Ibrahim, yuk-i,",
        6: "“Tuwan, kalehun kono'. Bang ma kami ka'a ilu a'a alanga, patut pinagaddatan. Kubulun h'ndanu ma deyom tampat kami ya katapusan ahāp. Amene' ka kono' maingga-maingga kabaya'annu pangubulan. Halam aniya' min kami makapagin'mbal ma ka'a.”",
        7: "Na, pakuru' magtūy si Ibrahim ma dahuan saga a'a Hīt, ya bangsa tag-lahat, bo' yukna ma sigām,",
        8: "“Bang aku parūlbi angubul h'ndaku maitu, magpati'llot kam ma aku maka si Epron anak si Sohar.",
        9: "Suli-sulihinbi iya pasal songab batu ya ma tōng tana'na, ya ma jadjahan lahat Makpela inān. Bang iya bilahi amab'lli, na, b'lliku du minsan pila pangahalga'na ma aku, jari hinangku pagkubulan. Maitu du aku magbayad ma dahuanbi kamemon.”",
        10: "Na maina'an asal si Epron samatingkō' maka kasehe'anna bangsa Hīt ya patimuk ma atag lawang pagsōd-luwasan da'ira inān. Magtūy sambunganna si Ibrahim ma pagkalehan sigām kamemon, yukna,",
        11: "“Tuwan, kalehun kono' pah'llingku itu. In tana' ilu sampay songab batuna pamuwanku du ma ka'a. Saksi'ku saga lūng-kampungku itu. Na, taima'un kono' pangubulannu h'ndanu.”",
        12: "Na, pakuru' si Ibrahim pabīng ma dahuan sigām bangsa Hīt.",
        13: "Ah'lling iya ma si Epron ma pagkalehan sigām kamemon, yukna, “Tuwan, kalehun aku. B'lliku tana' ilu kamemon. Bayaranta ka pila-pila halga'na. Taima'un kono' bayad itu supaya aku makakubul mayat h'ndaku mahē'.”",
        14: 'Anambung magtūy si Epron, yukna,',
        15: "“Tuwan, ya halga' tana' ilu mpat hatus pilak sadja. Saguwā' pamagayta ilu-i? Kubulun na h'ndanu pehē'.”",
        16: "Na kasulutan si Ibrahim ma bay pangahalga' si Epron ma pagkalehan saga a'a inān kamemon. Tinimbang e' si Ibrahim mpat hatus pilak tibu'uk ma buwat pagtimbang saga palilitu ma waktu ina'an-i, ati bayaranna na.",
        17: "Manjari palsuku'an si Ibrahim na tana' si Epron, ya ma jadjahan Makpela ma bihing lahat Mamre. Palsuku'anna na tana' maka songab batu, sampay kakayu-kayuhan kamemon isab ya ma deyomna.",
        18: "Manjari kasaksi'an e' a'a bangsa Hīt kamemon ya magtimuk maina'an ma pagsosōran da'ira, in si Ibrahim na tag-dapu tana' inān.",
        19: "Aubus pa'in, kinubul e' si Ibrahim h'ndana si Sara ma deyom songab batu inān ma lahat Kana'an.",
        20: "Na, ya na he'. Ya tana' maka songab batu bay ma a'a bangsa Hīt palsuku'an na ma si Ibrahim, pagkubulanna.",
    },
    24: {
        1: "Na, ato'a na to'ongan si Ibrahim. Aheka asal kahāpan bay pamuwan iya e' PANGHŪ' -Yawe ma ai-ai hinangna.",
        2: "Manjari aniya' dakayu' llaw ah'lling si Ibrahim ma dakayu' sosoho'anna, ya tag-ntanan pangalta'na kamemon. Yukna, “Dai' ka. Pat'nna'un tangannu ma llotan pa'aku.",
        3: "Anapa ka ma ōn Yawe, ya Tuhan tag-sulga' maka dunya, da'a pah'nda'in anakku si Isa'ak ni d'nda min bangsa Kana'an, ya tag-lahat pat'nna'anku itu.",
        4: "Pehē' ka gom pa'in ni saga kakampunganku mahē' ma lahatku porol, ati piha'in si Isa'ak d'nda minnē' pamah'nda ma iya.”",
        5: "Manjari tinilaw si Ibrahim e' sosoho'anna-i, yukna, “Tuwan, bang saupama mbal bilahi d'nda ameya' ma aku pi'itu ni lahat itu, ai subay hinangku? Bowaku anaknu pehē' bahā', ni bay lahatnu tagna'?”",
        6: "Ya sambung si Ibrahim, “Oy da'a! Amay-amay, da'a bowahun anakku pehē'.",
        7: "Si Yawe ya Tuhan tag-sulga' bay amapi'itu aku min lahatku porol maka min kakampunganku. Aniya' isab janji' pagkallamna ma aku. Lahat itu kono' pamuwanna du ma saga panubu'ku. Tantu du Tuhan itu amabeya' mala'ikatna parahū min ka'a anakap ai-ai supaya ka makapiha d'nda minnē' pamah'nda ma anakku si Isa'ak.",
        8: "Malaingkan,” yuk si Ibrahim, “bang d'nda ilu mbal bilahi ameya' ma ka'a pi'itu, puwas na ka min palkala' ya pagsapahanta itu. Ya sadja pangamay-ngamayku ma ka'a, da'a bowahun anakku pehē'.”",
        9: "Magtūy anapa sosoho'an si Ibrahim pasal ina'an-i, maka pinat'nna' tanganna ma deyo' pa'a nakura'na.",
        10: "Pagubus, sinakap e'na unta' si Ibrahim sangpū' hekana, niruwa'an ginisan alta' bo' aniya' kasampangan. Jari pauntas iya tudju pehē' ni kauman si Nahor ma lahat Mesopotami.",
        11: "Palabay pa'in daka pilang'llaw, at'kka na sosoho'an si Ibrahim pehē' ni kaluma'an si Nahor, ati pinatingkō' e'na saga unta' ma atag bohe' ya ma luwasan kaluma'an. Abay kohap na lahat, waktu pagā' bohe' e' saga kar'ndahan.",
        12: "Manjari angamu'-ngamu' iya ma Tuhan, yukna, “O Yawe, ya pagtuhanan nakura'ku si Ibrahim, tabangin aku llaw itu bo' ta'ā'ku maksudku. Pa'nda'in isab lasanu maka ase'nu ma nakura'ku he'.",
        13: "Itiya' aku an'ngge ma tongod pagbohe'an, maka ilu na isab saga kabudjangan pi'itu min kaluma'an supaya angā' bohe'.",
        14: "Na, bang sigām ganta' palūd pi'itu, ya pah'llingku ma dakayu' min sigām, ‘Arung, painumun lagi' aku bohe' min kibutnu ilu.’ Na, bang iya ina'an d'nda ya asal tapene'nu pamah'nda ma sosoho'annu si Isa'ak, na, mura-murahan bang pa'in buwattitu panambungna: ‘Aho' tuwan, anginum ka, maka ngā'anta lagi' ka bohe' pamainum saga unta'nu.’ Na, bang hati' buwattē', magtūy kata'uwanku in kasi-lasanu ma nakura'ku aheya to'ongan.”",
        15: "Manjari itu, halam gi' aubus pangamu'-ngamu'na, aniya' budjang palūd pina'an magtanggung kibut, ōnna si Ripka. Na, mma' si Ripka itu si Bituwil, anak si Nahor maka si Milka. Si Nahor itu magdanakan maka si Ibrahim.",
        16: "Ahāp d'nda si Ripka, alingkat to'ongan, maka halam bay makalabay l'lla. Palūd iya ni bohe' angisihan kibutna bo' yampa patukad pabalik.",
        17: "Pal'kkas magtūy sosoho'an si Ibrahim anampang iya, yukna, “Arung, painumun lagi' aku bohe' min kibutnu ilu.”",
        18: "Ya sambungna, “Aho', Tuwan, anginum na ka.” Magtūy pinareyo' kibutna supaya makainum a'a-i.",
        19: "Aubus pa'in e'na anginum, yuk budjang ma iya, “Angagad gi' ka, tuwan, ngā'anku lagi' bohe' pamainum saga unta'nu sampay sigām asso.”",
        20: "Magtūy tinuwangan isi kibutna pehē' ni pagi'inuman saga hayop, ati magkuwat-kuwat iya angā' bohe' sampay tapainumna kamemon.",
        21: "Halam ah'lling sosoho'an-i. Hal ang'nda'-ng'nda' maka e'na maghona'-hona' bang kalu ta'ā'na maksudna sabab tabang min PANGHŪ'.",
        22: "Aubus pa'in anginum saga unta' inān, aniya' kasampangan nihawas e' sosoho'an-i min duwa'anna: dakayu' singsing ahalga' maka duwa gallang aheya, bulawan lullun, ati pamuwanna ma budjang-i.",
        23: "Puwas e' atilaw iya ma budjang, yukna, “Arung, sai mma'nu? Makajari kami atuli ma luma'bi sangom ilu? S'ddong bahā'?”",
        24: "Yuk sambung budjang, “Mma'ku si Bituwil, mbo'ku si Nahor maka si Milka.",
        25: "Aheka parang-parang kami pamakan saga unta'nu, aniya' isab kapantayan paghali-halian. Maka luma' kami aheya du isab.”",
        26: "Magtūy pakuru' sosoho'an inān amudji PANGHŪ'.",
        27: "Yukna, “Pudjiku si Yawe ya pagtuhanan nakura'ku si Ibrahim, pagka itiya' pa'nda'anna lasana maka ase'na ma iya. B'nnal-b'nnal katō'an aku e'na lān tudju ni kakampungan nakura'ku.”",
        28: "Sakali itu magdai'-dai' budjang-i parahū amole' ni pagluma'an ina'na. Kasuli-sulihan sigām kamemon pasal bay kahālanna inān.",
        29: "Na aniya' danakan si Ripka l'lla ōnna si Leban. Pagkale si Leban itu ma suli-suli si Ripka, maka pag'nda'na isab singsing ma ūngna maka gallang ma l'ngngonna karuwambila', magtūy iya magdai'-dai' pehē' ni bohe'. Ta'nda'na a'a bay panuli-nuli e' danakanna an'ngge maina'an ma bihing saga unta'na.",
        30: "Na aniya' danakan si Ripka l'lla ōnna si Leban. Pagkale si Leban itu ma suli-suli si Ripka, maka pag'nda'na isab singsing ma ūngna maka gallang ma l'ngngonna karuwambila', magtūy iya magdai'-dai' pehē' ni bohe'. Ta'nda'na a'a bay panuli-nuli e' danakanna an'ngge maina'an ma bihing saga unta'na.",
        31: "Yuk si Leban ma iya, “O tuwan, ka'a binarakatan e' Tuhan. Angay ka paddas maitu? Sūng kita pehē' ni luma'. Sakap na ma ka'a maka aniya' isab palegehan kaunta'annu.”",
        32: "Manjari pehē' a'a-i ni luma', ati nihawasan saga duwa'an min bukut saga unta'na e' si Leban. Pinakan isab unta' he' maka pinat'nna'an parang-parang pabahakan. Aniya' isab bohe' binowahan sosoho'an si Ibrahim maka saga sehe'na pangose' tape' sigām.",
        33: "Pagbuhat pa'in lalabotan ma sosoho'an si Ibrahim-i, ah'lling iya, yukna, “Mbal lagi' aku amangan, tuwan. Subay paluwasku gawiku dahū.” Yuk si Leban, “Na aho', paluwasun kono'.”",
        34: "Jari ah'lling na, yukna, “In aku itu sosoho'an si Ibrahim.",
        35: "Aheya kahāpan tapamuwan si Yawe ma iya, manjari dayahan na. Ya pamuwan Tuhan ma iya ba'anan hayop kaginisan, angkan jukup iya ma bili-bili, kambing, sapi', unta' maka kura'. Aheka isab bulawan kaginisan, aheka isab atana d'nda-l'lla.",
        36: "Na h'ndana si Sara bay anganak l'lla ma kato'ana, ati pamusaka' na e' si Ibrahim ma anakna itu karayana kamemon.",
        37: "Manjari aku itu bay binowa magsapa e' nakura'ku he'. Yukna ma aku, ‘Da'a pah'nda'in anakku si Isa'ak d'nda minnitu min lahat Kana'an.",
        38: "Subay ka pehē' ni kakampunganku, ni dī kausbahanku bo' supaya ka amiha d'nda maina'an pamah'nda ma anakku.’",
        39: "“Magtūy tilawku nakura'ku, yukku, ‘Bang saupama aniya' d'nda tapihaku sagō' mbal bilahi ameya' ma aku pi'itu ni lahat itu, painay?’",
        40: "Ya sambungna ma aku, ‘Ya PANGHŪ' pagbeya'anku, tantu iya anoho' mala'ikatna anehe'an ka'a supaya ta'ā'nu maksudnu. Tantu aniya' d'nda min kakampunganku tabowanu pamah'nda ma anakku.",
        41: "Malaingkan,’ yuk nakura'ku-i, ‘bang ka saupama pehē' ni saga kausbahanku bo' ka mbal tinaima', apuwas na ka min palkala' ya pagsapahanta itu.’”",
        42: "Anuli-nuli gi' sosoho'an si Ibrahim, yukna, “Na, makat'kka pa'in aku ni bohe' insini', angamu'-ngamu' aku. Yukku, ‘O Yawe, ya pagtuhanan nakura'ku si Ibrahim, tabangin aku supaya ta'ā'ku maksudku.",
        43: "Itiya' aku ma bihing bohe'. Jari bang aniya' budjang pi'itu angā' bohe', angamu' du aku pinainum bohe' min kibutna.",
        44: "Na Tuhan, bang ya na d'nda ya asal tapene'nu pamah'nda ma anak nakura'ku, na, bang pa'in buwattitu panambung budjang-i ma aku, “Aho' tuwan, anginum ka. Ngā'anta ka bohe' isab pamainum saga unta'nu.”’",
        45: "“Sakali itu,” yuk a'a-i ma disi Leban, “halam gi' aubus e'ku angamu'-ngamu' ni Tuhan ma deyom atayku, ina'an si Ripka patuwa' magtanggung kibut. Palūd iya magtūy angā' bohe'. Aubus pa'in, yukku ma iya, ‘Arung, makajari aku painumnu bohe'?’",
        46: "“Pinareyo' kibut magtūy min bahana. Yukna ma aku, ‘Aho' tuwan, anginum na ka. Painumku isab saga unta'nu.’ Jari anginum na aku, maka pinainum isab unta'ku.",
        47: "“Bay iya tilawku isab, ‘Sai mma'nu?’ Ya sambungna ma aku, ‘Aku itu anak si Bituwil, mbo'ku si Nahor maka si Milka. Manjari tuwan,” yuk a'a, “bay sangonanku singsing ilu ni ūngna maka pasulugku isab gallang ma l'ngngonna karuwambila'.",
        48: "Pagubus, pakuru' aku magtūy amudji si Yawe ya pagtuhanan nakura'ku si Ibrahim. Aheya pagsukulanku ma iya sabab katuli'an aku e'na pi'itu ni saga lahasiya' si Ibrahim. Tapihaku na anak sigām budjang pamah'nda ma anak nakura'ku, bang hati aniya' dapat.",
        49: "Na, bang aniya' lasabi ma nakura'ku pagka kam maglahasiya' du, haka'inbi aku sab'nnal-b'nnal bang taima'bi maksudku itu atawa mbal. Bang hati' mbal, na maghona'-hona' lagi' aku bang ai subay hinangku.”",
        50: "Anambung si Leban maka si Bituwil, yuk sigām, “Ya palkala' ilu min kabaya'an PANGHŪ' du, jari halam aniya' kapatut kami angaho' atawa magin'mbal.",
        51: "Itiya' si Ripka, bowahun iya pasambeya' ma ka'a tudju ni pamole'anbi. Pah'nda'un iya ma anak nakura'nu. Tu'ud kahandak PANGHŪ' ko' ilu.”",
        52: "Na, pagkale sosoho'an si Ibrahim ma sambung disi Leban-i, magtūy iya pasujud magsarang-sukul ma PANGHŪ'.",
        53: "Puwas e', pinaluwas e'na saga s'mmek maka pamulawan dī bulawan bo' yampa pamuwanna ma si Ripka. Aniya' isab kasampangan ahalga' pamuwanna ma disi Leban sampay ma ina' si Ripka.",
        54: "Na aubus pa'in ina'an-i, magkakanan maka maginum sosoho'an si Ibrahim maka saga sehe'na bo' yampa sigām atuli. Pag'llaw dakayu' bo' magbati'an na sigām, ama'id sosoho'an e' min disi Leban. Yukna, “Amuhun lagi' aku amole' ni nakura'ku.”",
        55: "Saguwā' mbal bilahi danakan si Ripka maka ina'na, yuk sigām, “Tuwan, bang bahā' minaitu gi' si Arung saga sangpū' bahangi. Pagpuwas, ameya' du iya ma ka'am.”",
        56: "Malaingkan yuk sosoho'an, “Ndū' ampunun aku, sagō' ahāp kami da'a taggahinbi. Ta'ā'ku na in maksudku ma sabab tabang min PANGHŪ', manjari papole'unbi na aku bo' pabīng ni nakura'ku he'.”",
        57: "Ya sambung sigām, “Lingananta gi' si Ripka. Tilawta iya bang ai kabaya'anna.”",
        58: "Sakali nilinganan si Ripka bo' tinilaw. Yuk-i, “Na buwattingga? Bilahi ka ameya' ma a'a itu?” Ya sambung si Ripka, “Aho', ameya' aku.”",
        59: "Manjari pinatulak kakasi sigām si Ripka ameya' ma a'a inān sampay saga sehe'na. Pinabeya' isab ma iya matto'a d'nda ya bay angipat iya min kariki'-diki'na gi'.",
        60: "Niamu'-amu'an isab iya duwa'a min Tuhan e' disi Leban. Yuk pangamu' sigām, “Arung, mura-murahan bang pa'in laksa'an heka panubu'nu! Bang pa'in ta'agaw e' panubu'nu lahat kabantahan sigām.”",
        61: "Puwas e' magsakap na si Ripka maka saga sehe'na d'nda ati pakura' sigām ni saga unta' bo' ameya' ma tendog si Ibrahim e'. Jari pauntas sigām kamemon ni pal'ngnganan sigām.",
        62: "Na in si Isa'ak, wa'i na pat'nna' ma lahat Negeb (lahat tampal ni satan min lahat Kana'an). Yamboho' iya makapole' min bohe' niōnan Be'er-Lahai-Ruwi.",
        63: "Manjari itu, abay kohap pa'in lahat, hinabuna maglunsul-lunsul ma kaparangan, aniya' ta'nda'na saga unta' magt'kkahan.",
        64: "Ahā, ta'nda' isab si Isa'ak e' si Ripka. Pag'nda'na, magtūy iya pareyo' min unta'",
        65: "bo' tilawna sosoho'an si Ibrahim. Yukna, “Sai bahā' l'lla ma kaparangan inān, ya pal'ngngan tudju pi'itu ni kita?” Ya sambung sosoho'an si Ibrahim, “Si Isa'ak ko' inān, ya nakura'ku.” Magtūy niā' e' si Ripka turungna panambunna ma baihu'na.",
        66: "Makasampay pa'in sigām ni si Isa'ak, nihaka'an iya e' sosoho'an e' pasal kamemon bay kalabayanna.",
        67: "Pagubus, binowa si Ripka e' si Isa'ak tudju ni deyom kamalig bay pagluma'an ina'na si Sara. Gana-gana tahinangna h'nda. Alasa to'ongan si Isa'ak ma si Ripka, manjari kauli'an karukka'anna min kamatay ina'na.",
    },
    25: {
        1: "Manjari si Ibrahim makapagh'nda na pabīng, ōn h'ndana si Kitura.",
        2: "Nnom anakna l'lla min si Kitura. Ya siyaka si Simran, pasunu' si Joksan, bo' si Medan, bo' si Midiyan, kalimana si Isbak bo' si Suwa ya kasiyalihan.",
        3: "Si Joksan itu ya na mma' si Seba maka si Dedan. Manjari saga panubu' si Dedan, ya na bangsa Assur, bangsa Litus maka bangsa Leyom.",
        4: "Aniya' isab saga anak si Midiyan l'lla. Ōn sigām si Epa, si Eper, si Hanok, si Abida maka si Elda. Na, iya na ina'an panubu' si Ibrahim min h'ndana si Kitura.",
        5: "Si Isa'ak ya pamusaka'an e' si Ibrahim suku'na kamemon. Daipara sasangna allum lagi', aniya' alta' pamuwanna ma saga anakna min saga h'ndana saddī min si Sara. Sinoho' sigām maglahat ma lahat dakayu' tampal ni sobangan bo' supaya sigām alawak min anakna si Isa'ak.",
        6: "Si Isa'ak ya pamusaka'an e' si Ibrahim suku'na kamemon. Daipara sasangna allum lagi', aniya' alta' pamuwanna ma saga anakna min saga h'ndana saddī min si Sara. Sinoho' sigām maglahat ma lahat dakayu' tampal ni sobangan bo' supaya sigām alawak min anakna si Isa'ak.",
        7: "Na ataha' to'ongan umul si Ibrahim, dahatus maka pitumpū' maka limantahun. Manjari amatay na iya ma deyom kasannangan ati pinapagtimuk iya maka ka'mbo'-mbo'anna.",
        8: "Na ataha' to'ongan umul si Ibrahim, dahatus maka pitumpū' maka limantahun. Manjari amatay na iya ma deyom kasannangan ati pinapagtimuk iya maka ka'mbo'-mbo'anna.",
        9: "Kinubul iya e' anakna si Isa'ak maka si Isma'il ma deyom songab batu ma tana' si Makpela tampal ni sobangan min tana' si Mamre. Songab batu itu asal ma tana' bay bin'lli e' si Ibrahim min si Epron anak si Sohar bangsa Hīt. Jari kinubul si Ibrahim ma bihing h'ndana si Sara.",
        10: "Kinubul iya e' anakna si Isa'ak maka si Isma'il ma deyom songab batu ma tana' si Makpela tampal ni sobangan min tana' si Mamre. Songab batu itu asal ma tana' bay bin'lli e' si Ibrahim min si Epron anak si Sohar bangsa Hīt. Jari kinubul si Ibrahim ma bihing h'ndana si Sara.",
        11: "Na, pagka amatay na si Ibrahim, si Isa'ak ya pas'lle' binuwanan kahāpan na pa'in e' Tuhan. Maglahat si Isa'ak ma tongod bohe' Be'er-Lahai-Ruwi.",
        12: "Ya na itu saga panubu' si Isma'il, anak si Ibrahim min si Hajara a'a bangsa Misil, ya bay ipatan si Sara.",
        13: "Ya itu ōn saga anak si Isma'il magsunu'-sunu': si Nebayot ya kasiyakahan, pasunu' si Kedar, bo' si Abbe'el, bo' si Mibsam.",
        14: "Ya pasunu' ma si Mibsam si Misma, bo' si Duma, bo' si Massa,",
        15: "bo' si Hadad, bo' si Tema, bo' si Jetor, bo' isab si Napis, kasiyalihan si Kedema.",
        16: "Na saga anak si Isma'il itu tahinang po'onan sangpū' maka duwa tumpuk. Maka ōn sigām tahinang ōn lahat isab, ya pat'nna'an ba'anan katumpukan itu.",
        17: "Ta'abut pa'in umul si Isma'il dahatus maka t'llumpū' maka pituntahun, amatay na iya ati pinapagtimuk maka ka'mbo'-mbo'anna.",
        18: "Manjari saga panubu' si Isma'il itu ina'an maglahat ma tonga'an lahat Habila maka Sūr, ma bihing lahat Misil tampal ni sobangan. Magsaddī asal pat'nna'an sigām min saga panubu' si Ibrahim kasehe'an.",
        19: "Ya na itu salsila pasal si Isa'ak, anak si Ibrahim. Si Ibrahim ya mma' si Isa'ak.",
        20: "Mpatpū' tahun ya umul si Isa'ak waktu pah'ndana ma si Ripka danakan si Leban, anak si Bituwil. (Si Bituwil itu a'a Aram min lahat Mesopotami.)",
        21: "Sakali itu, pagka halam maka'anak si Ripka minsan at'ggol na pagpūn sigām, angamu'-ngamu' si Isa'ak ni PANGHŪ' -Yawe bang pa'in pinapangiram h'ndana. Manjari pinarūl pangamu'na e' PANGHŪ' ati ab'ttong si Ripka.",
        22: "Ya kinab'ttongan e' si Ripka k'mbal, sagō' ma halam lagi' paluwas tananamna sigām magkosog-kosogan ma deyom b'ttongna. Yuk si Ripka, “Angay bahā' buwattitu pagb'ttongku?” Jari angaru iya ni PANGHŪ' -Yawe.",
        23: "Ati yuk PANGHŪ' ma iya, “Ya ma deyom b'ttongnu ilu, duwa onde'-onde', manjari tahinang sigām duwa bangsa mbal to'ongan magsulut. Sababna dakayu' ilu akosog min dakayu', maka anaknu siyaka ilu pinagbaya'an du e' siyali.”",
        24: "Manjari ta'abut na bulanan si Ripka, k'mbal l'lla anakna.",
        25: "Ya dahū paluwas, akeyat-keyat kuwitna maka bahibuan baranna kamemon sali' kahantang kakana' akasap. Angkan iya niōnan Esaw.",
        26: "Ya paluwas damuli wa'i amalut pahogot ma buli' tape' si Esaw. Angkanna iya niōnan si Yakub. Nnompū' tahun asal umul si Isa'ak ma waktu kapanganak ma anakna k'mbal itu.",
        27: "Manjari asangpot pa'in umul duwangan k'mbal itu, si Esaw ya a'a magpapana', apanday to'ongan angā' hayop talun. Ya katagihanna subay ma luwasan sadja. Saddī kajarihan si Yakub. Ahantap iya, ya katagihanna subay pataptap ma kauman.",
        28: "Na, aheya lasa si Isa'ak ma si Esaw sabab asōb iya amangan susumbali'an ya tapana' e' si Esaw. Sagō' si Yakub ya kalasahan si Ripka.",
        29: "Manjari dakayu' llaw, hinabu pa'in si Yakub itu maghinang sayul batung keyat niloho'an, makapole' si Esaw min pagpana'an. Lingantu to'ongan iya,",
        30: "angkan yukna ma si Yakub, “Buwanin aku min loho' keyat ya b'llanu ilu. Sidda aku pinunung!” Ya he' sababanna angkan iya niranglay si Edom, hatina ‘keyat.’",
        31: "Ya sambung si Yakub, “Aho', sagō' buwanin aku kapatutannu dahū, ya pamusaka' anak siyaka.”",
        32: "Ya sambung isab si Esaw, “Na, pehē'un na, ma ka'a na kapatutan e'. Pamagayku bang aku arai' na patay otas?”",
        33: "Yuk si Yakub ma iya, “Subay ka anapa dahū, in kapatutan pamusaka' ma ka'a pamuwannu na ma aku sab'nnal-b'nnal.” Magtūy sinapahan e' si Esaw, jari pamuwanna pusaka'na ma siyalina.",
        34: "Pagsapa si Esaw, binuwanan iya tinapay maka loho' keyat e' k'mbalna. Na, amangan na iya sampay anginum bo' na paluwas. Halam to'ongan pinahalga' e'na kapatutanna ya pamusaka' ma anak siyaka.",
    },
    26: {
        1: "Sakali itu aniya' gotom ma lahat Kana'an e', saddī min gotom bay kalabayan disi Ibrahim ma waktu dahū. Jari maglain disi Isa'ak pehē' ni Gerar, ya lahat pagsultanan si Abimelek sultan bangsa Pilistin.",
        2: "Bay na magpa'nda' asal PANGHŪ' ma si Isa'ak maka e'na ah'lling, yuk-i, “Isa'ak, da'a ka pehē' ni lahat Misil. Ya paglahatannu subay lahat song panō'ku ma ka'a.",
        3: "Sagō' pahanti' ka buwattina'an ma jadjahan ya pat'nna'annu ilu. Taptap du aku mailu ma ka'a amuwanan ka'a kahāpan. Saga lahat kamemon ma jadjahan itu-i pamasuku'ku ma ka'a sampay ma saga panubu'nu. Tumanku isab bay paljanji'anku ma mma'nu si Ibrahim.",
        4: "Buwananta ka paltubu'an aheka, buwat saga bitu'un ma diyata' langit ya heka sigām. Pamuwanku du isab katibu'ukan lahat ilu ma sigām. Manjari kabangsahan kamemon ma deyom dunya angamu' kahāpan du min aku bang pa'in pinasali' ni kahāpan ya pamuwanku ma saga panubu'nu.",
        5: "Aho', buwananta ka kahāpan ma sabab kapameya' si Ibrahim ma panoho'anku. Bay kabogbogan e'na sara' maka panoho'an bay pamat'nna'ku ma iya.”",
        6: "Manjari mahē' na si Isa'ak pahanti' ma lahat Gerar.",
        7: "Na, tinilaw pa'in iya e' saga l'lla minna'an pasal si Ripka, ya sambungna ma sigām, “Danakanku ko' ilu.” Halam bay bontolna in si Ripka h'ndana du, sabab tināw iya. Pangannalna in iya binono' e' saga a'a inān bo' ta'ā' si Ripka e' sigām pagka ahāp d'nda sidda.",
        8: "Sakali itu, at'ggol-t'ggol pa'in kamahē' disi Isa'ak ma lahat Gerar, aniya' dakayu' llaw amantaw sultan Abimelek min tandawanna. Ta'nda' e'na si Isa'ak anapu-napu si Ripka.",
        9: "Magtūy pinalinganan si Isa'ak e' si Abimelek, sinō' patampal ma iya. Yukna, “Halam aniya' pagduwa-ruwana, h'ndanu ko' ilu. Angay kami putingannu in iya kono' danakannu?” Ya sambung si Isa'ak, “Tuwan sultan, tu'ud aku tināw binono' bang aku angahaka sab'nnal-b'nnal in iya h'ndaku.”",
        10: "Yuk si Abimelek, “Angay kami tala'atnu buwattilu? Bang saupama aniya' a'aku bay makabihing atuli ma iya, na, ka'a ya sababna bang kami kat'kkahan dusa.”",
        11: "Angkanna sinanggupan e' si Abimelek saga tendogna kamemon, yukna, “Sai-sai angala'at a'a itu atawa h'ndana, pat'nna'anku iya hukuman ni kamatay.”",
        12: "Manjari itu, ma Gerar pa'in si Isa'ak maglahat, maghuma iya ati ahāp to'ongan buwa' tinanomna ma tahun inān. Maghatusan buwa'na dampo'on maka dampo'on ma sabab lidjiki' min PANGHŪ'.",
        13: "Pak'nnop na pa'in alta' si Isa'ak sampay aheya to'ongan karayana.",
        14: "Na, pagka aheka to'ongan bili-bilina, kambingna maka sapi'na, maka aheka isab saga sosoho'anna, nijingki iya e' bangsa Pilistin.",
        15: "Ya he' sababna angkan nirasokan tana' saga pagbohe'an kamemon bay kinali e' saga sosoho'an mma'na si Ibrahim ma masana allum lagi'.",
        16: "Angkanna si Abimelek bay amowa si Isa'ak maggara', yukna, “Tuwan, subay kam papinda ni lahat saddī, sabab aga'os na kam min kami.”",
        17: "Sakali pauntas disi Isa'ak pehē' ni L'bbak Gerar ati mahē' na sigām pat'nna'.",
        18: "Aniya' saga pagbohe'an asal ma tongod ina'an-i bay kinali ma masa lagi' mma'na si Ibrahim, sagō' amatay pa'in si Ibrahim bay nirasokan tana' e' saga a'a Pilistin. Manjari ya bohe' inān bay pinakali pabīng e' si Isa'ak, pinat'nna'an isab ōn bay pangōn e' mma'na-i.",
        19: "Puwas e' aniya' pagbohe'an baha'u bay kinali e' saga sosoho'an si Isa'ak ma l'bbak inān ati makabāk sigām bohe' ahāp.",
        20: "Sagō' magsagga' saga a'a Gerar maka saga a'a magi'ipat hayop si Isa'ak. Yuk a'a Gerar e', “Kami dapu bohe' ilu.” Ya he' sababna angkan bohe' inān niōnan ‘Esek’ e' si Isa'ak, hatina ‘Pagsagga'an.’",
        21: "Na angali gi' saga sosoho'an si Isa'ak pagbohe'an saddī, jari ya du ina'an tahinang pagsasawan e' saga a'a Gerar, angkan niōnan e' si Isa'ak ‘Sitna’, hatina ‘Pagbantahan.’",
        22: "Palawak gi' disi Isa'ak minnē' bo' yampa angali bohe' saddī. Na halam na aniya' pagsagga'an ma pagbohe'an itu angkan niōnan Rehobot, hatina ‘Kaluhaya'an.’ Yuk si Isa'ak, “Itiya' kitam pinaluhaya e' PANGHŪ' -Yawe pat'nna' to'ongan ma lahat itu. Tantu kitam makabāk kahāpan maitu.”",
        23: "Na, patukad sigām minnē' tudju ni lahat Be'erseba.",
        24: "Pagt'kka sigām pehē' bo' sangom na, magpa'nda' PANGHŪ' ma si Isa'ak magsuwala, yuk-i, “Aku ya Tuhan pagtuhanan mma'nu si Ibrahim. Da'a ka tināw sabab taptap du aku mailu ma ka'a. Buwananta ka kahāpan, pahekaku panubu'nu ma sabab sosoho'anku si Ibrahim.”",
        25: "Aniya' pagtunu'an kulban nihinang e' si Isa'ak maina'an, bo' ana'at iya ma ōn si Yawe. Jari maina'an iya pat'nna', maina'an isab saga sosoho'anna bay angali pagbohe'an.",
        26: "Na aniya' dakayu' llaw pinehē' si Isa'ak e' si Abimelek, ya sultan ma lahat Gerar. Ya sehe' si Abimelek si Ahussat, ya bagayna pangandolan, maka si Pikul, ya nakura' saga kasundaluhanna.",
        27: "Atilaw si Isa'ak ma sigām, yukna, “Tuwan sultan, ai gawinu pi'itu? Bay aku pala'anbi min lahatbi inān maka aheya kab'nsibi ma aku. Na, ai maksudbi ma aku?”",
        28: "Ya sambung sigām, “Aho' tuwan, saguwā' kata'uwan kami in ka'a tinabang sadja e' si Yawe, angkan yuk kami subay aniya' pagsulutantam. Manjari ya maksud kami itu mikisapa ma ka'a,",
        29: "supaya ka mbal angala'at kami. Bistahun, sat'ggol kam bay ma lahat kami kahāpan sadja ya tahinang kami ma ka'am. Maka ta'abut waktu isab kala'anbi, pinatulak kam ma deyom kasannangan. Tantu ka kabuwanan kahāpan na pa'in e' si Yawe.”",
        30: "Pagkale si Isa'ak, magpajamu iya pangahulmatna ma disi Abimelek ati magsalu sigām amangan maka anginum.",
        31: "Pagsubu pa'in magjanji' sigām min karuwambila', magsapa in sigām mbal na magbono' dansehe'an. Pagubus, pinaba'id disi Abimelek e' si Isa'ak ati amole' sigām magatay pote'.",
        32: "Na, ma llaw ina'an-i, pina'an ni si Isa'ak saga sosoho'anna angahaka'an iya pasal pagbohe'an yamboho' kinali e' sigām. “Makabāk kami bohe'!” yuk sigām.",
        33: "Ya pangōn si Isa'ak ma bohe' inān ‘Siba'’. Ya he' sababna angkan kauman inān kaōnan Be'erseba sampay ni kabuwattituhan.",
        34: "Na, in pasal si Esaw, ta'abut pa'in mpatpū' tahun umulna, makapagh'nda iya duwa d'nda bangsa Hīt, ya na si Judit anak si Be'ere maka si Basemat anak si Elon.",
        35: "Aheya isab kasukkalan si Isa'ak maka si Ripka, ya matto'a si Esaw, ma sabab duwangan d'nda itu.",
    },
    27: {
        1: "Na palabay pa'in daka pilantahun, ato'a na si Isa'ak, mbal na maka'nda'. Jari aniya' llaw pangalinganna ma si Esaw, ya anakna siyaka. Yukna ma iya, “Otō'.” Ya sambung si Esaw, “Oy, Mma'.”",
        2: "Yuk si Isa'ak, “Otō', ta'nda'nu aku itu ato'a na. Sōng-sōng na ta'abut ganta'anku, angkan aniya' amu'ku ma ka'a.",
        3: "Bowahun pana'nu pehē' ni kareya-reyahan amiha'an kita hayop susumbali'an.",
        4: "Adjalin aku pagkakan ahāp nanamna ya kasōbanku. Bowahun pi'itu bo' kakanku ati amu'-amu'anta ka ni Tuhan bang pa'in ka pinasuku'an lidjiki'. Pang'bbaku ma ka'a sasangku masi allum.”",
        5: "Na, hinabu pa'in si Isa'ak magsuli-suli maka si Esaw, ina'an si Ripka pakale-kale. Jari makalanjal pa'in si Esaw kaleya amana',",
        6: "magtūy ah'lling si Ripka ni si Yakub, yukna, “Otō', yamboho' takaleku mma'nu ah'lling ma siyakanu, yukna,",
        7: "‘Piha'in kita susumbali'an ma deya. Adjalun pahāp bo' aniya' palaukku ahāp nanamna. Aubus pa'in aku amangan, amu'-amu'anta ka kahāpan ni Tuhan bang pa'in ka pinasuku'an lidjiki' ya kapatutan pamasuku' ma anak siyaka. Ya du ina'an pang'bbaku ma ka'a sasangku masi allum. Si Yawe ya saksi'ku.’",
        8: "Na, Otō',” yuk si Ripka, “kalehun aku. Beya'un panoho'anku itu.",
        9: "Pehē' na ka ni buluyan hayopta. Pene'un duwa anak kambing ahāp l'mmokna ati bowahun pi'itu ni aku. Aku ya angadjalan mma'nu lauk alanab ya kasōbanna to'ongan.",
        10: "Atahak pa'in lauk e', ka'a ya amowa pehē' ni mma'nu ati ka'a ya amakan iya. Manjari ka'a ya niamu'-amu'an kahāpan min Tuhan e' mma'nu sasangna masi allum lagi'.”",
        11: "Yuk si Yakub ni ina'na, “Oy, Ina', bahibuan asal si Esaw. Aku ngga'i ka, alanu' kuwitku.",
        12: "Painay bahā' bang aku sinanaw e' si Mma', bo' kata'uwanna magtūy in aku amarupang ma iya. Bang buwattē' ngga'i ka kahāpan ya ta'ā'ku, saguwā' sukna'.”",
        13: "Na ya sambung ina'na ma iya, “Mbal, Otō'. In sukna' inān subay papelleng ni aku, ngga'i ka ni ka'a. Pehē' na ka, ngā'in kita kambing.”",
        14: "Sakali pehē' na si Yakub angā' duwa anak kambing. Binowa e'na pehē' ni ina'na bo' adjalanna lauk ya kasōban si Isa'ak kinakan.",
        15: "Pagubus, pinaluwas e' si Ripka badju' si Esaw ahāp to'ongan, ya bay ma deyom tau'an. Jari pasulugna na ma anakna siyali, ya si Yakub.",
        16: "Niā' isab e' si Ripka kuwit kambing bay ta'adjal inān ati pangalapis e'na ma bukut tangan si Yakub sampay ma buli' k'llongna supaya iya bahibuan sali'.",
        17: "Aubus pa'in e'-i, ni'nde'an e' si Ripka ni si Yakub lauk ahāp nanamna, maka tinapay baha'u bay hinangna.",
        18: "Sakali pehē' na si Yakub ni mma'na, yukna, “O Mma'!” Yuk si Isa'ak, “Aho', Otō'. Sai sa ka'a ilu?”",
        19: "Ya sambung si Yakub, “Si Esaw, anaknu siyaka. Tahinangku na bay panoho'annu ma aku. Itiya' na lauk bay adjalanku ka'a. Papunduk ka amangan bo' aku yampa amu'-amu'annu kahāpan ni Tuhan.”",
        20: "Ah'lling gi' si Isa'ak ma si Yakub, yukna, “Al'kkas pahāp kapihanu susumbali'an ilu. Angay bahā'?” Ya sambung si Yakub, “Tu'ud aku tinabang e' si Yawe, ya pagtuhanannu.”",
        21: "Yuk si Isa'ak isab, “Otō', pasekot ka kono'. Sanawta ka bang ka b'nnal-b'nnal anakku si Esaw.”",
        22: "Manjari pasekot na si Yakub ni mma'na bo' tasanaw e'na. Yuk si Isa'ak, “Lagamnu sali' lagam si Yakub, malaingkan tangannu itu sali' tangan si Esaw.”",
        23: "Na, halam takilāna in a'a inān si Yakub, sabab tasanawna tanganna bahibuan, dasali' maka tangan si Esaw. Na, arai' pa'in si Isa'ak angamu'-ngamu' kahāpan tudju ni Tuhan,",
        24: "tinilaw e'na si Yakub pabīng, yukna, “B'nnal bahā'? Ka'a ilu anakku si Esaw?” “Aho', Mma',” yuk si Yakub. “Halam saddī.”",
        25: "Sakali ah'lling si Isa'ak, yukna, “Ndiya na lauk bay adjalannu aku-i. Amangan na aku bo' yampa ka amu'-amu'anku kahāpan tudju ni Tuhan.” Magtūy iya binowahan lauk maka binu-anggul e' si Yakub.",
        26: "Aubus pa'in, nilinganan iya. Yuk mma'na ma iya, “Otō', pi'itu ka kono', siyumun aku.”",
        27: "Manjari pasekot na si Yakub ni mma'na aniyum iya. Sakali itu, tahamut pa'in s'mmekna e' si Isa'ak, hamut si Esaw to'ongan, magtūy iya niamu'-amu'an kahāpan ni Tuhan. Ya pagkallam si Isa'ak ma iya, “Ya hamut anakku itu sali' hamut tana' paghuma'an kabuwanan kahāpan e' si Yawe.",
        28: "Bang pa'in binusugan tana'nu e' Tuhan maka alu' min diyata' langit. Bang pa'in isab pinajatu e'na tanomannu, supaya aheka buwa'na pagkakannu maka paginumnu!",
        29: "Bang pa'in kapagbaya'annu saga kabangsa-bangsahan, bang pa'in sigām pasujud ma ka'a. Bang pa'in ka magnakura' ma kakampungannu kamemon, bang pa'in isab pasujud ma ka'a kapanubu'an ina'nu. Bang pa'in kataluwa'an mulka' sasuku anabbut ōnnu ni kala'atan. Bang pa'in binuwanan kahāpan sasuku anabbut ōnnu ni kahāpan.”",
        30: "Manjari itu, aubus pa'in pangamu'-ngamu' si Isa'ak, bo' yamboho' paluwas si Yakub, ina'an na si Esaw at'kka min deya.",
        31: "Magtūy du iya angadjal lauk ahāp nanamna bo' yampa bowana pehē' ni mma'na. Yukna, “O Mma', itiya' na lauk bay adjalanku ka'a. Papunduk ka amangan bo' yampa aku amu'-amu'annu kahāpan ni Tuhan.”",
        32: "Tinilaw iya magtūy e' si Isa'ak, “Arī, sai sa ka'a ilu?” Ya sambung si Esaw, “Aku itu si Esaw, anaknu siyaka.”",
        33: "Agsai takuddat si Isa'ak, amidpid to'ongan baranna. Yukna, “Sai sa a'a bay amowahan aku palauk insini'. Susumbali'an kono' bay tapana' e'na! Yamboho' takakanku ma waktu kat'kkanu itu. Baha'u du iya bay amu'-amu'anku kahāpan ni Tuhan. Pangannalku ka'a, sagō' kahāpan ilu mbal kapindahan sabab makalagtik na d'lla'ku.”",
        34: "Na, pagkale si Esaw ma lling mma'na he' magtūy iya anangis pakosog kabowa kagit atayna. Yukna, “Arōy, aku isab Mma', amu'-amu'in aku kahāpan isab!”",
        35: "Ya sambung si Isa'ak, yukna, “Arōy, Otō'. Bay aku tarupang e' siyalinu. Ta'ā'na na kahāpan ya arak pamasuku'ku ma ka'a.”",
        36: "“Ā,” yuk si Esaw, “tinōp iya niōnan Yakub, sabab min duwa na aku ka'akkalan e'na. Ta'agaw e'na pusaka' ya kapatutanku pagka aku anak siyaka. Maka ma buwattina'an isab, ta'ā'na kahāpan min Tuhan ya subay pamasuku' aku. Mma', halam bahā' aniya' lidjiki' bay kapinannu aku?”",
        37: "Anambung si Isa'ak, yukna, “Bay na amu'-amu'anku si Yakub kahāpan bang pa'in iya tahinang nakura'nu. Maka kampungna kamemon subay tahinang sosoho'anna. Ta'amu'-amu'ku isab bang pa'in iya binalanja'an kinakan ahāp e' Tuhan maka binu-anggul paginumna. Hatina, Otō', si Yakub ya pinasuku'an kamemon, ati halam aniya' tahinangku ma ka'a.”",
        38: "Sakali angamu' na pa'in si Esaw, yukna, “Mma', min t'dda sadja ka bahā' angamu'-ngamu' kahāpan ni Tuhan? Mbal bahā' kaisaban? Ndū' Mma', amu'-amu'in aku kahāpan isab.” Jari aheya tangisna.",
        39: "Manjari magkallam si Isa'ak ma si Esaw, yukna, “Paglahatannu alawak du min huma ya taptap pinajatu e' Tuhan. Mbal ka pinasuku'an tana' ya binusugan maka alu' min diyata' langit, tana' akansang buwa'na.",
        40: "Magbono' du ka bo' aniya' tatabannu pagkallumannu, sagō' siyalinu ya pagnakura'annu na pa'in. Malaingkan bang ka mbal makasandal pinagbaya'an e'na, angatu du ka ati makal'ppa min komkomanna.”",
        41: "Sakali ab'nsi sidda si Esaw ma si Yakub ma sabab kahāpan ya pamasuku' ma iya e' mma' sigām. Ya minohot e' si Esaw ma deyom atayna, “Mbal at'ggol amatay du si Mma' ati papatayku si Yakub itu.”",
        42: "Daipara kahaka'an si Ripka pasal kamohotan si Esaw. Makata'u pa'in iya, magtūy lingananna si Yakub, yukna, “Otō', pakale ka. Agara' si Esaw amalosan ka'a.",
        43: "Na, buwattitu panganggara'ku ma ka'a, Otō'. Ala'an ka magdai'-dai' pehē' ni kauman Haran, ni danakanku si Leban e'.",
        44: "Subay ka pahanti' ma deyomanna sampay alungay na kab'nsi siyakanu ma ka'a.",
        45: "Jari bang ahāp-hāp na atayna ni ka'a, bo' alungay min pangentomna bay hinangnu ma iya, na, tambukuhanta pa'in ka bo' ka makapole' pi'itu. Tu'ud aku mbal bilahi kalungayan duwa anak ma dang'llaw.”",
        46: "Sakali aniya' pah'lling si Ripka ma si Isa'ak, yukna, “Ab'nsi aku ma saga d'nda bangsa Hīt buwat h'nda si Esaw itu. Bang si Yakub ganta' magh'nda isab ma bangsa Hīt, na, ahāp lagi' aku amatay.”",
    },
    28: {
        1: "Manjari halam gi' makauntas si Yakub, pinalinganan iya e' si Isa'ak. Maina'an pa'in, sinagina iya maka niamay-amayan. Yuk mma'na ma iya, “Otō', da'a ka magh'nda d'nda Kana'an.",
        2: "Pehē' ka gom pa'in ni lahat Mesopotami, ni tumpuk si Bituwil ya mbo'nu min ina'. Pene'un d'nda ngā'nu h'nda min ka'anakan bapa'nu si Leban.",
        3: "Mura-murahan, bang pa'in ka binuwanan kahāpan e' Tuhan Sangat Kawasa, bang pa'in pinaheka panubu'nu bo' ka tahinang pag'mbo'an ma kabangsa-bangsahan.",
        4: "Bang pa'in pinasampay ni ka'am dapanubu'an ya kahāpan bay panganjanji' Tuhan ma mma'ku si Ibrahim. Hatina ka'am iya tahinang tag-dapu lahat pahanti'antam itu, ya lahat bay pamuwan asal e' Tuhan ma mma'ku.”",
        5: "Aubus pa'in e' si Isa'ak ah'lling ma si Yakub, pinatulak na iya bo' pauntas tudju ni lahat Mesopotami, ni kauman si'itna si Leban. Ya si Leban itu anak si Bituwil a'a Aram.",
        6: "Manjari tata'u e' si Esaw pasal si Isa'ak bay angamu'-ngamu'an si Yakub kahāpan. Bay patulakna isab pehē' ni lahat Mesopotami amiha d'nda ngā'na h'nda. Niamay-amayan iya sinō' da'a magh'nda d'nda bangsa Kana'an.",
        7: "Ya takale isab e' si Esaw in si Yakub kono' bay ameya' ma panoho'an matto'ana, hatina wa'i na pal'ngngan tudju ni lahat Mesopotami.",
        8: "Na minnē' kinata'uwan na e' si Esaw in mma'na si Isa'ak mbal to'ongan kasulutan ma saga d'nda bangsa Kana'an,",
        9: "angkan iya pehē' ni si'itna si Isma'il anak si Ibrahim. Maina'an pa'in, makah'nda iya ni si Mahalat anak si Isma'il, danakan isab si Nebayot. Manjari t'llu na h'nda si Esaw.",
        10: "Na, pauntas na si Yakub min lahat Be'erseba bo' pal'ngngan tudju ni kauman Haran.",
        11: "Manjari makasampay pa'in iya ni dakayu' pa'atagan, pahanti' iya maina'an sabab pas'ddop na llaw. Angā' iya dakayu' batu paū'anna bo' yampa pabahak atuli.",
        12: "Jari anguppi iya. Ya ta'nda'na ma deyom uppina haronan bay pinat'ngge min tana' tudju ni diyata' langit. Aniya' isab ta'nda'na saga mala'ikat magdeyo'-diyata'.",
        13: "Ina'an isab PANGHŪ' an'ngge min diyata'na maka e'na magsuwala. Yukna, “Aku itu si Yawe ya pagtuhanan mbo'nu si Ibrahim maka mma'nu si Isa'ak. Ya tana' pabahakannu ilu pamuwanku ma ka'a sampay ma saga panubu'nu.",
        14: "Pahekaku du tubu'nu, ya heka sigām sali' solagan gusung ma gintana'an. Paheka du sigām ma kaluha'an lahat itu, min sobangan sampay ni s'ddopan. Maka kabangsa-bangsahan kamemon maitu ma dunya buwananku kahāpan du ma sababannu maka ma sababan saga panubu'nu.",
        15: "Na, taptap du aku mailu ma ka'a, jagahanta ka pi'ingga-pi'ingga pal'ngnganannu, sampay ni waktu pamowata ka'a pabīng ni lahat itu. Mbal ka bbahanku, maka tumananku to'ongan ya paljanji'anku itu ma ka'a.”",
        16: "Jari abati' na si Yakub maka e'na amikilan. “Sab'nnal-b'nnal, itiya' PANGHŪ' ma lahat itu, sagō' halam bay kata'uwanku.”",
        17: "Sinōd iya tāw angkan yukna, “Ag'mma sumangatku ma tongod itu-i! Pagluma'an Tuhan ko' itu. Itiya' isab maitu lawang pagsosōran sulga'.”",
        18: "Pagsubu-subu pa'in, binuhat e' si Yakub batu bay paū'anna sangom-i bo' pinat'ngge e'na sali' hāg. Tapat'ngge pa'in, binase' maka ns'llan bo' nihinang e'na tampat pangentoman.",
        19: "Manjari Betel ya pangōn si Yakub ma lahat inān. (Lūs ya ōn kauman ma atag ina'an ma masa awal lagi'.)",
        20: "Sakali magnajal si Yakub ni Tuhan, yukna, “Bang ka'a-i sab'nnal-b'nnal pataptap anganjagahan aku ma l'ngngananku itu, bang ka amuwanan aku pagkakan maka tamongon,",
        21: "maka bang aku papole'nu isab ni luma' mma'ku ma deyom kasalamatan, na, si Yawe ya Tuhanku, halam aniya' saddī.",
        22: "Ya batu tapat'nggeku itu ibarat luma' pagsusumbahan ni ka'a. Tukbalanku isab ma ka'a bahagi' sangpū' min ai-ai kamemon ya pamasuku'nu ma aku.”",
    },
    29: {
        1: "Pal'ngngan na pa'in si Yakub sampay ta'abutna lahat sobangan.",
        2: "Maina'an pa'in, bo' ma tongod kaparangan, aniya' ta'nda'na bohe' kali tinambolan asal maka batu aheya. Aniya' isab bili-bili t'llu ba'ananna pahali-hali ma tongod ina'an angagad pinainum.",
        3: "Sagō' ya kabiyaksahan saga a'a magi'ipat bili-bili maina'an, subay atipun ba'anan bili-bili kamemon bo' yampa sigām angaligiran batu sampay amainum. Jari aubus pa'in pinainum ba'anan bili-bili kamemon, magtūy tinūran batu-i ni baina.",
        4: "Manjari itu atilaw si Yakub ma saga a'a magi'ipat inān, yukna, “Saga tuwan, minningga sa ka'am ilu?” Ya sambung saga a'a inān, “Kami itu min Haran, tuwan.”",
        5: "Yuk si Yakub isab, “Magkata'u kam bahā' maka si Leban, mpu si Nahor?” Ya sambung sigām, “Aho' tuwan, kata'uwan kami.”",
        6: "Atilaw gi' si Yakub, yukna, “Ahāp isab ginhawa baranna?” “Aho' tuwan”, yuk a'a-i, “Ahāp du. O'o, ilu'un na anakna si Rakiya maka ba'anan bili-bilina.”",
        7: "Yuk si Yakub, “Nda'unbi ba, masi alanga llaw. Mbal gi' waktu pamapole' hayop ni deyom sasak. Bang bahā' painumbi buwattina'an bo' yampa bowabi ni kaparang-parangan pinakan pabīng.”",
        8: "Ya sambung saga a'a he', “Mbal makajari, tuwan. Subay atimuk pi'itu kaba'anan bili-bili kamemon bo' yampa ligiran kami tambol batu itu. Makajari pinainum bang maitu na kamemon.”",
        9: "Na, hinabu pa'in si Yakub magsuli-suli itu maka saga a'a magi'ipat inān, at'kka na si Rakiya maka ba'anan bili-bili mma'na. Tu'ud hinangna angipat bili-bili.",
        10: "Jari pag'nda' si Yakub ma kakina si Rakiya maka bili-bili si'itna si Leban, magtūy niligiran e'na batu min bowa' bohe' bo' painumna saga bili-bili ya suku' si'itna.",
        11: "Aubus pa'in, siniyum e'na si Rakiya maka e'na anangis ma sabab kakōganna.",
        12: "Yuk si Yakub ma iya, “Aku itu si Yakub, kamanakan mma'nu. Ina'ku si Ripka, ya danakan mma'nu.” Na, pagkale si Rakiya, magtūy iya paragan amole' angahaka'an mma'na.",
        13: "Manjari itu, makata'u pa'in si Leban pasal kat'kka kamanakanna si Yakub, magtūy iya magdai'-dai' pehē' anampang. Ginapus e'na si Yakub, siniyum isab ati binowa pehē' ni luma'. Pagka ma deyom luma' na, sinuli-sulihan si Leban e' si Yakub pasal kamemon bay kalabayanna.",
        14: "“Ā,” yuk si Leban ma iya, “lahasiya'ta ka sab'nnal-b'nnal, magdalaha' magdaisi.” Manjari dambulan ya kahanti' si Yakub ma deyoman disi Leban.",
        15: "Palabay pa'in dambulan-i, ah'lling si Leban ma si Yakub, yukna, “Otō', minsan kita magdalaha', bang ka ganta' maghinang ma aku mbal apatut bang halam aniya' tongodna. Subay ka gadjihanku. Haka'in aku bang pila kabaya'annu?”",
        16: "Na, aniya' duwa anak si Leban budjang. Ya ōn siyaka si Leya maka si Rakiya ya ōn siyali.",
        17: "Bulahaw asal mata si Leya, sagō' si Rakiya ya alingkat, ahāp pamarananna.",
        18: "Jari kinabilahian si Rakiya itu e' si Yakub ati yukna ma si Leban, “Bapa' bang ka'a-i asulut, maghinang aku maitu ma ka'a pituntahun, minsan aku mbal gadjihannu. Ya sadja amu'ku ma ka'a bang pa'in pamah'ndanu ma aku anaknu si Rakiya.”",
        19: "Ya sambung si Leban, yukna, “Ā, gom lagi' ka'a ya pamah'llaku ma iya, da'a a'a saddī. Maitu na ka ma deyomanku.”",
        20: "Manjari pituntahun ya paghinang si Yakub ma si Leban supaya tah'ndana si Rakiya, sagō' halam tabistana t'ggolna ma sabab kaheya lasana ma si Rakiya.",
        21: "Na, palabay pa'in pituntahun e', yuk si Yakub ma si Leban, “Bapa', ta'abut na waktu, kawinun kami maka si Rakiya bo' kami makapagdakayu' na.”",
        22: "Angaho' si Leban ati magsakap iya jajamuhan. Pinata'u e'na saga a'a kamemon ma lahatna, sinō' paluruk ni pagkawinan.",
        23: "Saguwā' pagsangom e', ngga'i ka si Rakiya ya ni'nde'an e' si Leban ni si Yakub sagō' si Leya. (Aniya' isab ipatan si Leban ōnna si Silpa bay pamuwanna ma si Leya nihinang ipatan.) Jari si Yakub maka si Leya magbihing na atuli.",
        24: "Saguwā' pagsangom e', ngga'i ka si Rakiya ya ni'nde'an e' si Leban ni si Yakub sagō' si Leya. (Aniya' isab ipatan si Leban ōnna si Silpa bay pamuwanna ma si Leya nihinang ipatan.) Jari si Yakub maka si Leya magbihing na atuli.",
        25: "Na, pagk'llat pa'in llaw dakayu', yamboho' tasayu e' si Yakub in si Leya bay sehe'na sangom inān! Pehē' iya magtūy ni si Leban. “Bapa',” yukna, “angay buwattilu hinangnu ma aku? Jukup na pituntahun ya paghinangku ma ka'a bo' supaya si Rakiya ta'ā'ku h'nda. Angay aku angkan akkalannu?”",
        26: "Ya sambung si Leban, “Otō', ya addat kami maitu, mbal makajari bang siyali pinah'lla'an dahū min siyaka.",
        27: "Tangguhanta dapitu' lagi'. Subay na aubus paglami-lami ma si Leya itu bo' yampa ka pakawin kami maka si Rakiya. Saguwā' aniya' tongodna. Ya paghinangnu maitu ma aku subay sinugpatan pituntahun lagi'.”",
        28: "Na, kasulutan si Yakub. Aubus pa'in dapitu' iya paglami-lami sigām ma si Leya, pinakawin si Yakub e' si Leban ma anakna si Rakiya.",
        29: "Damikiyanna du isab, aniya' ipatan d'nda pamuwan si Leban ma si Rakiya, ōnna si Bilha.",
        30: "Sakali itu magdakayu' na si Yakub maka si Rakiya. Aheya sidda lasana ma si Rakiya, labi-labi min lasana ma si Leya. Jari pituntahun gi' ya paghinang si Yakub ma deyoman si Leban.",
        31: "Na, ta'nda' pa'in e' PANGHŪ' ariki' asal lasa si Yakub ma si Leya, aniya' kahāpan pamuwanna ma iya. Jari si Leya ya makapangiram du, sagō' si Rakiya mbal maka'anak.",
        32: "Jari ab'ttong na si Leya ati anganak iya l'lla. Yukna, “Ta'nda' kasusahanku e' PANGHŪ'. Tantu aku kinalasahan na e' h'llaku.” Manjari Rubin ya pangōnna ma anakna he'.",
        33: "Manjari ab'ttong iya pabīng ati l'lla du isab anakna. Yukna, “Ya anak itu pamuwan PANGHŪ' ma aku sabab takalena pasal aku mbal kinalasahan.” Angkan Simiyun ya pangōnna ma onde'.",
        34: "Na, ab'ttong iya pabīng ati l'lla isab anakna. Yukna, “Na, tantu h'llaku pat'ttog na ma aku sabab t'llu na anak l'lla ya pamuwanku ma iya.” Manjari Libi ya pangōnna ma onde' itu.",
        35: "Anā, ab'ttong si Leya pabīng, ka'mpatna na, l'lla du isab. Yukna, “Pudjiku na PANGHŪ' buwattina'an.” Angkan ōnanna anakna si Yahud. Na minnē' pahondong si Leya maganak.",
    },
    30: {
        1: "Na si Rakiya itu, pagka tasayuna in iya mbal to'ongan makabuwanan si Yakub anak, angimbū na ma siyakana si Leya. Ah'lling iya ma si Yakub, yukna, “Buwanin aku anak. Bang aku mbal maka'anak, gom gi' aku amatay.”",
        2: "Apasu' magtūy atay si Yakub ma si Rakiya, yukna, “Pangannalnu aku itu Tuhan bahā', makapagbaya' amuwanan ka'a anak maka mbal?”",
        3: "Ya lling si Rakiya ma iya, “O'o, ipatanku si Bilha itu. Pahulid ka ma iya supaya iya anganak ganti' min aku, ati taga-tubu' aku min iya.”",
        4: "Jari sinōngan e'na ipatanna si Bilha ma si Yakub pamah'ndana. Magbihing sigām atuli,",
        5: "ati ab'ttong si Bilha maka anganak l'lla.",
        6: "Ya lling si Rakiya, “Kabogbogan aku e' Tuhan in aku patut taga-anak. Takalena bay pangamu'-ngamu'ku ma iya, ati kabuwanan aku anak l'lla.” Manjari Dān ya pangōnna ma iya.",
        7: "Ab'ttong na isab si Bilha pabīng ati aniya' gi' anak si Yakub l'lla min iya, karuwana na.",
        8: "Ya pah'lling si Rakiya, “Aheya paggaggud kami maka siyakaku, sagō' ma aku da'ugan.” Manjari Naptali ya pangōnna ma onde'.",
        9: "Na si Leya isab, pagka tasayuna in iya mbal na anganak, manjari pamuwanna isab ipatanna si Silpa ma si Yakub pamah'ndana.",
        10: "Ab'ttong isab si Silpa ati anganak l'lla.",
        11: "“Ahāp sukudku!” yuk si Leya. Jari Gād ya pangōnna ma anakna he'.",
        12: "Damuli pa'in minnē', anganak pabīng si Silpa itu, jari duwa na anak si Yakub min iya.",
        13: "Ya pah'lling si Leya, “Aheya kakōganku! Pinagsuli-sulihan du aku e' saga kar'ndahan in aku itu d'nda akōd.” Angkan na Aser ya pangōn si Silpa ma anakna.",
        14: "Na ma musim pagani lagi', ina'an si Rubin anak si Leya maglunsul ma huma. Aniya' tabākna buwa' kayu tapagtambal pamapangiram, jari binowa e'na pehē' ni ina'na si Leya. Ah'lling magtūy si Rakiya ni si Leya, yukna, “Kaka', buwanin aku min buwa' kayu ya tabāk e' anaknu ilu.”",
        15: "Ya sambung si Leya, “Ē, mamarahi pahāp ka'a ilu! Bay ta'agawnu h'llaku ati agawnu lagi' buwa' kayu anakku?” Yuk si Rakiya, “Bang aku buwanannu, tugutanku si Yakub pabihing ma ka'a sangom ilu.”",
        16: "Manjari itu, pagt'kka si Yakub min huma abay kohap na, sinampang iya e' si Leya. Yukna ma si Yakub, “Subay ka pabihing ma aku atuli sangom ilu. Makapagisun kami maka si Rakiya insini'. Bay iya buwananku saga buwa' kayu ya tapuwa' e' anakku si Rubin, manjari pinatuli ka ma aku.” Manjari pabihing si Yakub ma si Leya ma sangom inān.",
        17: "Na nirūlan si Leya e' Tuhan. Ab'ttong iya ati anganak l'lla. Manjari lima na anak si Yakub l'lla min h'ndana si Leya.",
        18: "Yuk si Leya, “Katungbasan aku e' Tuhan ni kahāpan ma sabab kapamuwanku ipatanku ma h'llaku.” Angkanna Issakar ya pangōnna ma anakna itu.",
        19: "Angiram isab si Leya pabīng, paganakna l'lla. Manjari nnom na anak si Yakub l'lla bay min si Leya.",
        20: "“Na,” yuk si Leya, “ahalga' to'ongan ya pamuwan Tuhan ma aku. Tantu aku pinaheya na e' h'llaku ma sabab nnom na anakna l'lla min aku.” Manjari Sibulun ya pangōn si Leya ma anakna itu.",
        21: "Na, mbal pa'in at'ggol, ab'ttong si Leya pabīng ati anganak iya d'nda. Dina ya pangōnna ma iya.",
        22: "Na, in si Rakiya isab, taentom du e' Tuhan. Takale bay pangamu'-ngamu' si Rakiya ma iya, ati nirūlan iya bo' makapangiram na.",
        23: "Manjari ab'ttong si Rakiya ati anganak iya l'lla. Ah'lling iya, yukna, “Kala'anan na kaiya'anku e' Tuhan sabab itiya' aku kabuwanan anak.",
        24: "Mura-murahan bang pa'in aniya' gi' anakku l'lla pinasunu' e' PANGHŪ' ni onde' dakayu' itu.” Manjari Yusup ya pangōn si Rakiya ma anakna-i.",
        25: "Manjari itu, bay pa'in nianakan si Yusup, binowa e' si Yakub mato'ana si Leban magisun. Yuk si Yakub, “Bapa', paba'irun aku sabab bilahi na aku amole' ni lahatku.",
        26: "Pabeya'un ma aku saga anak-h'ndaku, ya tausahaku maitu ma deyomannu. Kata'uwannu du ya katuyu'ku maghinang ma ka'a.”",
        27: "Sagō' ya sambung si Leban ma si Yakub, “Otō', da'a gi'. Aniya' pamowahanta ka'a magsuli-suli. Ta'nda'ku ma putika'an ka'a iya sababna ya angkan aku nilidjiki'an e' PANGHŪ'.",
        28: "Ah'lling sadja ka. Gadjihanta ka pila-pila kabaya'annu.”",
        29: "Anambung si Yakub, yukna “Kata'uwannu du bang buwattingga e'ku maghinang maitu ma ka'a. Angahāp sadja kahayopannu ma deyom kapagipatku.",
        30: "Ma halam gi' aku maitu, kulang asal pangalta'nu. Malaingkan aheka na ma buwattina'an. Minsan maingga-maingga paghinanganku ma deyomannu, nilidjiki'an sadja ka e' PANGHŪ' -Yawe. Bang ma aku ta'abut na waktu pamas'lle' ma aku, bo' supaya aniya' palsuku'an ma kami sampay anak-h'ndaku.”",
        31: "Atilaw si Leban ma iya, yukna, “Na, subay pila panganggadji ma ka'a?” Ya sambung si Yakub, “Ngga'i ka gadji ya kabaya'anku. Bang pagsulutanta, subay aku parūlnu angipat ba'anan hayopnu buwat bay dahū. Saguwā' aniya' amu'ku ma ka'a.",
        32: "Tugutin aku angaliling ba'anan hayopnu ma llaw itu to'ongan. Ingga aniya' bili-bili ettom atawa kambing kabang-kabang, ma aku na palsuku'anku. Ya du ilu pangangganti'nu gadjiku.",
        33: "Manjari ma sinosōng, bang ka ganta' bilahi angitung bang pila panambanu ma aku, kata'uwannu magtūy bang aku kapangandolan atawa mbal. Bang saupama aniya' ta'nda'nu ma aku kambing ngga'i ka kabang atawa bili-bili ngga'i ka ettom, takilānu du bay tangkawku min ka'a.”",
        34: "Ya sambung si Leban, “Aho', sulut. Buwattē' na.”",
        35: "Malaingkan karahūan si Yakub e' si Leban ma llaw ina'an-i. Pinasaddī e'na pat'nna'an saga kambingna l'lla jali'-jali' maka kambing d'nda kabang-kabang maka bili-bili ettom-ettom isab. Pinaipat kamemon ma saga anakna e' si Leban,",
        36: "ati palawak sigām min si Yakub saga t'llung'llaw nil'ngngan. Si Yakub ya ta'bba maina'an angipat kaheka'an hayop si Leban ya halam binowa.",
        37: "Na pagka buwattē' akkal si Leban, aniya' saga sanga kayu nilabas e' si Yakub min kayu t'llungginis. Kinupas-kupasan kuwitna supaya magjali'-jali' ettom maka pote'.",
        38: "Kakupasan pa'in, pinat'nna' e'na ma deyom pagbohe'an saga hayop bo' ta'nda' e' sigām pasalta' anginum pehē'. Bang ta'abut timpu pagd'nda saga hayop,",
        39: "magd'nda du ma dahuan saga sanga kayu jali'-jali' he'. Manjari tapangā'an lihi e' kambing d'nda maka bili-bili d'nda ati jali'-jali' maka kabang-kabang maka b'ttikan ya nianakan e' sigām.",
        40: "Na, ya anak hayop e' pinasaddī na pa'in e' si Yakub. Saguwā' ya hayop asangpot pinaharap e'na tudju ni saga hayop jali'-jali' maka ettom-ettom ya suku' si Leban. Minnē' pinapagsaddī ba'anan hayop si Yakub maka ba'anan hayop si Leban.",
        41: "Tiyap-tiyap aniya' hayop d'nda ahāp baranna ya magd'nda, pinat'nna' e' si Yakub saga sanga kayu nijali'-jali' ma deyom paginuman bo' supaya magd'nda ma kasekotan saga sanga-i.",
        42: "Saguwā' bang hayop kulang ahāp ya magd'nda, mbal pinat'nna'an kayu-kayu. Ya kat'kkahanna, in hayop kulang hāpna pinasuku' ma si Leban. Malaingkan ya pinasuku' ma si Yakub anak hayop ahāp sadja baranna.",
        43: "Ya kat'kkahanna, paheka na pa'in bo' paheka karaya si Yakub. Gana-gana aheka na ba'anan bili-bili maka kambingna. Aheka isab saga unta'na maka kura'na. Ya du saga sosoho'anna d'nda-l'lla, aheka du isab.",
    },
    31: {
        1: "Na, kahaka'an si Yakub in iya pinah'llingan ala'at e' saga ipalna anak si Leban. Yuk sigām, “Saga kahayop-hayopan mma'ta wa'i ta'ā' e' si Yakub. Ya angkan iya dayahan ma sabab pangalta' bay suku' si Mma'.”",
        2: "Ta'nda' isab e' si Yakub apinda na addat si Leban ma iya, ngga'i ka na buwat bay tagna'.",
        3: "Magkallam PANGHŪ' ma si Yakub, yukna, “Pabīng ka pehē' ni lahat kamatto'ahannu, ni kakampungannu. Pataptap du aku ma ka'a ma l'ngnganannu.”",
        4: "Anambuku magtūy si Yakub ma disi Rakiya maka si Leya. Sinō' sigām kaleya ni iya, ni tongod pagipatanna hayop.",
        5: "Makat'kka pa'in sigām pehē', yukna ma sigām, “Saga dayang, tasayuku apinda na pamaihu'an mma'bi ma aku, ngga'i ka buwat bay dahū. Daipara tatabang aku e' Tuhan ya pagtuhanan mma'ku.",
        6: "Makata'u kam bay pagsangsā'ku maghinang ma deyoman mma'bi.",
        7: "Sagō' minsan na, parupangna sadja aku pagka pinagpinda-pinda e'na gadjiku. Ngga'i ka hal min t'dda, min sangpū'. Daipara halam aku bay tainay e'na sabab mbal bilahi Tuhan.",
        8: "Bang saupama aniya' h'lling si Leban ma aku, yukna, ‘saga hayopan b'ttikan ya panganggadjiku ma ka'a,’ na, b'ttikan lullun ya nianakan e' saga hayop inān. Ya du bang pindahanna llingna bo' yukna, ‘hayop jali'-jali'an ya panganggadjiku ma ka'a,’ na, jali'-jali' na pa'in ya nianakan e' saga hayop kamemon.",
        9: "Hatina Tuhan ya bay angala'anan karaya mma'bi bo' pamuwanna ma aku.”",
        10: "Anuli-nuli gi' si Yakub, yukna, “Aniya' bay tauppiku ma waktu pagd'nda saga kambing. Kabang-kabang maka jali'-jali'an lullun saga kambing l'lla ya ta'nda'ku magd'nda ma deyom uppiku.",
        11: "Jari aniya' pah'lling mala'ikat Tuhan ma aku, yukna, ‘O Yakub!’ “Ya sambungku, ‘Oy, itiya' aku.’",
        12: "Agsai angabtang mala'ikat-i, yukna, ‘Ang'nda' ka pehē'. Saga kambing l'lla ya magd'nda ilu, kabang lullun maka jali'-jali'an. Min kabaya'anku ko' ilu, sabab kata'uwanku bay pamarupang si Leban ma ka'a.",
        13: "Aku ya Tuhan bay magpa'nda' ma ka'a ma lahat Betel. Ya na lahat bay pamat'nggehannu batu pangentomannu ma aku, lahat isab bay pagnajalannu. Na,’ yukna, ‘magsakap na ka buwattina'an bo' ka amole' pehē' ni lahatnu porol.’”",
        14: "Na anambung disi Rakiya maka si Leya. Yuk sigām ma si Yakub, “Tuwan, halam aniya' pusaka' taholat kami min si Mma'.",
        15: "Tahinang kami sali' a'a liyu, ngga'i na ka anakna lissi. Bang pinagbahasa, in kami itu sali' dagangan pinab'llihan e'na, sagō' aubus e'na b'llihanna.",
        16: "Ya kataluwa'anna, in pangalta' bay kala'anan e' Tuhan min si Mma' palsuku'an na ma kami maka ma saga ka'anakantam. Angkan na, tuwan, beya'un sadja ai-ai panoho'an Tuhan ma ka'a.”",
        17: "Manjari itu magsakap na si Yakub amole' pehē' ni mma'na ma lahat Kana'an. Pinakura' e'na anak-h'ndana ma saga unta', maka pinal'ngngan saga ba'anan hayopna kamemon dahū min iya. Binowa isab ai-aina kamemon ya bay tausahana t'ggolna bay ma lahat Mesopotami.",
        18: "Manjari itu magsakap na si Yakub amole' pehē' ni mma'na ma lahat Kana'an. Pinakura' e'na anak-h'ndana ma saga unta', maka pinal'ngngan saga ba'anan hayopna kamemon dahū min iya. Binowa isab ai-aina kamemon ya bay tausahana t'ggolna bay ma lahat Mesopotami.",
        19: "Na, alikut pa'in si Leban magguntingan bulbul saga bili-bilina, tinangkaw saga ta'u-ta'u pagtutuhananna e' anakna si Ripka.",
        20: "Jari si Leban bangsa Aram bay kalimbungan e' si Yakub, pagka halam pinata'u pasal mohot si Yakub ala'an na amole' ni lahatna.",
        21: "Jari magdai'-dai' si Yakub ala'an maka e'na amowa ai-ai palsuku'anna kamemon. Pauntas iya ni dambila' sapa' Alpurati bo' patudju pehē' ni kabūd-būran ma lahat Giliyad.",
        22: "Manjari makalabay pa'in t'llumbahangi, kahaka'an si Leban pasal kala'an disi Yakub.",
        23: "Tinurul iya magtūy e' si Leban maka saga kampungna, pitumbahangi ya t'ggol kapanurulna. Yamboho' ta'abutna disi Yakub ma kabūd-būran lahat Giliyad.",
        24: "Jari ma sangom e' aniya' pah'lling Tuhan ma si Leban ma deyom uppina. Yuk Tuhan ma iya, “Amay-amay, da'a sanggupin si Yakub, ai na ka ahāp, ai na ka ala'at.”",
        25: "Na, ina'an disi Yakub pahanti' ma kabūd-būran lahat Giliyad pagabut si Leban ma iya. Pahanti' isab si Leban maka saga kampungna ma tongod ina'an-i.",
        26: "Manjari itu ah'lling si Leban ma si Yakub, yukna, “Otō', angay aku akkalannu? Angay buwattilu pamowanu ma saga anakku? Bā'nu d'nda tasaggaw!",
        27: "Angay ka ala'an patapuk, halam minsan ama'id min aku? Bang ka bay ama'id, bay du pa'in kam tapatulakku ma deyom paglami-lamihan maka saga kalangan. Bay ka isab kabiyulahan maka katambulan.",
        28: "Angay aku halam minsan pasiyumnu ma saga anak-mpuku bo' kami mag'bba sangkahāpan? Dupang-dupang ka maghinang buwattilu!",
        29: "Aniya' kapatutku angala'at ma ka'a, daipara talāng aku dibuhi' e' Tuhan ya pagtuhanan mma'nu, da'a sinō' ananggupan ka'a.",
        30: "Kata'uwanku du bang ai sababna ya angkan ka ala'an. Tu'ud ka angentom lahatnu maka kakampungannu. Sagō' iya paginu-inuhanku, angay tangkawnu saga ta'u-ta'uku?”",
        31: "Anambung si Yakub ma si Leban, yukna, “Bapa', angkan aku halam ama'id min ka'a sabab tināw aku. Pangannalku in saga anaknu d'nda itu niagaw min aku.",
        32: "Sagō' in pasal saga ta'u-ta'unu, Bapa', sitta'aku. Bang hati tabāknu ma deyom duwa'an kami, minsan ma sai-sai, subay iya pinapatay. Itiya' kakampunganta anaksi'. Na, piha'un to'ongan. Bang aniya' tapihanu maitu ai-ai palsuku'annu, ngā'un na.” Tu'ud awam si Yakub, halam tasayuna in si Rakiya bay anangkaw saga ta'u-ta'u ya pagtuhanan mma'na.",
        33: "Manjari tolda si Yakub ya pamiha'an si Leban dahū. Pasunu', tolda si Leya, bo' ni deyom tolda duwangan ipatan d'nda. Sagō' halam tabāk maina'an saga ta'u-ta'u. Pagpuwas, pasōd na isab iya ni deyom tolda si Rakiya.",
        34: "Na in ta'u-ta'u itu bay tinapukan asal e' si Rakiya ma pakol unta'na bo' tiningkō'an e'na. Makasōd pa'in si Leban, agsai binulangkayat e'na duwa'an kamemon ya ma deyom tolda inān, sagō' halam aniya' tapihana.",
        35: "Ah'lling si Rakiya ma mma'na, yukna “Mma', da'a pa'in ala'at ataynu ma aku. Ampunun aku, sabab itiya' aku binulan, ya po'on aku mbal makat'ngge ma kamaitunu.” Na, minsan buwattingga e' si Leban amiha ta'u-ta'una inān, halam to'ongan tabāk maina'an.",
        36: "Manjari akalintaw si Yakub, angkan yukna ma mato'ana, “Ai dusaku? Sara' ai bay talanggalku ya angkan aku turulnu pi'itu?",
        37: "Tajagjagnu duwa'anku kamemon. Aniya' bahā' suku'nu tabāknu mailu? Bang hati aniya', paluwasun kono' pi'itu ma pang'nda'an saga lahasiya'ta itu ati sigām ya maghukum ma kita duwangan bang sai magsab'nnal, ka'a ka atawa aku.",
        38: "“Duwampū' tahun,” yuk si Yakub, “bay t'ggolku ma deyomannu. Halam aniya' bili-bilinu atawa kambingnu kapulakan. Maka halam aku bay makakakan minsan dakayu' kambingnu l'lla.",
        39: "Tiyap-tiyap bang aniya' hayop tatanggal e' sattuwa talun, halam bay bowaku ni ka'a. Sagō' akuhanku sinambi'an minsan ngga'i ka suku'ku. Maka bang aniya' hayopnu tinangkaw sumiyan-sumiyan, llaw ka atawa sangom, patanggungnu na pa'in ma aku, soho'nu ginanti'an ma aku.",
        40: "Buwattē' na pa'in bay kahālanku. Kapasu'an aku sidda ma ka'llawan, kahaggutan ma waktu sangom. Ai na ka llaw, ai na ka sangom, halam ahāp e'ku atuli.",
        41: "Buwattē' sadja kahālanku ma deyomannu duwampū' tahun t'ggolna. Sangpū' maka mpat tahun isab ya t'ggolku maghinang ma ka'a supaya ta'ā'ku h'nda duwangan anaknu itu. Nnom tahun isab ya kapaghinangku ma ka'a supaya aniya' saga hayop ma aku. Aheya asal untungnu min aku, sagō' minsan na, min pila bay pagpinda-pindanu panganggadjinu ma aku.",
        42: "Daipara nientom aku e' Tuhan, ya pagtuhanan mbo'ku si Ibrahim, ya pagmatāwan mma'ku si Isa'ak. Bang aku halam bay bogboganna, arak aku bay patulaknu ma halam aniya' ai-ai tabowaku. Saguwā' ta'nda' e' Tuhan katiksa'anku sampay lu'ug-liksa'ku ma deyomannu. Ya he' sababna angkan ka'a nilāng e'na dibuhi'.”",
        43: "Ya sambung si Leban ma si Yakub, “Aku ya tag-dapu ma ai-ai kamemon ilu. H'ndanu ilu, anakku du. Anaknu ilu, mpuku du. Kaba'anan hayop ilu, aku ya tag-dapuna. Saguwā' minsan na, halam na aniya' dapatku angokoman saga anakku maka ka'anakan sigām.",
        44: "Manjari Otō', in kita itu subay magjanji' buwattina'an. Subay kita amangkat batu isab pangentoman supaya mbal takalipatta.”",
        45: "Magtūy aniya' batu dansolag pinuwa' e' si Yakub niosol maina'an.",
        46: "Yuk isab si Yakub ma saga a'ana, “Angahangkut kam batu pinatumpuk pi'itu.” Pagubus, mahē' na sigām amangan ma bihing tumpukan batu he'.",
        47: "Na ya pangōn si Leban ma tumpukan batu he' bang ma bahasa sigām, ‘Jegar Sahaduta.’ Ya pangōn si Yakub, ma bahasana isab, ‘Gale'ed.’",
        48: "Ya pamissala si Leban ma si Yakub, “Ya tumpukan batu itu paltanda'an in kita duwangan bay makapagjanji' ma llaw itu.” Angkanna tumpukan e' kaōnan Gale'ed.",
        49: "Niōnan Mispa isab ma sabab kabtangan si Leban, ya yukna, “Bang pa'in kita pineyanan e' si Yawe sat'ggolta magsaddī lahat.”",
        50: "Aniya' gi' lling si Leban, yukna, “Bang ka saupama aminjala' saga anakku itu atawa magh'nda ma d'nda saddī, entomun to'ongan, ilu du Tuhan ang'nda' ma kita minsan halam aniya' makata'u.",
        51: "“Nda'un isab,” yuk si Leban, “tumpukan batu itu maka batu bay osolanta.",
        52: "Paltanda'an ko' itu ma kita duwangan ma pasal paljanji'anta dakayu'. In aku itu mbal paliyu min tumpukan batu itu angala'at ma ka'a. Damikiyanna isab, in ka'a ilu mbal paliyu min batu itu angala'at ma aku.",
        53: "Na, mura-murahan bang pa'in kita nihukum e' Tuhan ya pagtuhanan mbo'nu si Ibrahim maka pagtuhanan mbo'ku si Nahor.” Manjari anapa na si Yakub ma ōn Tuhan ya pagmatāwan e' mma'na si Isa'ak. Ya pagsapana in iya amogbog ma paljanji'an sigām.",
        54: "Sakali itu, aniya' hayop sinumbali' e' si Yakub maina'an pagkulbananna ni Tuhan. Nilinganan isab saga kakampunganna sinō' magjamu. Jari maina'an sigām magtulihan ma bihing būd inān.",
        55: "Pagdai' llaw pa'in siniyum e' si Leban saga mpuna maka saga anakna. Niamu'-amu'an isab sigām kahāpan bo' yampa iya amole' ni lahatna.",
    },
    32: {
        1: "Ya du si Yakub bay pauntas ni patudjuhanna. Sakali itu, ma labayan pa'in, aniya' saga mala'ikat min Tuhan anampang iya.",
        2: "Ya lling si Yakub pag'nda'na ma sigām, “Kilāku, pat'nna'an kasundaluhan Tuhan ko' itu.” Ati Mahanaim ya pangōnna ma lahat inān.",
        3: "Manjari aniya' panoho'an si Yakub ma saga a'ana, yukna, “Parahū kam min aku ni danakanku si Esaw, ina'an ma jadjahan Se'er, ma lahat Edom.",
        4: "Ya llingbi ma iya subay buwatittu, ‘Tuwan, aniya' itu lapal min atanu si Yakub. Yuk lapal itu, “At'ggol aku bay maglahat ma deyoman si'itta si Leban. Halam aku bay magla'an-la'an minnē'.",
        5: "Aheka na hayop palsuku'anku, buwat saga sapi', kura', bili-bili, maka kambing. Aheka na isab saga sosoho'anku d'nda-l'lla. Manjari, tuwan, ya angkan pabowaku lapal itu ni ka'a, bang pa'in aku taima'nu magatay pote'.”’”",
        6: "Sakali itu, makabīng pa'in saga a'a bay pamabowahan lapal si Yakub, aniya' pangahaka sigām ma iya, yuk-i, “Tuwan, bay kami patampal pehē' ni danakannu si Esaw, maka ilu'un na iya pasampang ma ka'a. Aniya' ma iya saga tendogna mpat hatus hekana.”",
        7: "Na, sinōd tāw magtūy si Yakub, aheya to'ongan kasusahanna, angkan binahagi' duwa saga a'a ya bebeya'anna. Ya du ba'anan hayopna sampay saga unta'na, binahagi' duwa isab.",
        8: "Ya ma deyom pikilan si Yakub, bang si Esaw ganta' pina'an amono' sigām, makal'ppa sigām dabahagi'.",
        9: "Jari angamu'-ngamu' si Yakub ni Tuhan, yukna, “O Tuhanku, ka'a ya pagtuhanan mbo'ku si Ibrahim maka mma'ku si Isa'ak, angamu' aku tabang ma ka'a. O Yawe, ka'a ya bay anoho' aku subay amole' ni lahatku maka ni kakampunganku. Bay aku janji'annu isab in aku buwanannu kahāpan ma ai-ai hinangku.",
        10: "Atanu aku, a'a mbal tinōp subay nihāp e'nu. Sagō' minsan na, aheya ase' maka lasanu ma aku. Waktu lagi' kauntasku ni dambila' sapa' Jordan, halam aniya' tabowaku, luwal la'a dakayu' tungkud ma tanganku. Saguwā' ma buwattina'an itiya' na aku magduwa tumpukan ma labayan tudju amole'.",
        11: "O Tuhan, tabangin aku sabab aheya kagawahanku ma siyakaku si Esaw. Pi'itu iya arai' amono' aku sampay saga anak-h'ndaku.",
        12: "Entomun lagi' bay paljanji'annu ma aku, in aku buwanannu kahāpan, maka buwanannu aku tubu' mbal taitung hekana, sapantun heka solagan gusung ma bihing tahik.” Ya na he' pangamu'-ngamu' si Yakub ma Tuhan.",
        13: "Manjari pahanti' iya maina'an dambahangi. Pagsubu, amene' iya hayop aheka pamasampangna ma si Esaw.",
        14: "Ya tapene'na duwa hatus kambing d'nda maka duwampū' kambing l'lla, duwa hatus bili-bili d'nda maka duwampū' bili-bili l'lla,",
        15: "t'llumpū' unta' d'nda taga-anak masi anganduru', mpatpū' sapi' d'nda maka sangpū' sapi' mandangan, duwampū' kura' d'nda maka sangpū' kura' l'lla.",
        16: "Jari pinagbahagi' magba'an-ba'an saga hayop itu e' si Yakub ati patunggu'anna ma saga a'ana. Ya panoho'anna ma sigām, “Pauntas kam dahū min aku. Paglawak-lawakunbi isab saga hayop ilu damba'an maka damba'an.”",
        17: "Aniya' isab pamandu'na ma sosoho'anna dakayu' ya parahū min kamemon, yukna, “Bang ka saupama talanggal e' siyakaku, bo' yukna ma ka'a, ‘Pi'ingga ka, maka sai nakura'nu, maka sai isab tag-dapu saga hayop ilu?’",
        18: "Ya panambungnu ma iya subay buwattitu. Yuknu, ‘Tuwan, atanu si Yakub ya tag-dapu itu kamemon. Sinō' binowa pi'itu ni ka'a kasampangan. Ilu'un na iya paturul min buli'an.’”",
        19: "Ya du panoho'an si Yakub ma saga a'ana magsunu'-sunu' ya tag-tunggu'an saga hayop kasehe'. Yukna, “Bang kam ganta' talanggal e' siyakaku si Esaw, ya pangahakabi ma iya subay buwattitu,",
        20: "‘Aho' tuwan, ilu'un du atanu si Yakub paturul min buli'an.’” Ya ma deyom pikilan si Yakub, bang aniya' kasampangan pinabeya'an si Esaw dahū gi' min kapaglanggal sigām, kalu ahāp atayna tudju ni si Yakub ati magkahāp sigām pabīng.",
        21: "Manjari pinarahū e' si Yakub kasampanganna inān kamemon. Sagō' si Yakub baranna angagad gi' ma pahanti'an sigām dambahangi.",
        22: "Na, ma sangom inān, papunduk si Yakub min patulihanna. Niā' h'ndana karuwangan maka ipatan sigām, sampay anakna l'lla kasangpū' maka dda. Ni'nde'an sigām e'na pehē' ni dambila' sapa' Jabbok.",
        23: "Ma dambila' pa'in saga anak-h'ndana, pinauntas isab e' si Yakub kaniya'na kamemon.",
        24: "Sagō' in iya baranna pat'nna' dangan-danganna ma tongod ina'an. Sakali aniya' magpasalupa ma si Yakub amowa iya magkosogan sampay asekot ni karai'-llawan.",
        25: "Na, pagnanam e' a'a inān in si Yakub mbal tara'ugna, magtūy tibu'na ma pangkulna ati magsā' lo'atanna.",
        26: "Ya yuk a'a-i ma iya, “Bbahin aku, marai' na llaw.” Anambung si Yakub, yukna, “Ē, mbal ka bbahanku. Subay ka amuwanan aku barakat dahū.”",
        27: 'Manjari tinilaw si Yakub bang sai ōnna. “Si Yakub,” yukna.',
        28: "Angabtang a'a inān, yukna, “Ngga'i ka na Yakub ya pangōn ka'a puwas minnitu, sagō' si Isra'il na, ma sabab kapagkosognu maka Tuhan maka ma pagkahinu manusiya'. Bay tara'ugnu sali'-sali'.”",
        29: "Ah'lling gi' si Yakub, “Tuwan, pahati'un aku kono' bang sai ōnnu.” Anambung a'a-i, yukna, “Oy, angay tilawnu ōnku?” Manjari barakatanna si Yakub.",
        30: "Ya pah'lling si Yakub, “Arī, magharap aku maka Tuhan, bo' pa'in itiya' aku masi allum.” Angkanna lahat inān niōnan Peniyēl e' si Yakub.",
        31: "Yamboho' paluwas mata llaw ma waktu kalanjal si Yakub min lahat Peniyēl e'. Magpengka'-pengka' isab iya ma sabab dambila' lo'atan pangkulna magsā'.",
        32: "Ya he' sababna angkan bangsa Isra'il mbal to'ongan amangan ugat sumbali'an ya ma lo'atan pangkul. Ya ina'an addat sigām sampay ni kabuwattituhan, tu'ud nientom mbo' sigām si Yakub bay waktu kapanibu' pangkulna.",
    },
    33: {
        1: "Manjari itu, maka'nda' pa'in si Yakub ni dahuanna, ilu na si Esaw maka saga tendogna mpat hatus puhu'. Magtūy pinapagtumpuk e' si Yakub saga onde'-onde' maka kaina'an sigām magkaniya-kaniya.",
        2: "Ya pinarahū e'na si Bilha maka si Silpa sampay saga anak sigām. Pasunu' disi Leya maka saga anakna, ati karamulihan si Rakiya maka anakna si Yusup.",
        3: "Si Yakub baranna ya parahū min kamemon. Na, asekot-sekot pa'in iya ni si Esaw, magtūy iya pasujud min pitu' pagaddatna ma siyakana.",
        4: 'Malaingkan si Esaw paragan anampang si Yakub. Anganggapus iya maka aniyum, ati magtangis sigām karuwangan.',
        5: "Pag'nda' si Esaw ma saga kar'ndahan maka saga onde'-onde', atilaw iya ma si Yakub, yukna, “Sai kasehe'annu ilu?” Ya sambung si Yakub, “Kaka' tuwan, ya na itu ka'anakan bay pangalidjiki' Tuhan ma aku, ya atanu itu.”",
        6: "Manjari pasōng isab saga ipatan si Yakub maka ka'anakan sigām, ati pasujud ma dahuan si Esaw.",
        7: "Pasunu' isab si Leya maka saga anakna, karamulihan si Rakiya maka anakna si Yusup, pasujud sigām kamemon.",
        8: "Atilaw gi' si Esaw, yukna, “Pamagay ba'anan tumpukan hayop bay talanggalku ma lān ina'an? Ai kagunahanna?” Ya sambung si Yakub, “Ya kagunahanna, Kaka' tuwan, pamuwanku ma ka'a pamahāp ataynu tudju ni aku.”",
        9: "Yuk si Esaw, “Otō', da'a na. Aheka du ma aku. Mailuhun na ma ka'a.”",
        10: "Yuk si Yakub, “Ndū', Kaka' tuwan, bang sab'nnal-b'nnal ahāp na ataynu ma aku, taima'un kasampanganku itu ma ka'a. Ya pagharapku maka ka'a llaw itu, sali' hantang pagharapku maka Tuhan, sabab ahāp sidda pamaihu'annu ma aku.",
        11: "Taima'un, Kaka' tuwan, ya kasampanganku itu ma ka'a, sabab aheya kahāpan ya bay pamuwan Tuhan ma aku. Halam aniya' kulang ma aku.” Jari tinaima' na e' si Esaw pagka tapogos e' si Yakub.",
        12: "“Na,” yuk si Esaw, “Sūng na kitam. Sehe'anta kam.”",
        13: "Sagō' mbal si Yakub. Yukna, “Kaka' tuwan, kata'uwannu du. Alamma saga onde'-onde' itu. Maka pagsusahanku isab saga bili-bili maka saga sapi' taga-anak duru'an lagi'. Bang puspusanta pal'ngngan minsan dang'llaw sadja, marai' magpatayan du kamemon.",
        14: "Ndū', Kaka',” yuk si Yakub ma si Esaw, “parahū gi' ka min kami. Kami maka saga anakku sampay saga ba'anan hayop itu subay paturul min damuliannu. Painut-inut sadja kami pal'ngngan sampay ka ta'abutku mahē' ma lahat Se'er.”",
        15: "“Na aho', Otō',” yuk si Esaw. “Bbahanku isab saga a'aku pagapi' ma ka'am.” Yuk si Yakub, “Minsan mbal na, Kaka' tuwan. Ya sadja aheya ma aku bang pa'in ahāp na ataynu ma aku.”",
        16: "Manjari ma llaw ina'an-i magpamole' na disi Esaw ni lahatna Se'er.",
        17: "Sagō' si Yakub iya pehē' gom pa'in ni lahat Sokkot. Ma Sokkot pa'in, angahinang iya luma' pat'nna'anna maka saga anak-h'ndana. Angahinang isab iya saga kamalig pasindungan ba'anan kahayopanna. Ya he' sababna angkan lahat inān niōnan Sokkot.",
        18: "Ya hatulanna, makapole' pa'in si Yakub min lahat Mesopotami, at'kka na ni lahat Kana'an ma halam aniya' baya-baya. Tat'kkana da'ira Sekem ati maina'an iya magpat'ngge tolda pagluma'an sigām, ina'an ma anggopan da'ira.",
        19: "Manjari ya tana' pat'nna'an sigām inān bay bin'lli e'na min saga panubu' si Hamor mma' si Sekem, dahatus pilak tibu'uk ya pam'llina.",
        20: "Aniya' isab pagtunu'an kulban nihinang e' si Yakub ma tana' ina'an. El-Elohe-Isra'il ya pangōnna ma pagkukulbanan inān.",
    },
    34: {
        1: "Na, aniya' anak si Yakub maka si Leya budjang, ōnna si Dina. Dakayu' llaw pal'ngngan si Dina itu anibaw saga bagayna d'nda, a'a Kana'an.",
        2: "Jari ta'nda' iya e' si Sekem anak si Hamor, ya pagbebeya'an ma lahat inān. (A'a bangsa Hīb disi Hamor itu.) Pag'nda' si Sekem ma si Dina, magtūy saggawna bo' yampa usiba'anna.",
        3: "Sagō' ka'amuhan iya ma si Dina he' maka sinōd lasa. Jari bissalahanna pahāp-hāp, kalu tabowa alasa isab ma iya.",
        4: "Yuk si Sekem ma mma'na si Hamor, “Mma', pah'nda'un ma aku d'nda itu.”",
        5: "Sakali itu, makata'u pa'in si Yakub pasal pangusiba' itu ma anakna si Dina, halam aniya' tapah'llingna pasal palkala' itu. Subay na bay makapole' saga anakna min kaparangan, min hinang sigām anunggu' kahayopan.",
        6: "Manjari si Hamor, ya mma' si Sekem-i, pehē' ni si Yakub amowa iya maggara'.",
        7: "Maina'an isab saga anak si Yakub l'lla baha'u bay at'kka min deya. Kahaka'an pa'in sigām pasal palkala' itu, magtūy sigām astolan makalandu' ma sabab pangusiba' si Sekem ma danakan sigām si Dina. Mbal to'ongan manjari, talapay saga a'a Isra'il kamemon nihinangan kaiya'an.",
        8: "Ah'lling si Hamor ma si Yakub maka saga anakna-i, yukna, “Ndū' tuwan, in anakku si Sekem itu aheya to'ongan baya'na ma anaknu si Dina. Taima'un iya, pah'nda'un ma anaknu.",
        9: "Ahāp kitam magpikit-pikiti d'nda maka l'lla.",
        10: "Bang hati buwattē', makapaglahat du kam maitu maingga-maingga kabaya'anbi pat'nna'an. Aluhaya du kam angusaha maitu, makajari isab am'lli tana'.”",
        11: "Ah'lling isab si Sekem ma mma' si Dina sampay ma saga danakanna, yukna, “Ndū', saga Tuwan, bang pa'in aku makasulut ataybi. Ai-ai amu'bi ma aku pamuwanku du ma ka'am.",
        12: "Haka'inbi aku bang pila ungsudna maka sokatna ati akuhanku du, bang aku pakawinbi ma si Dina.”",
        13: "Sagō' angakkal saga anak si Yakub ma si Sekem maka mma'na si Hamor, ma sabab pangusiba'na ma danakan sigām si Dina.",
        14: "Yuk sigām, “Ē, mbal makajari. In danakan kami itu mbal tapah'lla ma l'lla halam bay taislam. Kaiya'an ko' ilu ma kami.",
        15: "Magsulut du kitam bang pa'in ni'islam kal'llahanbi kamemon, buwat pagislam ma kami.",
        16: 'Jari magpikit-pikiti du kitam. Magdalahat kitam magdabangsa.',
        17: "Malaingkan bang kam mbal ameya' ma gara' kami itu, pagka mbal bilahi magislam, na, ngā' kami na danakan kami d'nda itu bo' ala'an minnitu.”",
        18: "Manjari kasulutan si Hamor maka anakna si Sekem ma gara' bay nihūgan sigām e' saga anak si Yakub e'.",
        19: "Mbal pa'in at'ggol, bineya' e' si Sekem gara' sigām ma sabab baya'na ma si Dina anak si Yakub. Si Sekem ya pinagaddatan asal labi min kakampunganna kasehe'an.",
        20: "Manjari pehē' na iya maka mma'na si Hamor ni tongod pasōran da'ira bo' amowa magisun saga l'lla ya magtipun maina'an.",
        21: "Yuk sigām, “Saga tuwan, in bangsa Isra'il itu patibagayun asal. Ahāp bang sigām tugutanta maglahat maitu maka magusaha isab ma deyom kaluhaya'an, sabab aluha asal lahattam. Ahāp isab bang tugutantam saga anak sigām subul-budjang magkawin-kiyawani maka anaktam.",
        22: "Saguwā' mbal gi' sigām makajari magdalahat-magdabangsa maka kitam. In kitam kal'llahan subay magislam dahū buwat kapagislam ma sigām.",
        23: "Manjari bang beya'ta addat sigām e', in hayop sigām kamemon maka pangalta' sigām kamemon ma kitam du ma waktu sinōng. Jari patut bahā' bang kitam magsulut supaya sigām maglahat maitu ma kitam?”",
        24: "Manjari kasulutan saga l'lla ma da'ira inān kamemon. Bineya' e' sigām gara' si Hamor maka anakna si Sekem ati magislam sigām kamemon.",
        25: "Na, palabay pa'in t'llumbahangi min bay pagislam e', bo' halam gi' kauli'an, pina'an na duwangan anak si Yakub l'lla, si Simiyun maka si Libi ya langgung si Dina. Pasōd sigām magtakos kalis ni deyom da'ira inān ma halam aniya' pangalab-ngalab saga a'a maina'an. Jari nilagut pinapatay saga l'lla inān kamemon e' sigām karuwangan.",
        26: "Talapay isab si Hamor maka anakna si Sekem pinapatay. Si Dina iya niā' e' sigām min deyom luma' si Sekem.",
        27: "Magpatayan pa'in saga a'a itu, paturul isab saga anak si Yakub kasehe'an anaban kamemon ai-ai bay ma deyom da'ira. Ya he' pamalos sigām ma kaiya'an danakan sigām budjang.",
        28: "Tinaban e' sigām pangalta' kamemon ma deyom-luwasan da'ira inān, buwat saga kambing, bili-bili, sapi' maka kura', hatina ai-ai taga-guna.",
        29: "Tinaban pangalta' kamemon bay ma deyom luma', sinaggaw isab saga d'nda maka kaonde'an kamemon.",
        30: "Na, kinata'uwan pa'in e' si Yakub hinang si Simiyun maka si Libi itu, magtūy pah'llinganna sigām. Yukna, “Arōy! Aheya kasusahan ya pamuwanbi itu ma aku. Binantahan du aku e' saga bangsa Kana'an maka bangsa Pirissi sampay bangsa a'a kamemon ma lahat itu. Ariki' du kitam. Bang sigām ganta' magdakayu' pi'itu angandugpak, tantu kitam alaglag kamemon magtai'anak.”",
        31: "Ya sambung si Simiyun maka si Libi, “Pasagaranta bahā' bang danakan kami si Dina tahinang sali' d'nda pinagtatambahan?”",
    },
    35: {
        1: "bdNa aniya' panoho'an Tuhan ma si Yakub, yukna, “Patukad ka ni Betel bo' ka maglahat mahē'. Hinangun pagtunu'an isab mahē' pagkulbanannu ma aku, ya Tuhan bay magpa'nda' ma ka'a waktu lagi' kalahinu min siyakanu si Esaw.”",
        2: "Ah'lling si Yakub ma saga anak-h'ndana sampay ma saga a'a bebeya'anna kamemon, yukna, “Timaninbi saga ta'u-ta'u kamemon ya pagtutuhananbi ilu. Sussihunbi baranbi pahāp bo' yampa kam magsalinan badju' al'ssin.",
        3: "Pagubus, patukad kitam ni Betel ati angahinang aku pagkulbanan maina'an pangarapan ni Tuhan ya bay anabangan aku ma waktu kasukkalanku. Ginapi' na pa'in aku e'na pi'ingga-pi'ingga bay pal'ngngananku.”",
        4: "Manjari bineya' lling si Yakub e' saga a'ana inān ati sinōngan ni iya saga ta'u-ta'u sigām kamemon sampay saga aretes bay ma tainga sigām. Jari kinubul kamemonna e' si Yakub ma tongod po'on kayu pagduwa'ahan ya ma Sekem.",
        5: "Pagubus, pasalta' pa'in disi Yakub atulak minnē', pinat'kkahan tāw aheya saga a'a ma kakauman Sekem angkan sigām mbal makatawakkal anurul disi Yakub amalos.",
        6: "Manjari itu magt'kkahan na si Yakub sampay saga a'ana kamemon ni Lūs, ya pinagōnan Betel ma tahun damuli itu. Ma lahat Kana'an ko' inān.",
        7: "Aniya' pagtunu'an kulban nihinang e' si Yakub mahē'. El-Betel ya pangōnna ma lahat inān, sabab ya na lahat bay pagpa'nda'an Tuhan ma iya waktu bay kalahina min siyakana.",
        8: "Amatay na si Debora, ya d'nda bay angayurahan si Ripka min kariki'-diki'na gi'. Takubul iya ma tongod dakayu' po'on kayu ya ma lūran lahat Betel. Allon Bakut (hatina Kayu Pagkarukka'an) ya pangōn a'a ma kayu inān.",
        9: "Na, ma waktu kapamole' si Yakub min lahat Mesopotami, bay magpa'nda' Tuhan ni iya pabalik maka amuwanan iya kahāpan.",
        10: "Ya pangallam Tuhan ma iya, “Ōnnu si Yakub sagō' puwas itu ngga'i ka na si Yakub ya pangōn ka'a, sagō' si Isra'il na.” Hatina Tuhan to'ongan ya bay angōnan iya si Isra'il.",
        11: "Manjari angallam na isab Tuhan ma iya, “Aku itu Tuhan Sangat Kawasa. Anganak ka paheka, manjari ma waktu sinōng aniya' kabangsa-bangsahan patubu' min ka'a. Lāgi aniya' saga sultan isab luwa' min panubu'nu.",
        12: "Ya lahat bay pamuwanku ma mbo'nu si Ibrahim maka mma'nu si Isa'ak pamuwanku isab ma ka'a sampay ma saga panubu'nu.”",
        13: "Pagubus, ala'an na Tuhan min lugal bay pagsuli-sulihanna maka si Yakub.",
        14: "Na maina'an, ma tongod bay pangallaman Tuhan ma iya, aniya' batu niosolan e'na. Taosol pa'in, binusug e' si Yakub binu-anggul maka ns'llan jaitun ma diyata'na panukbal ni Tuhan.",
        15: "Manjari Betel ya pangōn si Yakub ma lahat ina'an-i.",
        16: "Pagpuwas, palanjal na si Yakub maka saga anak-h'ndana min Betel inān. Na alawak-lawak lagi' sigām min kauman Eprata, ta'abut na bulanan si Rakiya anganak. Kahunitan iya to'ongan.",
        17: "Jari itu, pagka makalandu' hunitna, yuk panday ma iya, “Ndū', Rakiya, da'a ka tināw, l'lla ko' itu.”",
        18: "Song pa'in ab'kkat napasna, si Benoni (hatina ‘anak kasusahanku’) ya ōn pang'bba si Rakiya ma anakna. Manjari amutawan na iya. Saguwā' Benjamin ya pangōn si Yakub ma onde'-onde' he'.",
        19: 'Pagka amatay na si Rakiya, kinubul iya ma bihing lān tudju ni kauman Eprata, ya pinagōnan Betlehem ma tahun damuli itu.',
        20: "Jari aniya' batu lakit niosolan e' si Yakub, batu panganggindanan kubul si Rakiya. Ina'an du isab sampay ni buwattina'an.",
        21: "Pagpuwas, palanjal na disi Yakub (ya pinagōnan isab si Isra'il) ati magpat'ngge tolda pagluma'an sigām ma liyuhan Migdal-Eder.",
        22: "Sakali itu, waktu lagi' disi Isra'il pat'nna' ma liyuhan Migdal-Eder inān, makapagbihing anakna si Rubin maka h'nda-h'ndana si Bilha. Kahaka'an si Yakub pasal ina'an-i angkan akagit atayna. Na, si Yakub itu, sangpū' maka duwa anakna l'lla.",
        23: "Ya itu saga anakna min si Leya: si Rubin ya pagsiyakahan, bo' si Simiyun, si Libi, si Yahud, maka si Issakar, si Sibulun ya kasiyalihan.",
        24: "Saga anak si Yakub min si Rakiya: si Yusup ya siyaka, bo' si Benjamin.",
        25: 'Anakna isab min si Bilha ya ipatan si Rakiya: si Dān maka si Naptali.',
        26: "Anakna isab min si Silpa ya ipatan si Leya: si Gād maka si Aser. In sangpū' maka duwa anak si Yakub l'lla itu bay nianakan ma lahat Mesopotami.",
        27: "Manjari at'kka na si Yakub ni mma'na si Isa'ak ma lahat Mamre (hatina lahat Hebron), ya na lahat bay paglahatan si Isa'ak maka si Ibrahim.",
        28: "Na, ta'abut pa'in dahatus maka walumpū' tahun umul si Isa'ak,",
        29: "awapat na iya ma deyom kasannangan, ati pinapagtimuk iya maka ka'mbo'-mbo'anna. Takubul iya e' anakna karuwangan si Esaw maka si Yakub.",
    },
    36: {
        1: "Ya na itu salsila panugsugan saga panubu' si Esaw, ya pinagōnan isab si Edom.",
        2: "Min lahat Kana'an h'ndana kat'llungan. H'ndana dakayu' si Ada anak si Elon, a'a bangsa Hīt. Karuwana si Oholebama anak si Ana anak si Sebeyon, a'a bangsa Hīb.",
        3: "Kat'lluna si Basemat anak si Isma'il, ya magdanakan maka si Nebayot.",
        4: 'Si Elepas ya anak si Esaw min si Ada, si Ruwil iya anakna min si Basemat.',
        5: "Saga anakna min si Oholebama, ya na si Jiyus, si Jalam maka si Kora. In itu kamemon bay nianakan ma si Esaw ma lahat Kana'an.",
        6: "Manjari aniya' waktu pabutas na si Esaw min siyalina si Yakub, maglain ni lahat saddī. Tabeya' ma iya saga anak-h'ndana sampay saga tendogna kamemon. Tabowa isab kahayopanna sampay pangalta'na kamemon bay tausahana ma lahat Kana'an.",
        7: "Ya angkan si Esaw pabutas min si Yakub, sabab aheka makalandu' ba'anan hayop ya suku' sigā karuwangan, mbal s'ddong ma tana' bay paglahatan sigā he'. Mbal na sigā makapagdakayu' lahat.",
        8: "Manjari si Esaw, hatina si Edom, pehē' na ni kabūd-būran lahat Se'er bo' maglahat mahē'.",
        9: "Ya na itu isab salsila panugsugan panubu' si Esaw, ya pang'mbo'an bangsa Edom, a'a kabūd-būran Se'er.",
        10: "Saga anak si Esaw l'lla: Si Elepas ya anakna min h'ndana si Ada, si Ruwil ya anakna min h'ndana si Basemat.",
        11: "Saga anak si Elepas l'lla: si Teman, si Omar, si Sepo, si Gatam maka si Kenas.",
        12: "Aniya' h'nda-h'nda isab si Elepas, ōnna si Timna, ya bay anganakan l'lla, ōnna si Amalek. Ya du ina'an saga mpu si Esaw min h'ndana si Ada.",
        13: "Saga anak si Ruwil l'lla: si Sera, si Samma maka si Missa. Ya du ina'an saga mpu si Esaw min h'ndana si Basemat.",
        14: "Aniya' gi' anak si Esaw l'lla min h'ndana si Oholebama anak si Ana, mpu isab si Sebeyon: si Je'us, si Jalam maka si Kora.",
        15: "Itiya' na saga datu' bay patubu' min si Elepas anak si Esaw siyaka: si Teman, si Omar, si Sepo, si Kenas,",
        16: "si Kora, si Gatam maka si Amalek. Si Ada h'nda si Esaw ya mbo' saga a'a magdaratu' itu ya bay panubu' si Esaw.",
        17: "Saga datu' isab bay patubu' min si Ruwil ya anak si Esaw dakayu': si Nahat, si Sera, si Samma maka si Missa. Si Basemat h'nda si Esaw ya mbo' sigām.",
        18: "Saga anak si Esaw isab min h'ndana si Oholebama anak si Ana: si Je'us, si Jalam maka si Kora, a'a magdaratu' kamemon.",
        19: "Manjari ya du ina'an saga bangsa maka ba'anan datu' sigām ya bay patubu' min si Esaw (ya pinagōnan isab si Edom).",
        20: "Na, in pasal saga bangsa porol ma lahat Edom, si Se'er bangsa Hōr ya pang'mbo'an sigām. Saga anak si Se'er ya tahinang datu', ya na si Lotan, si Sobal, si Sebeyon, si Ana, si Disun, si Eser maka si Disan.",
        21: "Na, in pasal saga bangsa porol ma lahat Edom, si Se'er bangsa Hōr ya pang'mbo'an sigām. Saga anak si Se'er ya tahinang datu', ya na si Lotan, si Sobal, si Sebeyon, si Ana, si Disun, si Eser maka si Disan.",
        22: "Saga anak si Lotan: si Hore maka si Homan. Si Timna ya danakan si Lotan d'nda.",
        23: 'Saga anak si Sobal: si Alban, si Manahat, si Ebal, si Sepo maka si Onam.',
        24: "Saga anak si Sebeyon isab: si Aya maka si Ana. Si Ana itu bay makabāk bohe' amukal-mukal ma lahat paslangan, hinabuna magipat saga kura' mma'na.",
        25: "Saga anak si Ana: si Disun ya anakna l'lla, si Oholebama ya anakna d'nda.",
        26: 'Saga anak si Disun: si Hemdan, si Esban, si Itran maka si Keran.',
        27: "Saga anak si Eser anak si Se'er: si Bilhan, si Sa'aban maka si Akan.",
        28: 'Saga anak si Disan: si Ūs maka si Aran.',
        29: "Itiya' na isab ōn saga a'a pagdatu'an kabangsa-bangsahan Hōr ya bay maglahat ma lahat Se'er: si Lotan, si Sobal, si Sebeyon, si Ana, si Disun, si Eser maka si Disan.",
        30: "Itiya' na isab ōn saga a'a pagdatu'an kabangsa-bangsahan Hōr ya bay maglahat ma lahat Se'er: si Lotan, si Sobal, si Sebeyon, si Ana, si Disun, si Eser maka si Disan.",
        31: "Na, ya na itu saga a'a magsusultan ma lahat Edom masa halam gi' aniya' sultan ma bangsa Isra'il.",
        32: "Si Bela anak si Beyor tahinang sultan ma bangsa Edom. Dinhaba ya ōn da'ira pagsultananna.",
        33: "Amatay pa'in si Bela, si Johab anak si Sera' ya pas'lle' aningkō' magsultan. A'a iya min lahat Bosla.",
        34: "Amatay pa'in si Johab, ya pas'lle' magsultan si Husam a'a min jadjahan bangsa Teman.",
        35: "Amatay pa'in si Husam, ya pas'lle' magsultan si Hadad anak si Bedad. Abit iya ōn da'ira pagsultananna. Si Hadad itu bay makara'ug ma bangsa Midiyan ma deyom lahat Mowab.",
        36: "Amatay pa'in si Hadad, ya pas'lle' magsultan si Samla min lahat Masleka.",
        37: "Pagmatay si Samla, ya pas'lle' magsultan si Sa'ul, a'a min lahat Rehobot ma bihing sapa' aheya.",
        38: "Na, amatay pa'in si Sa'ul, ya pas'lle' magsultan si Ba'al-Hanan anak si Akbor.",
        39: "Amatay pa'in si Ba'al-Hanan anak si Akbor, ya pas'lle' magsultan si Hadad. Pau ya ōn da'ira pagsultananna. Si Mehetabel anak si Matered, mpu si Mesahab, ya h'nda si Ba'al-Hanan itu.",
        40: "Itiya' na isab ōn saga datu' bay patubu' min si Esaw, kaniya-kaniya sigām magsaddī-saddī lahat maka bangsa: si Timna, si Alba, si Jetet,",
        41: 'si Oholebama, si Ela, si Pinun,',
        42: 'si Kenas, si Teman, si Mibsar,',
        43: "si Magde'el maka katapusan si Iram. Saga panubu' si Esaw itu kamemon bay datu' ma lahat Edom kaniya-kaniya ma paglahatan sigām. Na, ya na ina'an salsila pasal paltubu'anan si Esaw, ya po'onan bangsa Edom.",
    },
    37: {
        1: "Ya na itu salsila pasal si Yakub maka anak-mpuna. Maglahat asal iya ma Kana'an, ya lahat bay paghanti'an mma'na si Isa'ak. Manjari itu, ya anakna si Yusup wa'i angipat saga hayop sigām, beya' isab saga danakanna l'lla min saddī ina', min si Bilha maka si Silpa. Sangpū' maka pituntahun umul si Yusup ma waktu ina'an-i. Jari sinumbung e' si Yusup saga danakanna itu ni mma' sigām. Aniya' kono' hinang sigām mbal taluwa'.",
        2: "Ya na itu salsila pasal si Yakub maka anak-mpuna. Maglahat asal iya ma Kana'an, ya lahat bay paghanti'an mma'na si Isa'ak. Manjari itu, ya anakna si Yusup wa'i angipat saga hayop sigām, beya' isab saga danakanna l'lla min saddī ina', min si Bilha maka si Silpa. Sangpū' maka pituntahun umul si Yusup ma waktu ina'an-i. Jari sinumbung e' si Yusup saga danakanna itu ni mma' sigām. Aniya' kono' hinang sigām mbal taluwa'.",
        3: "Na, aheya lasa si Yakub ma si Yusup. Salasa-lasa iya ma anakna kasehe', alasa gi' ma si Yusup sabab anak ma kato'ana. Jari pinatahi'an e'na si Yusup juba alingkat.",
        4: "Kinata'uwan pa'in e' saga dauranakan kaheya lasa si Yakub ma si Yusup, labi-labi min lasana ma sigām kasehe'an, magtūy sigām ab'nsi ma iya. Mbal na sigām amissala sangkahāpan ma iya.",
        5: "Manjari itu, aniya' waktu anguppi si Yusup. Kahaka'an pa'in dauranakanna pasal uppina, gom pa'in ab'nsi sigām ma iya.",
        6: 'Yukna ma sigām, “Ā, kalehunbi bay tauppiku.',
        7: "In kitam kamemon bay ma huma magp'kkos pai, manjari ya p'kkosan pai bay ma aku magtūy an'ngge pabontol. Ya du saga p'kkosan pai bay ma ka'am, an'ngge isab bo' patilibut ni p'kkosanku ati pasujud.”",
        8: "Sinambungan si Yusup e' danakanna, yuk sigām, “Ē! Ka'a ilu magsultan bahā' ma kami? Pagbaya'annu kami?” Pasōng gom pa'in kab'nsi sigām ma iya ma sabab uppina maka suli-sulina he'.",
        9: "Pinauppihan na isab si Yusup pabalik ati suli-sulihanna isab saga danakanna. Yukna ma sigām, “Kalehunbi pasal uppiku dakayu' itu. Tauppiku llaw maka bulan sampay saga bitu'un sangpū' maka ssa hekana pasujud ni aku.”",
        10: "Anuli-nuli isab si Yusup ma mma'na pasal uppina itu. Magtūy iya pinah'llingan e' mma'na, yuk-i, “Oy! Uppi ai ilu? Pikilnu bahā' in aku maka ina'nu sampay saga danakannu subay pasujud ni ka'a?”",
        11: "Manjari akagit atay saga danakan si Yusup ma iya. Sagō' kinannal e' mma'na palkala' inān.",
        12: "Manjari dakayu' llaw, pagka maina'an saga danakan si Yusup ma lahat Sekem angipat ba'anan kahayopan ya suku' mma' sigām,",
        13: "aniya' panoho'an si Isra'il (hatina si Yakub) ma si Yusup. Yukna, “Otō', kata'uwannu asal, ina'an saga danakannu ma Sekem angipat hayop. Bilahi aku anoho' ka'a pehē'.” Ya sambung si Yusup, “Aho', Mma', pehē' aku.”",
        14: "Yuk mma'na isab, “Na, pehē' na ka. Tibawun danakannu inān bang ahāp du kahālan sigām maka saga hayopta bo' ka amole' isab pi'itu angahaka'an aku.” Jari pinatulak iya min kapantayan Hebron tudju ni lahat Sekem. Pagt'kkana ni Sekem,",
        15: "hinabuna amiha saga danakanna ma kaparang-parangan, aniya' a'a makalanggal ma iya. Yukna, “Otō', ai pihanu ilu?”",
        16: "Ya sambung si Yusup, “Ya pihaku, tuwan, saga danakanku. Maitu kono' sigām angipat kahayopan kami. Kata'uwannu bahā' tuwan bang maingga sigām?”",
        17: "Yuk a'a inān, “Ā, halam na sigām maitu. Takaleku sigām magsuli-suli, ni lahat Dotan kono'.” Manjari paturul si Yusup ni saga danakanna sampay ta'abutna sigām ma tongod Dotan.",
        18: "Na, alawak-lawak gi' si Yusup, ta'nda' iya he' saga danakanna. Magtūy iya pinagisunan pinapatay e' sigām.",
        19: "Yuk sigām dansehe'an, “O'o, nda'unbi. Ilu na si Pangunguppi.",
        20: "Sūng, bono'ta iya ati timananta baranna ni deyom lowang bay pagtau'an bohe' itu. Ya pangahakata ma pasalna in iya bay pinapatay maka kinakan e' sattuwa talun. Nda'ta minnē' bang ai kapūsan uppina.”",
        21: "Na, pagkale pagisun itu e' siyaka sigām si Rubin, magtūy iya amikil bang buwattingga e'na anabang si Yusup bo' mbal kinala'atan e' saga danakanna. Yukna ma sigām, “Ndū', da'a iya papatayhunbi.",
        22: "Hūgta sadja iya ni lowang itu. Halam aniya' a'a maglahat maitu. Saguwā' da'a iya inay-inayunbi.” Angkan buwattē' lling si Rubin sabab magmaksud iya angā' si Yusup pabalik bo' pinapole' ni mma'na.",
        23: "Ahā, pagt'kka si Yusup pehē' ni saga danakanna, magtūy iya sinaggaw e' sigām bo' niurusan jubana alingkat e'.",
        24: "Puwas e', binowa iya nihūg ni deyom lowang halam bohe'na sabab atigang na.",
        25: "Sakali itu, hinabu saga danakan si Yusup aningkō' amangan, na, aniya' ta'nda' e' sigām saga a'a bangsa Isma'il. Ina'an sigām magturul-turul min lahat Giliyad tudju ni lahat Misil. Aniya' isab dagangan paruwa' ma saga unta' sigām, saga ginisan bulitik pahamut maka ginisan pamapā.",
        26: "Ah'lling magtūy dakayu' danakan sigām ōnna si Yahud, “Ai untungna bang bono'ta siyalita itu bo' limbunganta kamatayna?",
        27: "Gom lagi' iya pab'llihanta ni saga a'a Isma'il itu. Da'a sadja iya mulata sabab danakanta du iya, dalaha' maka kitam.” Manjari kasulutan saga danakan si Yahud ma llingna he'.",
        28: "Manjari itu, makasekot pa'in saga a'a magdaragang e', nihella' si Yusup paluwas min deyom lowang bo' yampa pinab'llihan ma saga bangsa Isma'il e'. Ya b'llihanna duwampū' pilak tibu'uk. Pagb'lli pa'in, tabowa iya pehē' ni lahat Misil.",
        29: "Na, pabalik si Rubin ni lowang bay pangahūgan si Yusup arak angā' iya. Pagdomolna halam maina'an si Yusup, agsai gineret e'na badju'na tanda' sin pagdukkana.",
        30: "Pabīng iya magdai'-dai' ni tongod saga danakanna bo' yukna, “Arōy! Halam maina'an si Yusup! Daka painay hinangku!”",
        31: "Jari, anumbali' sigām kambing ati niledje juba si Yusup maka laha'na.",
        32: "Binowa juba inān amole' bo' pina'nda'an ni mma' sigām. Ya yuk sigām, “Ndū' Mma', nda'un ba bay tabāk kami. Juba si Yusup bahā'?”",
        33: "Takilā magtūy e' si Yakub. “Aho',” yukna. “Ma si Yusup ko' ilu! Kilāku aniya' sattuwa talun bay angā' iya anagpe' baranna. Arōy! Anakku si Yusup!”",
        34: "Magtūy gineret e' si Yakub badju' ma baranna bo' yampa magbinadju' karut, tanda' ma pagkarukka'anna. Jari at'ggol to'ongan pagdukka si Yakub ma anakna.",
        35: "Pina'an ni iya saga anakna d'nda-l'lla bahasa amauli' karukka'anna, saguwā' mbal iya, subay pasangdan magdukka. Angabtang iya, yukna, “Mbal ala'an pagdukkaku ma anakku sampay aku amole' ni ahirat.” Manjari kasangdanan si Yakub magdukka ma anakna si Yusup.",
        36: "Pasalta', si Yusup bay binowa ni lahat Misil e' saga magdaragang. Ma Misil pa'in, pinab'llihan iya ni dakayu' kapitan pangandolan Pira'un, ōnna si Putipar. Pagnakura'an iya ma saga jaga ma deyom astana' Pira'un.",
    },
    38: {
        1: "Na, ma waktu ina'an pabutas na si Yahud min saga danakanna bo' pehē' ni da'ira Adullam pat'nna' ma luma' si Hira.",
        2: "Mahē' pa'in si Yahud, makapagkilā iya maka budjang, anak si Suwa bangsa Kana'an. Jari tahinangna h'nda.",
        3: "Anganak iya l'lla ati si Ēr ya pangōn si Yahud ma iya.",
        4: "Angiram h'ndana pabīng bo' anganak isab l'lla. Onan ya pangōnna ma iya.",
        5: "Ma lahat Keseb pa'in, anganak gi' iya pabīng, l'lla isab. Sela ya pangōnna ma iya.",
        6: "Na palabay pa'in daka pilantahun, si Yahud bay amah'nda'an anakna siyaka, ya si Ēr, ma si Tamar.",
        7: "Sagō' lumandu'an ala'at kajarihan si Ēr ma pang'nda' PANGHŪ' -Yawe, angkan iya magtūy minomos.",
        8: "Manjari ah'lling si Yahud ma si Onan ya anakna pasunu'. “Otō',” yukna, “ipalnu si Tamar abalu na. Subay ka magpūn maka iya supaya aniya' tubu' siyakanu. Ya na addat bang aniya' amatay ma halam aniya' anakna.”",
        9: "Sagō' kinata'uwan asal e' si Onan bang si Tamar ganta' ab'ttong e'na bo' anganak, in anak inān mbal taitung anakna. Taitung anak siyakana. Angkanna si Onan itu, sakahaba' iya magbihing maka si Tamar, mbal tino'ongan e'na supaya halam aniya' tubu' ma siyakana ya bay amatay he'.",
        10: "Ala'at isab hinang si Onan inān ma pang'nda' PANGHŪ' angkan amatay isab iya.",
        11: "Na, aniya' lling si Yahud ma ayuwanna si Tamar, yukna, “Amole' na ka ni okoman mma'nu. Da'a ka magh'lla saddī, lagarin gi' anakku si Sela. Subay na iya asangpot bo' kam magpūn.” Angkan buwattē' lling si Yahud sabab ahalli' iya ma si Sela. Kalu iya amatay buwat duwangan siyakana he'. Jari amole' na si Tamar ni matto'ana.",
        12: "At'ggol-t'ggol pa'in, amatay isab anak si Suwa ya h'nda si Yahud. Ataptap pa'in pangatayan si Yahud itu min bay kamatay h'ndana, magbeya' iya maka bagayna si Hira a'a Adullam. Amaklay sigām karuwangan pehē' ni lahat Timna, ni lugal pagguntingan bulbul saga bili-bili si Yahud.",
        13: "Manjari aniya' makahaka ma si Tamar in mato'ana song at'kka ni Timna angangguntingan saga bili-bilina.",
        14: "Na pagta'u si Tamar, magtūy iya analinan s'mmekna balu. Tinambunan isab baihu'na maka sulban bo' mbal takilā, ati aningkō' iya ma tongod pagsosōran ni deyom kauman Inaim, ya ma bihing kalsara tudju ni Timna. Kinata'uwan asal e' si Tamar in si Sela asangpot na, sagō' halam gi' tapamah'lla ma iya.",
        15: "Na, ta'nda' e' si Yahud si Tamar e' sagō' halam takilāna. Pangannalna d'nda pinagtatambahan sabab magtambun baihu'na.",
        16: "Manjari itu, pagka halam kinata'uwan e' si Yahud in d'nda inān ayuwanna, pina'an si Yahud ni tongodna ma bihing lān. Yukna ma iya, “Bilahi ka ameya' ma aku?” Yuk si Tamar, “Ai panambanu aku?”",
        17: "Ya sambung si Yahud, “Pabeya'anta ka dakayu' anak kambing min ba'anan kambingku.” “Na,” yuk si Tamar, “makajari. Sagō' subay aniya' sanda' pang'bbanu ma aku.”",
        18: "Atilaw si Yahud, “Ai pang'bbaku?” Yuk d'nda, “Ā, engkot k'llongnu ilu maka tungkudnu.” Na sinōngan magtūy e' si Yahud ati magbihing na sigā maka angiram iya.",
        19: "Puwas e' amole' na si Tamar bo' yampa nila'anan sulban bay panambun baihu'na ati magsin'mmek iya balu pabīng.",
        20: "Na, si Yahud itu bay amabeya' kambing ma bagayna si Hira. Sinō' e'na angā' ai-ai bay pang'bbana ma d'nda he', sagō' halam tabāk e'na.",
        21: "Aniya' isab saga a'a Inaim bay tinilaw e' si Hira bang maingga d'nda pinagtatambahan ya bay ma bihing lān. Ya sambung saga l'lla he', “Tuwan, bay min katagna' lagi' halam aniya' d'nda pinagtambahan maitu.”",
        22: "Pabalik si Hira pehē' ni si Yahud angahaka'an iya. Yukna, “Tuwan, halam tabākku. Yuk isab saga l'lla maina'an halam kono' aniya' d'nda pinagtambahan maina'an min katagna'.”",
        23: "“Na,” yuk si Yahud, “ya niyatku subay anambahan iya dakayu' anak kambing, sagō' halam ya tabāknu. Ma iya na ai-ai bay pang'bbaku. Pasagarin na bo' kita mbal pagtunggīngan e' a'a.”",
        24: "Sakali itu, palabay pa'in saga t'llumbulan, aniya' a'a makahaka ma si Yahud, yukna, “Ayuwannu si Tamar ala'at kajarihanna magusaha'an baranna, maka ab'ttong na iya.” Magpanoho'an si Yahud, yukna, “Bowahunbi iya paluwas min kauman itu. Tunu'unbi bo' amatay.”",
        25: "Hinabu si Tamar binowa paluwas bahasa tinunu', bay iya amabeya' lapal ni mato'ana. Yuk lapalna, “Ab'ttong aku e' a'a ya tag-dapu engkot k'llong maka tungkud itu. Nda'un pahāp, kalu takilānu.”",
        26: "Takilā magtūy e' si Yahud. Yukna, “Abontol iya labi-labi min aku. Tinaikutan e'ku addattam pagka halam bay pamah'llaku ma iya anakku si Sela.” Jari puwas minnē' halam iya bay makasekot pabalik ni ayuwanna si Tamar e'.",
        27: "Na, ta'abut pa'in bulan panganak si Tamar, k'mbal l'lla ya nianakan e'na.",
        28: "Ang'ddon pa'in iya, amaluwas tanganna k'mbal dakayu'. Magtūy niengkotan e' panday maka salban keyat. “Ya itu,” yukna, “k'mbal siyaka.”",
        29: "Sagō' sinuhutan tanganna. Jari ya k'mbal pasunu' paluwas dahū. Yuk panday isab, “Mamarahi pahāp ka'a ilu pa'agaw paluwas dahū!” Jari si Peres ya pangōn onde'-onde' dahū paluwas e'.",
        30: "Puwas e', paluwas na k'mbal ya taga-salban keyat ma tanganna, l'lla du isab, ati niōnan iya si Sera.",
    },
    39: {
        1: "Na, in si Yusup bay na tabowa ni lahat Misil e' saga a'a bangsa Isma'il. Pinab'llihan iya e' sigām ni si Putipar, ya pagnakura'an saga jaga ma deyom astana' Pira'un.",
        2: "Manjari itu, ahāp sadja kat'kkahan ai-ai nihinang e' si Yusup hinabuna pat'nna' ma luma' nakura'na si Putipar a'a Misil. Tu'ud iya tinabang na pa'in e' si Yawe.",
        3: "Ta'nda' isab e' si Putipar in si Yusup tinabang asal e' si Yawe, maka ahāp kasōngan hinangna kamemon.",
        4: "Manjari kasulutan si Putipar ma si Yusup ati tahinang iya pangandolanna. Binuwanan iya kapatut magnakura' ma a'ana kamemon sampay ma pangalta'na kamemon.",
        5: "Na, tinagna'an min waktu ina'an-i, si Putipar a'a Misil bay nilidjiki'an e' PANGHŪ' ma sabab si Yusup. Paheka na pa'in palsuku'anna, ai na ka ma deyom luma', ai na ka ma humana maka ma kabbunna.",
        6: "Angandol to'ongan si Putipar ma si Yusup, angkan pangandolna ma iya pangalta'na kamemon. Halam aniya' pagsusahan si Putipar, luwal pagkakanna. Na, si Yusup itu dakayu' l'lla ahāp luwana maka pamarananna.",
        7: "Sakali itu, mbal isab at'ggol, kinabilahian iya e' h'nda si Putipar. Yukna ma si Yusup, “Pi'itu ka ni deyom bilik, maghulid kita.”",
        8: "Sagō' mbal si Yusup. Ya llingna ma d'nda he', “Oy, aku itu pangandolan e' nakura'ku, ya na h'llanu. Mbal pamagayna ai-ai pangalta'na ma deyom luma' itu pagka pangandolna ma aku.",
        9: "Bang binista, in kapatutku daheya du maka kapatutna ma deyom luma' itu. Pagdūl-baya'anku kamemon, luwal du ka'a sabab h'ndana ka. Angkan aku mbal makahinang la'at ya yuknu ilu, sabab dusa ko' ilu ni Tuhan!”",
        10: "Na minsan buwattē' lling si Yusup, masi-masi du iya nilogos e' h'nda si Putipar, saguwā' mbal to'ongan iya ameya' maghulid maka iya. Mbal minsan pasekot ni tongodna.",
        11: "Sakali aniya' dakayu' llaw, makasōd pa'in si Yusup ni deyom luma' maghinang ai-ai kabiyaksahanna, halam aniya' sosoho'an saddī ma deyom luma'.",
        12: "Pagsōdna, magtūy iya tahella' ma tōng badju'na e' h'nda si Putipar. Yukna ma iya, “Dai' na ka. Maghulid kita.” Daipara makakawas si Yusup min balutanna maka e'na alahi paluwas. Ka'bbahan badju'na ma tangan d'nda.",
        13: "Na, pag'nda' h'nda si Putipar ma si Yusup paragan paluwas, maka badju' bay ka'bbahan e'na,",
        14: "magtūy lingananna saga sosoho'anna. “Nda'unbi,” yukna, “a'a Hibrani bay pinapi'itu e' h'llaku angahina' kitam. Bay iya anōd bilikku, arak aku niusiba'an e'na, manda' aku angolang saru'un-du'un.",
        15: "Na, pagolangku itu,” yukna, “alahi iya paluwas magdai'-dai'. O'o, badju'na bay bbahanna ma bilikku.”",
        16: "Manjari d'nda inān bay ang'nna' badju' si Yusup ma bihingna sampay at'kka h'llana.",
        17: "Na, at'kka pa'in si Putipar magtūy iya sinuli-sulihan e' h'ndana. Yukna, “O, ya atanu Hibrani bay bowanu pi'itu, bay makasōd ni deyom bilikku insini' amuwanan aku kaiya'an.",
        18: "Daipara angolang aku saru'un-du'un. Pagolangku, magtūy iya alahi magdai'-dai' paluwas. Sagō' ta'bba badju'na ma bihingku.”",
        19: "Na, pagkale pa'in si Putipar ma sumbungan h'ndana pasal bay tahinang kono' e' atana he', magtūy akagit sidda atayna,",
        20: "ati soho'na si Yusup sinaggaw bo' pinakalabusu ma deyom luma' pagkumbisan saga pilisu bay makalanggal sara' Pira'un. Kasangdanan si Yusup ma deyom kalabusu,",
        21: "malaingkan halam bay pinasagaran e' PANGHŪ'. Taptap iya pinat'kkahan lasa maka ase', ya angkan iya makasulut atay nakura' kalabusu inān.",
        22: "Si Yusup kabuwanan e'na kapatut magbaya' ma saga pilisu kasehe'an, maka pangandolna isab ma iya kahinangan ai-ai maina'an ma kalabusu.",
        23: "Manjari itu, pagka si Yusup ya a'a pangandolan ma deyom kalabusu, halam aniya' pagsusahan nakura' inān sabab aheya tabang PANGHŪ' ma si Yusup. Ai-ai hinangna ahāp sadja kasōnganna.",
    },
    40: {
        1: "Na at'ggol-t'ggol pa'in, aniya' duwa sosoho'an Pira'un makarusa ma iya. Dakayu' itu bay pagnakura'an saga a'a magbubuhat inumanna, maka dakayu' ya pagnakura'an saga a'a maghinang tinapayna. Angastol Pira'un ma sigām karuwangan itu,",
        2: "Na at'ggol-t'ggol pa'in, aniya' duwa sosoho'an Pira'un makarusa ma iya. Dakayu' itu bay pagnakura'an saga a'a magbubuhat inumanna, maka dakayu' ya pagnakura'an saga a'a maghinang tinapayna. Angastol Pira'un ma sigām karuwangan itu,",
        3: "ati pinakalabusu sigām ma deyom luma' kapitan saga jaga, hatina luma' pangumbisan si Yusup.",
        4: "Maina'an pa'in sigām, aniya' hinang pamat'nna' kapitan jaga ma si Yusup. Sinō' iya anabangan a'a duwangan-i ma ai-ai kagunahan sigām. Na, at'ggol-t'ggol pa'in sigām ma deyom kalabusu, ma dasangom du,",
        5: "aniya' tauppi e' duwangan pilisu itu, ya bay pagnakura'an ma deyom astana' Pira'un. Magsaddī uppi sigām dangan maka dangan, maka saddī isab ma'anana.",
        6: "Pagsubu, pasekot si Yusup ni duwangan sosoho'an Pira'un ya sehe'na ma deyom kalabusu itu. Ta'nda'na magtūy aniya' pagsusahan sigām angkan tilawna. “Asusa pahāp pamaihu'anbi ilu. Angay bahā'?”",
        7: "Pagsubu, pasekot si Yusup ni duwangan sosoho'an Pira'un ya sehe'na ma deyom kalabusu itu. Ta'nda'na magtūy aniya' pagsusahan sigām angkan tilawna. “Asusa pahāp pamaihu'anbi ilu. Angay bahā'?”",
        8: "Ya sambung sigām karuwangan, “Aniya' uppi kami dibuhi', sagō' halam aniya' maitu ata'u angama'anahan iya.” “Ā,” yuk si Yusup, “dakayu'-kayu' du Tuhan makabuwan pangita'u magma'ana. Haka'in aku kono' ya bay tauppibi ilu.”",
        9: "Manjari ah'lling a'a dangan ya pagnakura'an saga a'a magbubuhat inuman Pira'un, yukna, “Ya ta'nda'ku ma deyom uppiku dampo'on bahan anggul",
        10: "t'llu sangana. Paguplutna, magtūy anumping. Pagsumping itu, magtūy patahak buwa'na.",
        11: "Na, ina'an asal sawan pagi'inuman Pira'un ma tanganku, jari k'ttu'ku buwa' anggul e' bo' yampa p'gga'ku ni deyom sawan. Puwas e', bay sōnganku bohe'na pehē' ni Pira'un. Na, halam na.”",
        12: "Yuk si Yusup, “Ya na itu ma'ana uppinu ilu. Ya t'llu sanga ilu, hatina t'llung'llaw.",
        13: "T'llung'llaw gi' minnitu in ka'a pinaluwas du e' Pira'un min deyom kalabusu. Pinabīng du ka ni bay hinangnu dahū magbubuhat inumanna.",
        14: "Sagō' aniya' pangamu'ku ma ka'a,” yuk si Yusup. “Bang ka ma deyom kasannangan na, ndū', entomun pa'in aku sangkahāpan. Sabbutun kahālanku ma munda'an Pira'un supaya aku makaluwas min deyom kalabusu itu.",
        15: "Sabab ya b'nnalna, in aku itu bay tasaggaw min lahatku porol, ya lahat bangsa kami Hibrani. Damikiyanna isab maitu ma lahat Misil, takalabusu aku ma halam aniya' sababna.”",
        16: "Na, takale pa'in kahāp ma'ana itu e' nakura' dakayu' ya maghihinang tinapay Pira'un, magtūy iya amaluwas uppina ma si Yusup. Yukna, “Ya du aku taga-uppi dibuhi'. Ma deyom uppiku in aku baranku bay angandurung t'llu ligu magbangkat-bangkat.",
        17: "Aniya' ginisan tinapay maka bāng-bāng ma ligu diyata', arak pangalabot Pira'un, sagō' pinagtittuk e' saga manuk-manuk. Na, ya du ilu uppiku.”",
        18: "Manjari ah'lling si Yusup ma nakura' maghihinang tinapay, “Ya ma'ana uppinu ilu,” yukna “buwattitu. Ya t'llu ligu sapantun t'llung'llaw.",
        19: "Jari t'llung'llaw minnitu in ka'a-i pinaluwas du e' Pira'un min deyom kalabusu bo' yampa paponggolanna kōknu. Pagpuwas, pinasagnat bangkaynu ma diyata' hāg bo' pinagtittuk isina e' saga manuk-manuk.”",
        20: "Na, t'llung'llaw pa'in damuli minnē', ta'abut na llaw pagmahaltabat kapaganak ma Pira'un. Pinagjamuhan e'na kamemon saga tendogna ya pagnakura'an, maka soho'na pinaluwas min kalabusu ya nakura' magbubuhat inumanna inān sampay nakura' maghihinang tinapayna. Pinatampal sigā ni matahan ba'anan nakura' inān.",
        21: "Ya nakura' magbubuhat inuman pinabalik e' Pira'un ni bay hinangna.",
        22: "Saguwā' in nakura' maghihinang tinapay inān sinō' pinasagnat bangkayna ni hāg. Jari taluwa' bay pagma'ana si Yusup ma pasal panguppi duwangan itu.",
        23: "Malaingkan halam taentom e' nakura' magbubuhat inuman ya bay tambuku si Yusup ma iya. Takalipatna na.",
    },
    41: {
        1: "Na, aniya' saga duwantahun palabay, anguppi isab Pira'un. Ma deyom uppina, ina'an iya an'ngge-n'ngge ma bihing sapa' Nīl.",
        2: "Jari aniya' pitu' sapi' al'mmok maka alanu' patukad min deyom sapa' e' bo' amangan ma kaparangan.",
        3: "Pagpuwas, aniya' pitu' sapi' saddī patukad min sapa', angagkag lullun maka ahigtal. Jari pasekot saga sapi' damuli itu ni sapi' al'mmok ya ma bihing sapa' e'.",
        4: "Ahā, saga sapi' al'mmok kinakan magtūy e' saga sapi' angagkag. Na, makabati' na Pira'un min uppina.",
        5: "Pagtulina pabīng, anguppi na isab iya. Ya tauppina pitumbatang pai ahāp isina maka asambu, patomo' asal min dampo'on.",
        6: "Mbal at'ggol, aniya' isab pitumbatang pai saddī patomo' min po'onna. Ak'ppes isi paina maka alūs e' baliyu apasu'.",
        7: "Manjari tin'llon magtūy e' pai ak'ppes in pai asambu inān. Na, pagbati' pa'in Pira'un e', tasayuna in iya bay anguppi.",
        8: "Pagsubu, aheya kasusahanna angkan palingananna saga a'a ilmu'an maka kamemon a'a bal-akkal ma kaluha'an lahat Misil. Maina'an pa'in sigām ma Pira'un, nihaka'an sigām e'na pasal uppina, malaingkan halam aniya' min sigām makapahati iya bang ai ma'anana.",
        9: "Manjari aniya' lling nakura' magbubuhat inuman ma Pira'un. Yukna, “Tuwan Pira'un, yamboho' taentomku ma llaw itu, aniya' kasā'an bay tahinangku.",
        10: "Ma waktu kakagit ataynu ma aku maka ma nakura' maghihinang tinapay, bay kami pakalabusunu ma luma' kapitan saga jaga.",
        11: "Manjari dakayu' sangom makauppi kami karuwangan, bo' saddī ma'anana.",
        12: "Na, aniya' a'a Hibrani bay sehe' kami ma deyom kalabusu, subul lagi', sosoho'an kapitan jaga. Bay iya haka'an kami pasal bay tauppi kami. Pagkalena, magtūy mina'anahan e'na pakaniya-pakaniya.",
        13: "Ya kaluwasanna, tatuman ai-ai kamemon bay pagma'anana ma kami. Aku itu bay pinabīng ni bay hinangku. Ya a'a maghihinang tinapaynu bay soho'nu pinapatay.”",
        14: "Angkan na pinalinganan magtūy si Yusup e' Pira'un ati pinaluwas iya magdai'-dai' min deyom kalabusu. Aubus pa'in e'na amagongan p'ngngotna sampay analinan badju'na, paharap iya pehē' ni Pira'un.",
        15: "Yuk Pira'un ma si Yusup, “Makauppi aku sagō' halam aniya' minsan dakayu' makapahati aku ma pasalna. Na kahaka'an aku pasal ka'a. Bang aniya' uppi a'a takalenu, ata'u ka kono' angama'anahan iya.”",
        16: "Ya sambung si Yusup ma Pira'un, “Tuwan sultan, ngga'i ka min pangita'uku. Tuhan dakayu'-kayu' ya makabuwanan ka'a ma'ana ahāp.”",
        17: "Ya lling Pira'un ma si Yusup, “Ma deyom uppiku, ina'an aku an'ngge-n'ngge ma bihing sapa' Nīl.",
        18: "Manjari aniya' ta'nda'ku pitu' sapi' al'mmok maka alanu' patukad min deyom sapa' amangan ma kaparangan.",
        19: "Puwas e', aniya' patukad pitu' sapi' saddī, angagkag maka ahigtal. Yamboho' aku maka'nda' sapi' buwattē' la'atna minsan ma'ingga-ma'ingga ma lahat Misil.",
        20: "Sakali itu, in sapi' al'mmok inān kinakan magtūy e' saga sapi' angagkag.",
        21: "Malaingkan halam apinda baran saga sapi' bay amangan. Bā'nu halam bay makakakan ai-ai sabab masi angagkag. Na halam na, makabati' magtūy aku.",
        22: "“Pagtuliku pabīng, anguppi na isab aku. Ya ta'nda'ku ma deyom uppiku damuli itu, pitumbatang pai patomo' min dampo'on. Ahāp isi paina, asambu lullun.",
        23: "Puwas e', aniya' patomo' pitumbatang pai saddī, min dampo'on du isab. Ak'ppes isi paina maka alūs e' baliyu apasu'.",
        24: "Oy na, ya pai asambu inān tat'llon magtūy e' pai ak'ppes. Na, iya na he' tauppiku. Manjari haka'anku saga a'a ilmu'an pasal bay tauppiku he', sagō' halam aniya' minsan dakayu' min sigām makapahatian aku bang ai ma'anana.”",
        25: "Yuk si Yusup ma Pira'un, “Tuwan Pira'un, ya duwa uppinu ilu dama'ana du. Tu'ud ka pinata'u e' Tuhan bang ai hinangna ma sinosōng.",
        26: "Ya pitu' sapi' al'mmok ilu, maka pitumbatang pai asambu, sapantun pituntahun ahāp to'ongan anihanna.",
        27: "Buwattē' isab pitu' sapi' angagkag ya patukad ma karamulihan, maka pitumbatang pai ya alūs e' baliyu, sapantun pituntahun gotom.",
        28: "“Buwat bay pangahakaku ma ka'a, Tuwan Pira'un, in ka'a pinata'u na e' Tuhan bang ai nihinang e'na ma sinosōng.",
        29: "Hatina, ma deyom pituntahun ya song pat'kka itu, ajatu to'ongan saga tinanom ma katilibut lahat Misil, magdayas-dayas ma kinakan.",
        30: "Pasunu' isab pina'an pituntahun gotom, jari in lahat Misil itu magkasigpitan, ati takalipat e' saga a'a kamemon bay timpu pagdayas-dayas e'.",
        31: "Alungay timpu kahāpan min pangentom manusiya' ma sabab kabisa paggotom ya makasunu'.",
        32: "Tuwan, ya angkan ka pinauppihan min duwa e' Tuhan, sabab ahogot niyatna. In pakaradja'an bay tauppinu ilu marai' na pinat'kka e'na.",
        33: "“Da'a busung, Tuwan Pira'un, bang bahā' aku angahūgan ka'a gara'? Subay ka amiha dakayu' a'a bal-akkal, a'a alalom pangita'una, pinapagnakura' e'nu ma katilingkal lahat Misil.",
        34: "Subay ka amat'nna' saga mandul isab maka subay aniya' kapatut sigām angā' bahagi' lima min ai-ai pinagani ma deyom pituntahun ya aheka anihanna.",
        35: "Subay aniya' isab kapatut sigām deyo' min Pira'un amatipun kamemon anihan inān sat'ggol ahāp tahunanna, maka subay tinau' pahogot ma deyom saga da'ira.",
        36: "Ya kinakan tatipun itu subay tinagama pagbalanja' manusiya' ma timpu gotom ya song pat'kka ni lahat Misil. Manjari mbal sigām patay otas.”",
        37: "Na, kasulutan Pira'un maka kamemon saga tendogna ma bay panganggara' si Yusup e'.",
        38: "Angkan yuk Pira'un ma sigām, “Mbal na kitam makapiha a'a saddī makasali' ni si Yusup itu. In iya dakayu' a'a katulunan pikilan alalom e' Tuhan.”",
        39: "Angabtang Pira'un ma si Yusup, yukna, “Pagka ka'a ya bay kabuwanan pangita'u maka pikilan alalom e' Tuhan, mattan halam aniya' angatu ma ka'a ma akkal maka pamikil.”",
        40: "Ah'lling gi' Pira'un ma si Yusup, yukna, “Itiya' aku angangg'llal ka'a pagmakōkan ma pagsultananku itu. Ai-ai panoho'annu subay bineya' sadja e' saga a'aku kamemon. Luwal kawasaku ya aheya min kawasanu, sabab Pira'un aku.",
        41: "Buwattina'an g'llalta na ka gubnul ma sakalingkal lahat Misil.”",
        42: "Manjari niurusan e' Pira'un singsingna taga-gindan pagsultanna, ati pasulugna ma tangan si Yusup. Pinasulugan iya juba ahalga' kakana'na isab, maka engkot k'llong bulawan.",
        43: "Puwas e' binuwanan iya dakayu' kalesa, ya pamasuku' a'a bangsahan ya pasunu' ma Pira'un. Aniya' isab jaga sinō' parahū min kalesana amasimay saga a'a bo' aluhaya palabayanna. Manjari si Yusup ya pinapaggubnul ma kaluha'an lahat Misil.",
        44: "Ah'lling Pira'un ma si Yusup, yukna, “B'nnal, aku ya sultan maitu ma Misil, sagō' halam aniya' a'a ma katilibut lahat Misil itu makatawakkal maghinang ai-ai bang ngga'i ka min panoho'annu.”",
        45: "Jari aniya' ōn saddī pamuwan Pira'un ma si Yusup ma bahasa Misil. Niōnan iya Sapenat-Paneya. Pinah'nda'an isab iya e' Pira'un ma si Asenat anak si Potepera, dakayu' imam ma da'ira Ūn. T'llumpū' tahun ya umul si Yusup ma waktu katagna'na maghinang ma deyoman Pira'un ya magsultan ma lahat Misil. Makaluwas pa'in iya min deyom astana', nilibut e'na kaluha'an lahat.",
        46: "Jari aniya' ōn saddī pamuwan Pira'un ma si Yusup ma bahasa Misil. Niōnan iya Sapenat-Paneya. Pinah'nda'an isab iya e' Pira'un ma si Asenat anak si Potepera, dakayu' imam ma da'ira Ūn. T'llumpū' tahun ya umul si Yusup ma waktu katagna'na maghinang ma deyoman Pira'un ya magsultan ma lahat Misil. Makaluwas pa'in iya min deyom astana', nilibut e'na kaluha'an lahat.",
        47: "Manjari itu ma deyom pituntahun ahāp, aheka to'ongan buwa' tinanom ya niani ma lahat e'.",
        48: "Pinatau' e' si Yusup ma saga da'ira pakaniya-pakaniya ya ingga-ingga bay ta'ani min kahuma'an ya ma katilibut saga da'ira inān. Buwattē' na pa'in hinang si Yusup ma deyom pituntahun ya ahāp pagani.",
        49: "Tinipun bo' tinipun sampay palasay min pagtau'an. Angkan pinahondong e' si Yusup saga sosoho'anna inān angitung t'pponganna. Tu'ud aheka makalandu', buwat ibarat gusung ma bihing tahik mbal taitung.",
        50: "Na, ma halam lagi' ta'abut waktu gotom, aniya' duwa anak si Yusup l'lla min h'ndana si Asenat ya anak si Potepera imam ma da'ira Ūn.",
        51: 'Si Manasse ya pangōn si Yusup ma anakna siyaka inān. Ya pangabtang si Yusup, “Min Tuhan ya angkan aku kalungayan pangentom ma kakampunganku kamemon, sampay kabinasahan kamemon bay kalabayanku.”',
        52: "Manjari si Epra'im ya pangōnna ma anakna pasunu'. Angabtang isab si Yusup, yukna, “Kabuwanan aku tubu' ma lahat ya bay makabuwanan aku kabinsana'an.”",
        53: "Na, ta'abut na tobtoban pituntahun ya aheka anihanna ma lahat Misil,",
        54: "ati anagna' pituntahun gotom buwat bay pangahaka si Yusup. Taluwa' gotom kalahat-lahatan inān kamemon, malaingkan aniya' kinakan ma sakalingkal lahat Misil.",
        55: "Kakulangan pa'in balanja' saga a'a Misil e', angamu' sigām ni Pira'un. Angkan na aniya' panoho'anna ma saga a'a inān kamemon, sinō' sigām pehē' ni si Yusup bo' ameya' ma ai-ai pamat'nna'na ma sigām.",
        56: "Pasōng na pa'in gotom sampay pa'abut ni kaluha'an lahat Misil. Jari magpanoho'an si Yusup, sinō' niukab saga bodega panau'an kinakan bo' yampa pinab'llihan ma saga a'a Misil.",
        57: "Damikiyanna saga a'a ma kamemon kalahat-lahatan, kasigpitan sidda ma sabab gotom. Angkan na sigām pehē' ni lahat Misil am'lli balanja' min si Yusup.",
    },
    42: {
        1: "Na, makata'u pa'in si Yakub mma' si Yusup aniya' balanja' tab'lli ma lahat Misil, ah'lling iya ma saga anakna l'lla. Yukna, “Angay kam hal aningkō'?",
        2: "Takaleku aniya' balanja' tab'lli mahē' ma Misil. Pehē' kam, b'llihinbi bo' kitam mbal patay otas.”",
        3: "Manjari pehē' na saga siyaka si Yusup sangpū' puhu' am'lli balanja' ni Misil.",
        4: "Ya halam pinabeya' e' si Yakub anakna kasiyalihan si Benjamin, ya langgung si Yusup. Nihalli'an iya e' mma'na bo' mbal t'kkahan la'at ma l'ngnganan.",
        5: "Manjari pa'abay na saga anak si Yakub ma a'a kasehe'an pehē' ni lahat Misil am'lli balanja', sabab kaluha'an lahat Kana'an inān talapay gotom isab.",
        6: "Na, pagka si Yusup ya gubnul ma lahat Misil, taga-kapatut iya magpab'lli balanja' ma sai na. Sakali itu, at'kka pa'in saga danakan si Yusup pina'an, magtūy sigām pasujud ma dahuanna.",
        7: "Magtūy sigām takilā e' si Yusup, sagō' magbau'-bau' sadja iya in sigām mbal kata'uwanna. Akasla isab llingna ma sigām, yukna, “Oy, minningga kam?” Ya sambung sigām, “Min lahat Kana'an, tuwan. Bay kami pi'itu am'lli balanja'.”",
        8: "Minsan takilā e' si Yusup saga danakanna, in iya halam takilā e' sigām.",
        9: "Jari taentom e' si Yusup bay tauppina ma masa palabay pasal saga danakanna inān, angkan yukna, “Ā, mata-mata ko' ka'am ilu bay pi'itu ang'nda'-ng'nda' lahat kami bang tongod ai ya aluhay sinōd.”",
        10: "Ya sambung saga danakanna, “Arōy tuwan, kami itu ngga'i ka mata-mata. Halam aniya' maksud kami ala'at. Sosoho'annu du isab kami bay pi'itu am'lli balanja'. Magdanakan kami, a'a asaltun lullun.”",
        11: "Ya sambung saga danakanna, “Arōy tuwan, kami itu ngga'i ka mata-mata. Halam aniya' maksud kami ala'at. Sosoho'annu du isab kami bay pi'itu am'lli balanja'. Magdanakan kami, a'a asaltun lullun.”",
        12: "“Ē!” yuk si Yusup. “Mbal aku am'nnal. Ya gawibi pi'itu ang'nda'-ng'nda' bang tongod ai ya aluhay sinōd ma lahat kami.”",
        13: "Ya sambung sigām ma si Yusup, “Tuwan Gubnul, in kami sosoho'annu itu bay sangpū' maka duwa magdanakan. Mma' kami ina'an ma lahat Kana'an, maka ina'an ma iya danakan kami kasiyalihan. Aniya' isab danakan kami amatay na.”",
        14: "“Ā,” yuk si Yusup, “B'nnal ya yukku insini', in ka'am ilu mata-mata. Ala'at maksudbi.",
        15: "Sulayanta kam bang b'nnal llingbi. Ya danakanbi kasiyalihan e' subay pinapi'itu. Bang hati' mbal, na sapahanta kam min ōn Pira'un, in ka'am mbal to'ongan makala'an minnitu.",
        16: "Dangan min ka'am subay pehē' angā' siyalibi he'. Kasehe'anbi subay tinahan maitu ma deyom kalabusu sampay tata'u bang b'nnal llingbi atawa mbal. Bang mbal, mattan du in ka'am mata-mata. Ōn Pira'un ya pagsapahanku.”",
        17: "Manjari pinakalabusu na sigām e' si Yusup t'llung'llaw t'ggolna.",
        18: "Na, ta'abut pa'in llaw kat'lluna, ah'lling na si Yusup ni saga danakanna, yukna, “Aku itu magmatāw ma Tuhan. Mbal kam papatayku bang pa'in kam ameya' ma pamat'nna'ku itu.",
        19: "Bang kam b'nnal asaltun, ahāp maksudbi, subay aniya' mattanna. Dakayu' a'a min ka'am ta'bba maitu ma deyom kalabusu, bo' kasehe'anbi ilu tinugutan amole' amowa balanja' ma saga anak-h'ndabi ya agon-agon patay otas.",
        20: "Pagubus, bowahunbi siyalibi pi'itu ni aku. Bang buwattē' hinangbi kamattanan aku in llingbi ma aku b'nnal to'ongan. Jari mbal na kam papatayku.” Na, kasulutan sigām magdanakan ma lling si Yusup.",
        21: "Magsuli-suli sigām pakaniya-pakaniya, yuk-i, “Na, tantu kitam katongoran ma bay tahinangtam ma siyalitam e'. Bay ta'nda'tam kasigpitanna waktu kapangamu'na ase' ma kitam. Sagō' halam asiptam. Ya he' sababanna angkan kitam t'kkahan sigpit buwattina'an.”",
        22: "Ah'lling isab si Rubin, yukna, “Bay na sa yukku ma ka'am da'a binasahunbi onde' e', sagō' halam aku bay beya'bi. Na, itiya' kitam binalosan pasal kamatayna.”",
        23: "Tahati asal e' si Yusup ai-ai pamissala sigām, saguwā' halam kinata'uwan e' sigām sabab kahaba' sigām anuli-nuli ma si Yusup aniya' magsasalin bahasa sigām ni bahasa Misil.",
        24: "Pagkale si Yusup ma pamissala sigām, tatangis iya ati pataikut min sigām. Pahondong pa'in tangisna bo' makasuwala pabīng, pabaihu' iya ni dauranakanna. Pinene' e'na si Simiyun, bo' soho'na niengkotan ma matahan sigām.",
        25: "Na, arai' pa'in amole' saga danakan si Yusup kasehe'an, magpanoho'an si Yusup ma saga tendogna, sinō' pin'nno'an balanja' saga karut sigām pakaniya-pakaniya. Sinō' isab ni'isi ni karut sigām sīn bay pamayad sigām dangan maka dangan. Pinalutu'an lagi' sigām bo' aniya' takakan-kakan sigām ma labayan.",
        26: "Kaniya-kaniya sigām anganduwa' ni kura' sigām saga balanja' bay tab'lli sigām. Pagduwa' itu, palanjal na sigām amole'.",
        27: "Sangom pa'in, pahondong sigām ma pahanti'an. Sakali itu, aniya' dangan min sigām angukab karutna bahasa angā' gandum pamakan kura'na. Pagukabna, na, aniya' sīn ma bowa' karut e'.",
        28: "Agsai lingananna saga danakanna, yukna, “Oy, itiya' sīnku bay pinabīng ni karutku.” Na taluwa' sigām sukkal aheya, jari magpamidpid sigām ati magtilaw-tilawan dansehe'an, yuk-i, “Ai sa ya pamat'kka kitam itu e' Tuhan?”",
        29: "Manjari itu, at'kka pa'in sigām ni lahat Kana'an maka ni si Yakub ya mma' sigām, sinuli-sulihan iya pasal kamemon bay kalabayan sigām.",
        30: "Yuk sigām, “Mma', binissalahan kami e' Gubnul ya pagnakura'an lahat Misil, akasla sidda. Tinuna'an kami e'na angamata-mata kono' ma lahatna.",
        31: "Ya sambung kami, ‘Tuwan, ngga'i ka kami saga mata-mata. A'a abontol kami, ahāp sadja maksud kami.",
        32: "Sangpū' maka duwa kami magdanakan, da'mma' kamemon. Dakayu' danakan kami wa'i na amatay. Maka danakan kami kasiyalihan ina'an tabba ma mma' kami ma lahat Kana'an.’ Ya he' bay pah'lling kami ma Gubnul e'.",
        33: "“Ya sambungna ma kami, ‘Nda'ku na bang kam b'nnal a'a abontol. Tahanku maitu a'a dangan min deyomanbi. Jari in ka'am kasehe'an makajari amole' bo' amowa balanja' ma anak-h'ndabi ya mbal makasandal otas.",
        34: "Malaingkan,’ yuk gubnul-i, ‘ya siyalibi subay bowabi pi'itu ni aku. Minnē' kamattanan aku in ka'am ngga'i ka mata-mata bay pi'itu amiha lugal aluhay sinōd. Jari nde'anku ni ka'am danakanbi bay tahanku ati aluhaya na kam magusaha ma lahat itu.’ Na, buwattē' lling gubnul inān ma kami.”",
        35: "Sakali itu, hinabu sigām angukab karut sigām pakaniya-pakaniya bo' anumpahan isina, allā! Ya putusan sīn bay pamayad sigām balanja', ina'an ma deyom karut. Pag'nda' sigām magtūy sigām sinōd tāw. Ya du si Yakub ya mma' sigām, sinōd tāw isab.",
        36: "Yukna ma sigām, “Arōy, kalungayan aku anak ma sababanbi. Halam na si Yusup, halam na si Simiyun, ati kabaya'anbi subay amowa si Benjamin? Aku ya marasahi magkarukka'an.”",
        37: "Manjari yuk si Rubin ma mma'na, “Mma', pangandolun si Benjamin ma aku. Bang saupama mbal tabowaku pabalik ni ka'a, makajari papataynu anakku l'lla karuwangan ilu.”",
        38: "Saguwā' mbal tapogos si Yakub. Yukna, “Mbal makabeya' ma ka'am anakku kabungsuhan itu. Wa'i na amatay langgungna, hal iya takapin allum. Bang aniya' makamula ma iya ma l'ngnganan, paheya gom pa'in karukka'anku ati tabowa aku amole' ni ahirat, sabab ato'a na aku.”",
    },
    43: {
        1: "Na, karuhunan gotom ma lahat Kana'an.",
        2: "Ya balanja' bay tab'lli e' saga anak si Yakub ma lahat Misil aubus na kamemon. Manjari ah'lling si Yakub ma saga anakna, yukna, “Pabalik kam pehē' ni Misil am'lli balanja' minsan mbal aheka.”",
        3: "Sagō' yuk si Yahud ma iya, “Mma', bay kami sinanggupan e' gubnul ma lahat-i, yukna bang kami mbal amowa siyali kami pehē', mbal kami makajari paharap ni iya.",
        4: "Bang hati pabeya'nu siyali kami itu, na, pehē' du kami am'lli balanja'.",
        5: "Sagō' bang iya mbal pabeya'nu, in kami itu mbal pehē' pagka mbal tinugutan paharap ni gubnul.”",
        6: "Ya sambung si Isra'il (hatina si Yakub), “Angay kam bay makahaka'an a'a inān aniya' gi' danakanbi saddī? Kasusahan sadja ya pamat'kkabi ma aku.”",
        7: "Ya sambung sigām, “Tu'ud mbal pahali a'a inān anilosa kami ma pasal kaukampungan kami. Tinilaw kami e'na pasal mma' kami bang masi allum, maka bang aniya' danakan kami saddī? Manjari, Mma', mbal kami makapagin'mbal ma panilawna. Maka halam isab bay makani-pikilan kami in siyali kami sinō' binowa pina'an ni iya.”",
        8: "Manjari si Yahud ya ah'lling, yukna, “Mma', pangandolun onde' ilu ma aku bo' kami pehē' magtūy am'lli balanja' supaya halam aniya' min kitam patay otas.",
        9: "Paglilla'ku baranku angakuhan iya min ai-ai makamula. Bang aniya' tum'kka ni iya, aku ya binīngan. Bang iya s'lle'-bale puhu' mbal tabowaku amole' pi'itu ni ka'a ma halam baya-baya, aku ya kasusunan sat'ggolku allum.",
        10: "Mma', bang kami halam bay taggahannu, bay du kami magpehē'-pi'itu min duwa na.”",
        11: "Yuk si Isra'il ya mma' sigām, “Na, bang buwattē', subay kam amowa kasampangan pangahulmatbi ma gubnul e'. Isihunbi ni karutbi ai-ai ya katapusan ahāp min lahatta itu, saga bulitik ahamut maka gula' buwani minsan sadja dangkuri', maka ginisan pamapā isab, maka saga kinakan ahāp nanamna buwat bigi-pistasyo maka bigi-almon.",
        12: "Bowahunbi isab sīn nilipat duwa min bay pam'llibi tagna' he', kalna' in sīn bay tabākbi ma bowa' karut subay pinabalik ni sigām. Arai' aniya' bay makasā'.",
        13: "Na, bowahunbi na siyalibi bo' kam magdai'-dai' pehē' ni gubnul.",
        14: "Bang pa'in iya pinat'kkahan atay ahāp e' Tuhan Sangat Kawasa supaya aniya' ase'na amabīng ni ka'am si Benjamin maka danakanbi dakayu'. Malaingkan bang aku saupama kalungayan anak, na, magsabal aku.”",
        15: "Sakali itu, palanjal na saga ka'anakan si Yakub maka e' sigām amowa kasampangan maka sīn nilipat duwa min bay dahū e'. Tabowa isab si Benjamin. Pagt'kka sigām ni Misil, pehē' sigām paharap ni si Yusup.",
        16: "Manjari, pag'nda' si Yusup ma si Benjamin, magtūy soho'na sosoho'an ya ang'ntan kapatut ma luma'na. Yukna, “Bowahun saga a'a itu pehē' ni luma'ku. Pasumbali'un hayop maka pa'adjalin pagkakan. Magsalu kami amangan ugtu llaw ilu.”",
        17: "Bineya' e' sosoho'an inān bay panoho'an si Yusup ma iya, ati binowa saga dauranakanna pehē' ni luma'.",
        18: "Sakali itu, sabu pa'in sigām binowa ni luma', t'kkahan sigām tāw. Ma hona'-hona' sigām, “Ya angkan kitam binowa pi'itu ma sabab sīn ya bay pinabīng ni deyom karuttam tagna' kitam bay am'lli balanja'. Marai' bahā' pataggaha' kitam nirugpak, ati sinaggaw kitam nihinang ata. Niagaw isab saga kura'tam.”",
        19: "Angkan na, pagabut sigām ni bowa' lawang, pasekot sigām ni a'a ang'ntan kapatut ma luma' si Yusup amowa iya magbissala. Yuk sigām,",
        20: "“Tuwan, da'a busung, aniya' pah'lling kami ma ka'a. Bay kami makapi'itu mint'dda am'lli balanja'.",
        21: "Sagō' makahanti' pa'in kami ma l'ngnganan tudju amole', taukab kami saga karut pakaniya-pakaniya. Pagukab itu, ta'nda' kami ma bowa' karut sīn bay pamayad kami balanja', jukup to'ongan. Daka sai bay amat'nna' sīn inān ni deyom karut kami. Angkan na itiya' kami amowa sīn e' pinapole' ni ka'am. Maka aniya' itu sīn saddī pam'lli kami balanja' ma l'ngngan itu.”",
        22: "Sagō' makahanti' pa'in kami ma l'ngnganan tudju amole', taukab kami saga karut pakaniya-pakaniya. Pagukab itu, ta'nda' kami ma bowa' karut sīn bay pamayad kami balanja', jukup to'ongan. Daka sai bay amat'nna' sīn inān ni deyom karut kami. Angkan na itiya' kami amowa sīn e' pinapole' ni ka'am. Maka aniya' itu sīn saddī pam'lli kami balanja' ma l'ngngan itu.”",
        23: "Ya sambung a'a ang'ntan kapatut e', “Da'a kam asusa. Da'a kam tināw. Tuhanbi, ya pagtuhanan mma'bi, bay makaisi sīn inān ni deyom karutbi. Bay du tasambutku bayadbi.” Puwas e' pinaluwas e'na si Simiyun ni'nde'an ni sigām.",
        24: "Na, binowa na saga danakan si Yusup ni deyom luma'na e' sosoho'anna he'. Binuwanan sigām bohe' pangose' tape' sigām maka binuwanan isab pagkakan saga kura' sigām.",
        25: "Makata'u pa'in sigām binowa sigām amangan ma luma' si Yusup, sinakap ba'anan kasampangan pangahulmat sigām ma iya pagt'kkana ni luma' ugtu llaw.",
        26: "Manjari pagt'kka si Yusup ni luma', pasujud sigām ma dahuanna maka e' sigām amuwanan iya saga kasampangan bay binowa e' sigām ni deyom luma'.",
        27: "Tinilaw sigām e' si Yusup pasal kahālan sigām. Yukna, “Painay na mma'bi ya bay pangahakabi ma aku ato'a na? Masi iya allum?”",
        28: "Ya sambung sigām, “Aho' tuwan, ahāp masi mma' kami maka alasig.” Pasujud na isab sigām ni si Yusup pagaddat sigām ma iya.",
        29: "Na, pag'nda' si Yusup ma langgungna si Benjamin, yukna, “Ā, ya na ka itu siyalibi, ya bay panuli-nulibi ma aku? Bang pa'in ka binuwanan kahāpan e' Tuhan, Otō'.”",
        30: "Agon-agon ahansul pangatayan si Yusup pag'nda'na ma langgungna. Angkan iya parai'-dai' paluwas sabab mbal tasandal bohe' matana am'ttak. Jari pasōd iya ni deyom bilikna anangis maina'an.",
        31: "Pagpuwas, akula'up iya bo' pabalik ni saga danakanna. Sinandalan e'na bohe' matana maka e'na anoho' saga a'ana amat'nna' kinakan sigām.",
        32: "Pinat'nna'an si Yusup dangan-danganna. Saga danakanna pinat'nna'an ma pamanganan saddī, sigām-sigām sadja. Saddī isab ma saga bangsa Misil ya magkakan maina'an. Mbal sigām makapagsalu maka bangsa Hibrani, sabab asammal bang ma sigām.",
        33: "Jari pinatingkō' saga danakan si Yusup ma anggopanna, maka pinagsunu'-sunu' isab tingkō'an sigām min siyaka ni siyali. Pag'nda' sigām ma pagpatingkō' ma sigām buwattē', magtūy sigām mag'nda' mata tabowa e' kainu-inuhan sigām.",
        34: "Manjari aniya' palauk pangalabot ma sigām bay min lamisahan si Yusup, sagō' ya pangalabot si Benjamin nilipat lima min bay pangalabot saga danakanna. Na magjamu sigām maka si Yusup, maginum sampay maglami-lami.",
    },
    44: {
        1: "Manjari aniya' panoho'an si Yusup ma a'a ang'ntan kapatut ma deyomanna, yukna, “P'nno'in balanja' karut sigām ilu kamemon, pila-pila ya takaya binowa e' sigām. Pole'in isab sīn bay pamayad sigām pakaniya-pakaniya, pat'nna'un ma diyata' balanja' ya ma deyom karut sigām.",
        2: "Ngā'un isab ya sawanku dī pilak bo' pat'nna'un pehē' ni deyom karut kasiyalihan e', pabeya'un ma sīn bay pamayadna.” Na bineya' e' a'a inān bay panoho'an si Yusup ma iya.",
        3: "Pagsubu-subu lagi', pinapole' na saga dauranakan e' maka saga kura' ya pagduruwa'an sigām.",
        4: "Sakali itu, ma halam lagi' sigām makalawak min da'ira bay kamahē'an sigām-i, ah'lling si Yusup ma a'a tag-kapatut ma deyomanna. “Pal'kkas ka,” yukna. “Turulun saga a'a inān. Pagabutnu, tilosahun sigām. Yuknu, ‘Ē, ka'am ilu! Kabuwanan kam kahāpan ati kala'atan ya panungbasbi!",
        5: "Angay tatangkawbi sawan pilak ya suku' nakura'ku? Sawan panginumanna ko' ilu, sawan isab pagputika'anna. Langgal sara' to'ongan ya tahinangbi ilu!’”",
        6: "Na, maka'abut pa'in sosoho'an si Yusup-i ni sigām magdanakan, magtūy isabanna kabtangan bay pah'lling si Yusup ma iya.",
        7: "Ya panambung saga magdanakan ma iya, “Tuwan, angay kami pah'llingannu buwattilu? Makabusung ko' ilu bang kami makahinang buwat yuknu ilu.",
        8: "Entomun sīn ya bay tabāk kami ma bowa' karut kami. Bay tabowa kami min lahat Kana'an bo' tinūran ni ka'a. Jari pangannalnu bahā' in kami makatangkaw pilak atawa bulawan min deyom luma' nakura'nu?",
        9: "Tuwan, bang sawan ilu ganta' tabāk ma sai-sai min kami, a'a inān subay papataynu, maka kami kasehe'an subay magpa'ata ma ka'a.”",
        10: "Ya sambung a'a si Yusup-i, “Sulut na,” yukna, “sagō' ya sadja hinangku ata, bang ma sai kabākan sawan ilu. Malaingkan ka'am kasehe'an puwas min palkala'.”",
        11: "Magtūy sigām magdai'-dai' amareyo' duwa'an sigām bo' yampa angukab karut pakaniya-pakaniya.",
        12: "Manjari pinaglungkad to'ongan saga karut sigām magdanakan e' sosoho'an si Yusup. Tinagna'an min siyaka tudju ni siyali. Allā, tabākna in sawan pilak ma deyom karut si Benjamin.",
        13: "Pagbāk itu, magtūy gineret e' saga dauranakan si Yusup saga badju' sigām ma sabab kaheya susa sigām. Taparuwa' pa'in ai-ai sigām ma saga kura', pehē' na sigām pabalik ni da'ira.",
        14: "Pagt'kka si Yahud maka saga danakanna ni luma' si Yusup, ina'an iya masi. Magtūy sigām pak'ppang ni tana' ma dahuanna.",
        15: "Yuk si Yusup ma sigām, “Angay kam makahinang buwattē'? A'awam kam bahā'? Bang a'a buwat aku ata'u ang'nda' putika'an, halam aniya' kalimbungan min aku.”",
        16: "Ya sambung si Yahud, “Daka ai pangabtang kami ma ka'a, tuwan. Halam aniya' panganda'awahan kami in kami itu asaltun. Tapabukis na dusa kami e' Tuhan. Atanu na kami itu kamemon, ngga'i ka sadja ya a'a dangan bay kabākan sawannu.”",
        17: "Ya sambung si Yusup, “Ā, mbal. Mbal aho'anku ya yuknu ilu. Ya sadja hinangku ata ya a'a bay kabākan sawanku. Ka'am kasehe'an ilu makajari na amole' pehē' ni mma'bi ma deyom kasalamatan.”",
        18: "Sakali si Yahud pasekot ni si Yusup maka e'na ah'lling, yukna, “Tuwan, da'a aku busung, aniya' pamowahanta ka magsuli-suli. Da'a isab ap'ddi' ataynu ma aku, sabab bang ma aku in ka'a sali' Pira'un.",
        19: "Tuwan,” yuk si Yahud, “bay kami tatilawnu bang aniya' lagi' mma' kami atawa danakan kami saddī.",
        20: "Ya sambung kami ma ka'a, aniya' mma' kami sagō' ato'a na. Maka aniya' gi' siyali kami l'lla bay nianakan ma kato'a si Mma'. Duwangan sigām maglanggung sagō' amatay na langgung siyaka. Manjari hal iya la'a takapin min sigām da-ina', angkan iya kinalasahan to'ongan e' si Mma'.”",
        21: "Ah'lling gi' si Yahud, yukna, “Manjari, tuwan, bay soho'nu kami amowa siyali kami pi'itu ni ka'a supaya iya ta'nda'nu.",
        22: "Ya sambung kami ma ka'a, ‘Onde' he' mbal makabutas min mma'na, sabab bang iya abutas, arakala' amatay si Mma'.’",
        23: "Sagō' ya llingnu in kami mbal makapagharap maka ka'a pabalik, luwal bang tabeya' pi'itu siyali kami.",
        24: "Na manjari tuwan, pagbīng kami pehē' ni si Mma', magtūy iya kahaka'an pasal bay pangabtangnu ma kami.",
        25: "“Na, mbal at'ggol, sinoho' na isab kami e' si Mma' pi'itu pabalik am'lli balanja' mbal aheka.",
        26: "Ya sambung kami ma iya, ‘Mma', bang mbal pabeya'nu si Benjamin mbal kami makapehē', sabab mbal tinugutan paharap ni gubnul e' bang halam tabeya' danakan kami kasiyalihan.’",
        27: "“Ya sambung si Mma' ma kami, ‘Kata'uwanbi asal, duwa du anakku l'lla min h'ndaku si Rakiya.",
        28: "Dakayu' e' halam na. Marai' iya bay tasagpe' e' sattuwa talun, sabab halam iya ta'nda'ku pabīng sangay min llaw bay kala'anna.’",
        29: "Yukna isab ma kami, ‘Bang pabutasbi si Benjamin min aku bo' aniya' kamulahan pataluwa' ma iya, na, pat'kkahanbi aku karukka'an mbal kasandalan e' a'a to'a. Ati tabowa aku amatay e' karukka'an.’”",
        30: "Ah'lling gi' si Yahud ma si Yusup. “Bang pinagbahasa, tuwan, onde' itu ya kapangā'an lasig si Mma'. Bang aku ganta' amole' bo' ta'nda' e' si Mma' in onde' halam tabeya' ma aku, piligdu, amatay du iya magkarukka'an.",
        31: "Ah'lling gi' si Yahud ma si Yusup. “Bang pinagbahasa, tuwan, onde' itu ya kapangā'an lasig si Mma'. Bang aku ganta' amole' bo' ta'nda' e' si Mma' in onde' halam tabeya' ma aku, piligdu, amatay du iya magkarukka'an.",
        32: "Paligay aku itu, tuwan,” yukna, “bay angakuhan kallum onde' itu. Yukku ma si Mma', ‘Bang iya mbal tabowaku pabīng pi'itu ni ka'a, aku iya kasusunan sat'ggolku allum.’",
        33: "“Ndū' tuwan,” yuk si Yahud, “bang pa'in tugutannu aku magpa'ata ma ka'a ganti' siyaliku. Paronganun iya ma saga danakanna kasehe'an amole' pehē' ni si Mma'.",
        34: "Daka painay e'ku amole' pehē' ni mma'ku bang halam ma aku onde' itu. Mbal aku makasandal ang'nda' ma pagkarukka'an si Mma'.”",
    },
    45: {
        1: "Manjari mbal na kasandalan e' si Yusup kahansul atayna angkan soho'na paluwas minna'an saga a'a Misil bay ma deyom luma'na. Na, halam pa'in aniya' a'a saddī maina'an, magpakilā na iya ma saga danakanna.",
        2: "Akosog pagtangis si Yusup, takale isab e' saga a'a Misil. Jari pinasampay habalna pehē' ni astana' Pira'un.",
        3: "Yuk si Yusup ma saga danakanna, “Aku na ko' itu si Yusup. Masi allum si Mma'?” Na, pagkale llingna itu e' saga danakanna, magtūy sigām sinōd tāw, kapam'ngngangan.",
        4: "Na amissala si Yusup ma sigām, yukna, “Pasekot kam pi'itu.” Jari pasekot na sigām. Yuk si Yusup isab, “Aku na ko' itu si Yusup, ya danakanbi bay pab'llihanbi bo' binowa ni Misil.",
        5: "Na, da'a kam asukkal. Da'a isab pagsusuninbi baranbi pasal pamab'llibi ma aku. Ya angkan aku makapi'itu, sabab Tuhan ya bay amapi'itu aku, ngga'i ka ka'am. Tu'ud aku pinarahū e'na min ka'am supaya kalappasan bangsa manusiya' min gotom.",
        6: "Ma buwattina'an yampa duwantahun paggotom ma lahat, jarina aniya' gi' limantahun halam aniya' tinanom, halam aniya' buwa' niani.",
        7: "Bay aku pinapi'itu e' Tuhan dahū min ka'am supaya kam kalappasan ma sabab kawasana makainu-inu, bo' aniya' du pa'in panubu'bi maitu ma dunya.",
        8: "“Hatina,” yuk si Yusup, “ngga'i ka ka'am ya bay amapi'itu aku, sagō' Tuhan. Min kahandakna ya angkan aku sali' sapantun pag'mma'an Pira'un angahūgan iya gara'. Tahinang aku pagmakōkan ma deyomanna, maka gin'llal aku nakura' ang'ntanan sakalingkal lahat Misil.",
        9: "Na, pal'kkas na kam amole' ni si Mma'. Pasampayunbi ni iya lapalku itu. ‘Min kahandak Tuhan ya angkan aku (yuk si Yusup) tahinang pagnakura'an ma sakalingkal lahat Misil. Palūd ka pi'itu saru'un-du'un, da'a ka ananggu.",
        10: "Maitu na ka pat'nna' ma lahat Gosen supaya asekot ni aku. Bowahun pi'itu saga anak-mpunu kamemon, sampay saga kahayopannu, bili-bili ka, kambing ka, sapi' ka. Bowahun isab pangalta'nu kamemon.",
        11: "Bang ka maina'an na ma Gosen aku ya angupiksa' ka'a. Aniya' gi' limantahun t'ggol gotom itu. Mbal aku bilahi bang ka'am magtai'anak atawa ba'anan hayopnu patay otas.’” Ya du ina'an lapal si Yusup ma mma'na si Yakub.",
        12: "Ah'lling gi' si Yusup ma saga danakanna, yukna, “Benjamin, ta'nda'nu na aku itu langgungnu. Maka ka'am ilu kamemon ta'nda'bi na, aku na ko' itu.",
        13: "Suli-sulihinbi si Mma' pasal kawasaku maitu ma lahat Misil. Suli-sulihinbi pasal kamemon ya ta'nda'bi maitu. Jari pasa'ut kam amowa iya pi'itu.”",
        14: "Magtūy ginapus e' si Yusup siyalina si Benjamin. Ginapus isab si Yusup e' si Benjamin, jari tatangis sigām karuwangan.",
        15: "Siniyum e'na danakanna kamemon dakayu' maka dakayu', maka e'na anangisan sigām. Pagubus, magsambung-siyambungi sigām magbissala.",
        16: "Na, makasampay pa'in ni astana' Pira'un habal pasal kat'kka saga danakan si Yusup, akōd to'ongan Pira'un maka saga tendogna pagnakura'an.",
        17: "Yuk Pira'un ma si Yusup, “Soho'un saga dauranakannu angamomos saga kura' sigām bo' pabalik ni lahat Kana'an.",
        18: "Sō'un sigām angā' mma'bi sampay anak-h'nda sigām kamemon bo' binowa e' sigām pi'itu waktu kapabalik sigām. Buwananku sigām tana' landu' ahāp maitu ma Misil, supaya sigām maglabi-labi ma kalluman.”",
        19: "Amissala gi' Pira'un, yukna, “Soho'un sigām amowa saga karitun minnitu pameya'an saga anak-h'nda sigām pi'itu, ya lagi'na mma'bi.",
        20: "Da'a na kinabimbangan palsuku'an sigām ta'bba ma lahat, sabab ma sigām na ai-ai ya ahāp to'ongan maitu ma Misil.”",
        21: "Manjari bineya' panoho'an Pira'un inān e' saga anak si Yakub. Binuwanan sigām saga karitun e' si Yusup ma buwat bay pah'lling Pira'un ma iya. Binuwanan sigām balanja' isab palutu' sigām ma l'ngnganan.",
        22: "Aniya' isab dapangampu'an s'mmek ahalga' pamuwan sigām pakaniya-pakaniya. Malaingkan ya pamuwan si Yusup ma si Benjamin, lima pangampu'an s'mmek pagsalinanna maka t'llu hatus pilak.",
        23: "Mma'na ya pinabowahan e' si Yusup sangpū' kura' l'lla ap'nno' e' ai-ai ahāp hinangan Misil, maka sangpū' kura' d'nda ap'nno' e' balanja' maka saga tinapay maka ginisan takakan-kakan pamalutu' iya ma l'ngngananna tudju ni Misil.",
        24: "Manjari itu, pinalanjal na saga danakanna e' si Yusup. Yukna ma sigām, “Ebot-ebot, da'a kam magkalukassa ma pal'ngngananbi.”",
        25: "Na, ala'an na sigām min Misil bo' pabalik pehē' ni lahat Kana'an. Pagt'kka sigām, magtūy sigām angahaka ma mma' sigām, yuk-i,",
        26: "“Mma', masi allum si Yusup! Pagnakura'an iya buwattina'an ma sakalingkal lahat Misil.” Magtūy tak'bbal atay si Yakub, sali' alungay pangannalna, mbal agon makapam'nnal ma bay pangahaka ma iya e' saga anakna.",
        27: "Malaingkan pagkalena kamemon bay panambuku si Yusup ma sigām, maka pag'nda'na isab saga karitun bay pinabeya'an iya e' si Yusup pameya'anna tudju ni Misil, magtūy pabalik pangannalna.",
        28: "Yuk si Yakub, “Kamattanan na aku. Allum du anakku si Yusup. Halam aniya' angutku saddī, bang pa'in aku makapehē' ang'nda' iya dahū sat'ggolku masi allum.”",
    },
    46: {
        1: "Na, palintas na disi Isra'il (hatina si Yakub) min lahat Kana'an maka e' sigām amowa ai-ai sigām kamemon. Tat'kka pa'in e' sigām lahat Be'erseba, anumbali' iya hayop pagkulbanna tudju ni Tuhan ya pagtuhanan mma'na si Isa'ak.",
        2: "Jari itu, sangom pa'in, takale e' si Isra'il itu suwala Tuhan angalinganan iya. “Yakub, O Yakub,” yukna. Ya sambung si Yakub, “Oy, itiya' aku.”",
        3: "Ya lling suwala-i, “Aku itu Tuhan ya pagtuhanan mma'nu. Da'a ka tināw palain ni lahat Misil, sabab mahē' aku angahinang saga panubu'nu bangsa akosog.",
        4: "Pataptap du aku ma ka'a, maka bowaku isab panubu'nu pabalik pi'itu ni lahat itu ma sinosōng. Bang ta'abut na waktunu awapat, ina'an du si Yusup ma bihingnu.”",
        5: "Manjari palanjal na disi Yakub min Be'erseba tudju ni lahat Misil. Si Yakub ya pinariyata' e' saga anakna ni karitun bay min Pira'un pameya'an sigām. Ya du pinariyata' isab saga anak-h'nda sigām.",
        6: "Bay binowa e' sigām ba'anan kahayopan sigām maka palsuku'an bay tausaha sigām maina'an ma lahat Kana'an bo' na palūd ni lahat Misil. Binowa e' si Yakub saga tubu'na kamemon.",
        7: "Tabeya' ma iya kamemon saga anak-mpuna l'lla maka d'nda.",
        8: "Ya na itu salsila ma kapanubu'an si Isra'il (hatina si Yakub) bay tabeya' ma iya waktu kapaglainna ni Misil: Si Rubin ya kasiyakahan.",
        9: "Anak si Rubin l'lla, ya na disi Hanok, si Pallu, si Hesdon maka si Karmi.",
        10: "Pasunu' si Simiyun maka saga anakna l'lla, ya na disi Jamuwal, si Jamin, si Hūd, si Yakin, si Sohar maka si Sa'ul. Si Sa'ul itu anakna min d'nda bangsa Kana'an.",
        11: "Pasunu' isab si Libi maka saga anakna l'lla, ya disi Gerson, si Kohat maka si Merari.",
        12: "Pasunu' si Yahud maka saga anakna l'lla, ya disi Sela, si Peres maka si Sera. Aniya' isab duwa anak si Yahud l'lla bay amatay ma lahat Kana'an lagi', ya na si Ēr maka si Onan. Aniya' isab saga anak si Peres l'lla, ya na si Hesdon maka si Hamul.",
        13: "Pasunu' isab si Issakar maka saga anakna l'lla, disi Tola, si Puwa, si Jasub, maka si Semlon.",
        14: "Kasiyalihan si Sibulun. Ya itu ōn anakna l'lla, disi Sered, si Elon maka si Jahale'el.",
        15: "Jari ya na ina'an saga anak si Yakub min h'ndana po'on si Leya, ya bay nianakan mahē' ma lahat Mesopotami. Aniya' isab anakna d'nda si Dina. Jari t'llumpū' maka t'llu ya heka panubu' si Yakub min h'ndana po'on si Leya.",
        16: "Ya anak si Yakub siyaka min h'nda-h'ndana si Silpa, ya na si Gād. Ya itu ōn anakna l'lla, disi Sepon, si Haggi, si Suni, si Esbon, si Iri, si Arod maka si Arili.",
        17: "Pasunu' si Aser maka anakna l'lla, ya disi Imna, si Isba, si Isbi, si Biriya, maka dakayu' d'nda isab si Sera. Aniya' isab anak si Biriya l'lla duwa hekana, si Heber maka si Malki'il.",
        18: "Jari sangpū' maka nnom ya heka panubu' si Yakub min si Silpa, ya d'nda ipatan bay pamuwan e' si Leban ma si Leya waktu kapagpūnna maka si Yakub.",
        19: "Saga anak si Yakub l'lla isab min h'ndana si Rakiya, ya na si Yusup maka si Benjamin.",
        20: "Si Manasse isab maka si Epra'im, ya anak si Yusup l'lla bay nianakan ma lahat Misil e' si Asenat anak si Potipero imam ma da'ira Ūn.",
        21: "Na, si Benjamin du isab maka saga anakna l'lla, ya na disi Bela, si Beker, si Asbel, si Gera, si Na'aman, si Ihi, si Rōs, si Muppim, si Huppim maka si Harid.",
        22: "Ya du ina'an saga tubu' si Yakub min h'ndana si Rakiya, sangpū' maka mpat puhu'.",
        23: "Ya anak si Yakub siyaka min h'nda-h'ndana si Bilha, ya na si Dān. Ya anak si Dān l'lla si Husim.",
        24: "Pasunu' si Naptali, maka anakna l'lla, disi Jasil, si Guni, si Jeser maka si Sillim.",
        25: "Ya du ina'an saga tubu' si Yakub pitu' puhu' hekana min si Bilha, ya d'nda ipatan bay pamuwan ma si Rakiya e' mma'na si Leban.",
        26: "Manjari nnompū' maka nnom ya heka panubu' si Yakub lissi bay tabeya' ma iya pehē' ni Misil, halam talapay ni'itung saga ayuwanna d'nda.",
        27: "Pak'nnop isab duwangan anak si Yusup ya bay nianakan ma Misil. Manjari pitumpū' ya heka sigām kamemon.",
        28: "Manjari si Yahud ya sinō' e' si Yakub parahū min sigām ni tongod si Yusup, bo' aniya' magmalim ma lahat Gosen. Pagt'kka pa'in sigām pehē',",
        29: "bo' kinata'uwan e' si Yusup, magtūy pinasakap e'na kalesana. Jari parai'-dai' iya ni Gosen amāk mma'na. Magbāk pa'in, magtūy ginapus si Yusup ma mma'na maka e'na anangis pat'ggol.",
        30: "Ya lling si Isra'il ma si Yusup, “Ndū' anakku, allum du hati ka! Lilla' na aku amatay pagka ka'a-i ta'nda'ku na.”",
        31: "Puwas e', ah'lling si Yusup ma saga danakanna sampay ma lahasiya'na kamemon ya ma deyoman mma'na. Yukna, “Patut aku subay paharap ni Pira'un amata'uwan iya in dauranakanku sampay lahasiya'ku kamemon magt'kkahan na min lahat Kana'an. Itiya' na kam ma aku. Pata'uku isab iya pasal pagusahabi magipat bili-bili maka sapi', ya angkan tabowabi pi'itu ba'anan kahayopan maka pangalta' bay suku'bi ma lahat Kana'an.",
        32: "Puwas e', ah'lling si Yusup ma saga danakanna sampay ma lahasiya'na kamemon ya ma deyoman mma'na. Yukna, “Patut aku subay paharap ni Pira'un amata'uwan iya in dauranakanku sampay lahasiya'ku kamemon magt'kkahan na min lahat Kana'an. Itiya' na kam ma aku. Pata'uku isab iya pasal pagusahabi magipat bili-bili maka sapi', ya angkan tabowabi pi'itu ba'anan kahayopan maka pangalta' bay suku'bi ma lahat Kana'an.",
        33: "Jarina, bang kam sinō' patampal ni Pira'un bo' kam tinilaw bang ai pagusahabi,",
        34: "sambungunbi iya buwattitu, yukbi, ‘Ya kami sosoho'annu itu, a'a magi'ipat hayop asal min jaman kaonde'-onde' kami. Ang'ntan kami bay pagusaha ka'mbo'-mbo'an kami.’ Na, bang buwattē' panambungbi, tinugutun du kam pat'nna' ma lahat Gosen. Sababna ya addat bangsa Misil mbal magdalahat maka a'a magi'ipat hayop, asammal kono' ma pang'nda' sigām.”",
    },
    47: {
        1: "Na, pehē' si Yusup ni Pira'un. Yukna ma iya, “Tuwan sultan, ilu na mma'ku maka saga danakanku at'kka min Kana'an. Tabowa e' sigām ba'anan saga kahayopan maka pangalta' sigām kamemon. Ina'an sigām ma jadjahan Gosen buwattina'an.”",
        2: "Manjari aniya' lima danakanna pinene' e' si Yusup pinakilā ma Pira'un.",
        3: "Tinilaw sigām e' Pira'un, “Ai usahabi?” Ya sambung sigām, “Tuwan Pira'un, in kami sosoho'annu itu a'a magi'ipat bili-bili, buwat bay ka'mbo'-mbo'an kami.",
        4: "Bay kami pi'itu arak maglahat maitu sabab asigpit na gotom ma lahat Kana'an. Halam aniya' minsan sagmot pagkakan saga hayop kami. Angkan ko' kami parahing ni ka'a, Tuwan, bang pa'in kami tugutannu pat'nna' ma Gosen.”",
        5: "Angabtang Pira'un ma si Yusup, yukna, “Na, pagka ilu na mma'-danakannu ma ka'a,",
        6: "makajari na sigām maglahat maingga-maingga kabaya'an sigām ma kaluha'an lahat Misil. Piha'in sigām tana' umbul-satu paglahatan sigām ma Gosen. Maka bang aniya' a'a kata'uwannu min sigām taga-kapandayan, pat'nna'un iya magmandul ma saga a'a ya magi'ipat ba'anan hayopku.”",
        7: "Pagpuwas ina'an, binowa e' si Yusup mma'na si Yakub pinakilā pehē' ni Pira'un. Ati angamu'an si Yakub pahala' ma Pira'un pangahulmatna ma iya.",
        8: "Jari aniya' patilaw Pira'un ma iya, yukna, “Pilantahun na umulnu, tuwan?”",
        9: "Ya sambung si Yakub, “Tuwan sultan, dahatus na maka t'llumpū' tahun ya paglunsul-lunsulku maitu ma dunya. Aheka isab kasukkalan bay kalabayanku. Sagō' mbal sakit at'ggol, ngga'i ka buwat bay paglunsul-lunsul kamatto'ahanku.”",
        10: "Na niamu'-amu'an Pira'un kahāpan isab e' si Yakub bo' yampa ama'id paluwas minnē'.",
        11: "Manjari pinatuntul pahāp e' si Yusup paglahat mma'na maka saga danakanna maina'an ma lahat Misil. Bineya' e'na panoho'an Pira'un angkan disi Yakub kabuwanan tana' ahāp to'ongan ma jadjahan da'ira Ramisis.",
        12: "Jari amalanja' na pa'in si Yusup ma mma'na maka ma saga danakanna sampay ma lūng-kampungna kamemon. Talapay isab saga kamanahutan.",
        13: "Pasōng na pa'in kasigpit gotom sampay halam na to'ongan aniya' kinakan minsan maingga-maingga. Jari saga a'a kamemon ma kalahat-lahatan Misil maka Kana'an magkalammahan na e' punung.",
        14: "Magb'lli na pa'in sigām balanja' pehē' ni si Yusup. Tinipun e'na kamemon sīn pam'lli sigām bo' yampa bowana ni deyom astana' Pira'un.",
        15: "Na, apuppus pa'in saga sīn kamemon ma kalahatan Misil maka lahat Kana'an, pina'an ni si Yusup saga a'a Misil parahing. Yuk sigām, “Arōy, tuwan, buwanin kami pagkakan! Halam aniya' sīn kami pam'lli. Da'a pa'in kami pasagarin amatay e' punung itu!”",
        16: "Ya sambung si Yusup, “Bang hati' halam aniya' sīnbi, na, bowahun pi'itu saga hayopbi panambi' kinakan.”",
        17: "Manjari binowa saga hayop sigām, saga kura', bili-bili, kambing maka sapi'. Binowa e' sigām pehē' ni si Yusup panambi' pagkakan. Jari aniya' kinakan pamalanja' sigām e' si Yusup ma deyom dantahun inān, panambi' saga hayop sigām.",
        18: "Aubus pa'in dantahun e', pabalik na isab sigām pehē' ni si Yusup. Ya lling sigām, “Tuwan, mbal kalimbungan kami min ka'a, halam na aniya' sīn kami maka ilu ma ka'a isab saga hayop kami kamemon. Halam aniya' takapin pamuwan kami ma ka'a, luwal baran kami maka tana' kami.",
        19: "Ndū' tuwan, da'a kami pasagarin pinunung. Kaugun isab tana' kami bang halam aniya' makapajatu iya. B'llihun baran kami sampay tana' kami panambi' kinakan. Minsan kami pina'ata ma Pira'un, minsan tana' kami pinasuku' ma iya, bang pa'in kami mbal amatay gotom. Buwanin kami isab binhi' tinanom bo' mbal kaugun tana' kami.”",
        20: "Na, pagka buwattē' kabisa gotom, tab'lli e' si Yusup tana' kamemon bay suku' saga a'a Misil pakaniya-pakaniya. Manjari Pira'un na tag-tana' kamemon,",
        21: "ati saga a'a kamemon ma lahat Misil tahinang atana ma sabab hinang si Yusup.",
        22: "Ya sadja halam tab'lli e' si Yusup tana' saga kaimaman. Aniya' balanja' sigām min Pira'un sakahaba' llaw, angkan halam bay tapab'lli saga tana' sigām.",
        23: "Manjari aniya' pamissala si Yusup ma saga a'a inān kamemon, yukna, “Na buwattina'an, pagka tab'lliku ka'am sampay tana'bi bo' kam suku' Pira'un na, na, itiya' na saga binhi' pananombi ma deyom tana'.",
        24: "Malaingkan, bang kam magani buwa' tinanombi, ya buwa'na subay binahagi' palima. Dabahagi' ilu subay pinasuku' ma Pira'un, ya mpat bahagi' takapin subay ma ka'am bo' aniya' pananombi pabīng maka aniya' takakanbi magtai'anak.”",
        25: "Ya sambung sigām “Tuwan, kalappasan kami min kamatay sabab ka'a. Bang pa'in ahāp sadja ataynu tudju ni kami, kami itu magpa'ata na ma Pira'un.”",
        26: "Manjari aniya' sara' pinat'nna' e' si Yusup ma lahat Misil, subay pinasuku' ma Pira'un bahagi' lima min ai-ai pinagani ma deyom lahat. Bineya' sara' inān sampay ni kabuwattina'anan. Luwal tana' saga kaimaman halam bay pinasuku' ma Pira'un.",
        27: "Manjari maglahat na bangsa Isra'il ma Gosen, ma deyom lahat Misil. Pasōng heka puhu' sigām, pasōng isab heka pangalta' sigām.",
        28: "Sangpū' maka pituntahun ya paglahat si Yakub mahē' ma Misil sampay dahatus maka mpatpū' maka pituntahun umulna.",
        29: "Manjari itu, song pa'in ta'abut waktuna, nilinganan e'na anakna si Yusup. Yukna, “Bang ka'a-i alasa du ma aku, pat'nna'un lagi' tangannu ma llotan pa'aku bo' yampa ka magsapa in janji'nu ma aku mbal binalubahan. Janji'in aku in aku mbal kubulnu maitu ma lahat Misil.",
        30: "Bilahi aku kinubul ma pangubulan saga ka'mbo'-mbo'anku. Angkan na bang aku amatay, bowahun bangkayku paluwas min Misil itu ati kubulunbi aku ma bay pagkubulan sigām.” Ya sambung si Yusup, “Aho' Mma', beya'ku llingnu ilu.”",
        31: "“Magsapa ka,” yuk si Yakub e'. Agsai pinagsapahan e' si Yusup. Manjari mahē' na si Yakub patukku' ma pabahakanna angamu' duwa'a ni Tuhan.",
    },
    48: {
        1: "Palabay pa'in waktu, kahaka'an si Yusup pasal mma'na alamma na, angkan iya patibaw pehē'. Binowa isab e'na karuwangan anakna si Manasse maka si Epra'im.",
        2: "Pagta'u si Yakub ilu na at'kka si Yusup, magtūy iya pakulasog papunduk.",
        3: "Ah'lling iya ma si Yusup, yukna, “Waktu kamahē'ku lagi' ma Lūs ya ma lahat Kana'an, bay magpa'nda' ma aku Tuhan Sangat Kawasa. Aniya' kahāpan pamuwanna ma aku,",
        4: "yukna, ‘Pahekaku panubu'nu sampay sigām tahinang kabangsa-bangsahan. Pamuwanku isab lahat Kana'an ilu palsuku'an saga panubu'nu sampay ni kasaumulan.’”",
        5: "Magsibahat na pa'in si Yakub ma si Yusup, yukna, “Yusup, in pasal anaknu, ya bay nianakan ma lahat Misil dahū gi' min kapi'ituku, in sigām karuwangan subay pamasuku' ma aku. Aho', si Epra'im maka si Manasse subay ni'itung anakku luggiya' buwat si Rubin maka si Simiyun.",
        6: "Malaingkan bang aniya' gi' anaknu liyu min sigām duwangan itu, suku'nu na. Maka tana' pamusaka' sigām subay niā' min bahagi' tana' ya pamasuku' ma si Epra'im maka si Manasse.",
        7: "Ina'nu si Rakiya ya sababanna angkan sigām ni'itung anakku. Landu' aheya dukkaku ma kamatayna. Ma l'ngnganan pa'in kami pabīng ni Kana'an min lahat Mesopotami, alawak-lawak gi' min kauman Eprata, amatay na iya. Jari takubulku iya mahē' ma bihing lān tudju ni Eprata.” Eprata itu, ya na Betlehem ma buwattina'an.",
        8: "Manjari pag'nda' si Yakub ma saga anak si Yusup, atilaw iya, “Sai saga onde' itu?”",
        9: "Ya sambung si Yusup, “Mma', ya na ko' itu anakku l'lla bay pamuwan Tuhan ma aku maitu ma Misil.” Yuk si Yakub, “Pasōngun sigām pi'itu supaya sigām kapangamu'anku kahāpan min Tuhan.”",
        10: "Na si Yakub itu, mbal agon maka'nda' sabab ato'a na iya to'ongan. Angkan pinasekot e' si Yusup saga anakna. Magtūy sigām ginapus e' si Yakub sampay siniyum.",
        11: "Yuk si Yakub ma si Yusup, “Halam aku bay makaholat ang'nda' ka'a pabīng, daipara kahandak min Tuhan itiya' ka ta'nda'ku sampay isab anaknu.”",
        12: "Pagpuwas, pinala'an e' si Yusup anakna min gibahan mma'na bo' yampa iya pasujud ma dahuanna.",
        13: "Manjari binalutan e' si Yusup anakna duwangan bo' pinasekot ni si Yakub. Si Epra'im ya pinasekot ni tangan si Yakub gibang, si Manasse ni tanganna kowan.",
        14: "Saguwā' pinagsaliyu e' si Yakub tangan mma'na bo' pinat'nna' tanganna kowan ma kōk si Epra'im minsan iya siyali. Maka tanganna gibang pinat'nna' ma kōk si Manasse, ya siyaka.",
        15: "Pagbuwattē', niamu'an duwa'a disi Yusup e' si Yakub, yukna, “Bang pa'in saga onde' itu binuwanan kahāpan e' Tuhan ya pameya'an mbo'ku si Ibrahim maka mma'ku si Isa'ak. Bang pa'in sigām pinat'kkahan lidjiki' e' Tuhan, ya bay angupiksa' aku min kanahutku sampay ni kabuwattituku, Bang pa'in nianughala'an duwangan onde' itu e' Mala'ikat ya bay amapuwas aku min kamulahan kamemon. Bang pa'in sigām pas'lle' amowa ōnku maka ōn mma'ku si Isa'ak sampay ōn mbo'ku si Ibrahim. Bang pa'in paheka to'ongan isab saga panubu' sigām maitu ma babaw dunya itu.”",
        16: "Pagbuwattē', niamu'an duwa'a disi Yusup e' si Yakub, yukna, “Bang pa'in saga onde' itu binuwanan kahāpan e' Tuhan ya pameya'an mbo'ku si Ibrahim maka mma'ku si Isa'ak. Bang pa'in sigām pinat'kkahan lidjiki' e' Tuhan, ya bay angupiksa' aku min kanahutku sampay ni kabuwattituku, Bang pa'in nianughala'an duwangan onde' itu e' Mala'ikat ya bay amapuwas aku min kamulahan kamemon. Bang pa'in sigām pas'lle' amowa ōnku maka ōn mma'ku si Isa'ak sampay ōn mbo'ku si Ibrahim. Bang pa'in paheka to'ongan isab saga panubu' sigām maitu ma babaw dunya itu.”",
        17: "Na, pag'nda' si Yusup ma mma'na amat'nna' tanganna kowan ma kōk si Epra'im, halam iya kasulutan. Binalutan e'na tangan mma'na kowan, arak pinat'nna' ma kōk si Manasse.",
        18: "Yukna ma mma'na, “Mma', asā' ko' ilu! Ya itu siyaka, ya subay pinat'nna'an tangannu kowan.”",
        19: "Sagō' mbal bilahi si Yakub, yukna, “Aho' Otō', kata'uwanku du. Si Manasse ilu b'nnal paheka panubu'na tahinang bangsa ga'osan. Malaingkan siyalina ya labi akosog min iya. Saga panubu' si Epra'im itu subay paheka to'ongan sampay sigām tahinang aheka bangsa gaga'osan.”",
        20: "Manjari niamu'-amu'an sigām kahāpan ma llaw ina'an-i. Yuk si Yakub, “Ma tahun sinōng, bang aniya' a'a Isra'il angamu'an kahāpan ma sai-sai, ōnbi ya panabbutanna. Buwattitu ya pangamu' sigām, ‘Bang pa'in kam binuwanan kahāpan e' Tuhan buwat bay ma si Epra'im maka si Manasse.’” Buwattē' pah'lling si Yakub, pagka paheyana si Epra'im labi min si Manasse.",
        21: "Puwas e', ah'lling isab si Yakub ma anakna si Yusup, yukna, “Nda'un, asekot na waktuku. Saguwā' mbal kam pinasagaran e' Tuhan. Pagapi' du iya ma ka'am bo' kam tabowana pabīng ni lahat ka'mbo'-mbo'anbi.",
        22: "Ma deyom saga anakku, ka'a ya pusaka'anku tana' lahat Sekem, ya tana' ahāp ma kabūd-būran bay ngā'ku min bangsa Amor. Ya bay pangā'ku iya pakokosku kalis maka pana'.”",
    },
    49: {
        1: "Manjari nilinganan e' si Yakub saga anakna kamemon. “Pasekot kam,” yukna, “patipun kam ni aku. Haka'anta kam dangan maka dangan bang ai ya kasōnganbi ma tahun damuli.",
        2: "Patipun kam saga anak si Yakub, pakale kam ma pangabtang ya pang'bbahan ka'am e' mma'bi si Isra'il.",
        3: "Ka'a Rubin, anakku kasiyakahan, anak min kosogku, paltanda'an pagkal'llaku. Min kamemon saga anakku, ka'a ya pagmakōkan akosog maka abantug.",
        4: "Saguwā' ya salla'nu, bay pakaiya'nu mma'nu pagka hulidnu h'ndana dakayu'. Napsunu ilu sali' dunuk mbal katiyara'an, angkan ka mbal na makalanga min dauranakannu.",
        5: "Ka'am Simiyun maka Libi, dalimbang du kam. Mbal aku bilahi palamud ma pagisunanbi, mbal pasōd ni deyom palhimpunanbi. Asapat kam angahublut pakokosbi ma saukat apasu' pangatayanbi. Bang kam niastolan, magtūy kam amono' a'a, tapengkolbi saga sapi' mandangan ma halam sababna.",
        6: "Ka'am Simiyun maka Libi, dalimbang du kam. Mbal aku bilahi palamud ma pagisunanbi, mbal pasōd ni deyom palhimpunanbi. Asapat kam angahublut pakokosbi ma saukat apasu' pangatayanbi. Bang kam niastolan, magtūy kam amono' a'a, tapengkolbi saga sapi' mandangan ma halam sababna.",
        7: "Bang pa'in kam pinat'kkahan mulka' ma sabab pangastolbi mbal tasangsang. Pinapulak-palik saga panubu'bi ma katilibutan lahat Isra'il.",
        8: "Na, ka'a Yahud, pinudji du ka e' saga dauranakannu. Pasujud sigām pagmahaltabat ma ka'a. Tara'ugnu du palbantahannu.",
        9: "Ka'a ilu ibarat halimaw asangpot kosogna. Bang aubus e'na an'kkob hayop maka amangan magtūy pah'nnat atuli ma tongod ina'an. Halam aniya' makatawakkal pasekot anasat iya.",
        10: "Saga panubu'nu, Yahud, sinusultan salama-lama. Mbal alungay kapatutnu kapagsultan sampay at'kka a'a dangan ya apatut pinaghulmatan. Kapagbaya'anna saga kabangsa-bangsahan.",
        11: "Kaengkotan kura'na ni batang anggul, ya ahāp suliganna min kamemon. Ajatu to'ongan ba'anan buwa' anggulna, landu' aheka bohe'na bang tap'gga', manjari pangandakdakan s'mmekna.",
        12: "Matana arokot keyatna min bohe' anggul, emponna apote' sidda min gatas.",
        13: "Na, anakku si Sibulun, bihing tahik ya paglahatanna, manjari paglalayohan kappal. Aluha isab tana'na, maka'abut sampay ni lahat Sidun.",
        14: "Na, si Issakar, sali' sapantun kura' akosog baranna, pabahak sadja ma t'ngnga' duwa'anna.",
        15: "Pagsayuna ahāp pabahakanna, magtūy iya amuspus kosogna angahangkut. Pagsayuna ahāp paglahatanna, magtūy iya lilla' pina'ata maghulas-magsangsā'.",
        16: "Anakku si Dān, amat'nna' hukuman abontol ma saga a'ana, pagka dapanubu' sigām ma bangsa Isra'il.",
        17: "Ibarat iya sowa abisa pat'nna' ma bihing lān. Bang aniya' palabay minna'an a'a magkura', tinanghab e'na kura' inān ma buli' tape'na supaya pahantak ni buli'an a'a angura' he'.",
        18: 'O Yawe, lagaranku waktu pangalappasnu ma aku.',
        19: "Na, anakku si Gād isab, nilangpasan ko' ka'a ilu e' saga mundu, sagō' taturulnu sigām sampay ka'atuhannu.",
        20: "Si Aser isab, alanab kinakan ya niā' min tana'nu, kinakan ahāp nanamna patut pagkakan sultan.",
        21: "Si Naptali isab, sali' sapantun usa d'nda bay pinal'ppa min sasak. Alingkat isab saga anakna.",
        22: "Na, anakku si Yusup, sali' hantang po'on kayu ajatu to'ongan buwa'na, ya patomo' asal ma bihing bohe'. Palabung saga sanga sampay parambila' sasak.",
        23: "Nirugpak iya e' saga a'a magtakos pana', nijingki iya e' sigām.",
        24: "Malaingkan atotog l'ngngonna, ahogot e'na ang'ntan pana' ma sabab tabang min Tuhan Sangat Kawasa, ya Tuhan pagtuhanan si Yakub. Niupiksa' iya e' Tuhan, ya Batu-Lakit pasindungan bangsa Isra'il.",
        25: "Tinabang du si Yusup e' Tuhanku ya pagtuhanan mma'nu, binarakatan ka e' Tuhan Sangat Kawasa. Kabuwanan ka kahāpan, ulan min diyata' langit, bohe' min deyom tana', kahāpan panganak maka kahāpan pamaruru'.",
        26: "In lidjiki' pangamu'-ngamu'anku ka'a itu labi ahāp min lidjiki' kabūd-būran, lidjiki' bay min awal. Mura-murahan, bang pa'in saga lidjiki' itu kamemon makani-si Yusup, ya tapene' e' Tuhan pinaliyu min dauranakanna.",
        27: "Anakku isab si Benjamin, a'a aesog iya, sali' sapantun ero' talun. Subu-subu amangan ai-ai bay papatayna. Abay kohap amahagi' ai-ai bay tatabanna ma pagbono'an.”",
        28: "Na, ya du ina'an saga bangsa Isra'il kasangpū' maka duwa. Ya ina'an kabtangan bay pang'bba e' si Yakub ma anakna kasangpū' maka duwa, ya makatōpan sigām dangan maka dangan.",
        29: "Manjari aniya' panoho'an pang'bba e' si Yakub ma saga anakna he', “Itiya' aku arai' na patipun ni ka'mbo'-mbo'anku. Bang aku ta'abut na, kubulunbi aku ma deyom songab batu bay pangubulan ka'mbo'-mbo'anku. Ina'an ma lahat Kana'an, ma tana' Makpela ya ma anggopan Mamre. Songab batu inān sampay tana'na bay tab'lli e' mbo'ku si Ibrahim min si Epron bangsa Hīt.",
        30: "Manjari aniya' panoho'an pang'bba e' si Yakub ma saga anakna he', “Itiya' aku arai' na patipun ni ka'mbo'-mbo'anku. Bang aku ta'abut na, kubulunbi aku ma deyom songab batu bay pangubulan ka'mbo'-mbo'anku. Ina'an ma lahat Kana'an, ma tana' Makpela ya ma anggopan Mamre. Songab batu inān sampay tana'na bay tab'lli e' mbo'ku si Ibrahim min si Epron bangsa Hīt.",
        31: "Ina'an maina'an pagkubulan si Ibrahim maka h'ndana si Sara, mma'ku si Isa'ak maka ina'ku si Ripka. Ina'an isab pagkubulanku h'ndaku si Leya.",
        32: "Ya tana' maka songab ilu bay tab'lli min saga bangsa Hīt.”",
        33: "Aubus pa'in e' si Yakub ang'bba panoho'anna inān ma saga anakna, magtūy iya pabahak bo' yampa ab'kkat napasna. Hatina magtipun na iya maka kamatto'ahanna.",
    },
    50: {
        1: "Awapat pa'in si Yakub, magtūy iya ginapus pahogot e' anakna si Yusup. Tinangisan iya, siniyum isab baihu'na.",
        2: "Pagpuwas, magpanoho'an si Yusup ma saga panday ya tendogna, sinō' kinapul bangkay mma'na.",
        3: "Manjari aniya' mpatpū' llaw ya t'ggol sigām magkapul. Addat Misil ko' inān. Pitumpū' llaw isab ya paghinang saga a'a Misil pagdukka sigām ma iya.",
        4: "Atammat pa'in paghinang e', ah'lling si Yusup ma saga tendog Pira'un, yukna, “Bang makajari, pasampayunbi lapalku itu pehē' ni Pira'un, yukbi,",
        5: "‘Tuwan sultan, marai' pa'in waktu mma'ku, bay aku pinasapa e'na. Bangkayna kono' subay kinubul ma lahat Kana'an, ma pagkubulan bay tagamahanna ma baranna. Jari makasapa aku, ya angkan subay beya'ku na. Angamu' aku ma ka'a, Tuwan, bang pa'in aku tugutannu pehē' ni Kana'an angubul mma'ku.’ Pabalik du aku pi'itu bang aubus na.”",
        6: "Ya sambung Pira'un ma si Yusup, “Makajari,” yukna. “Pehē' na ka angubul mma'nu. Beya'un bay pagsapahannu maka iya.”",
        7: "Manjari palanjal na si Yusup angubul mma'na. Pabunyug isab ma iya kamemon saga tendog ya pagnakura'an ma okoman Pira'un, ma deyom astana' ka atawa ma kaluha'an lahat Misil.",
        8: "Ya du pabunyug ma si Yusup saga dauranakanna maka saga a'a kamemon ya ma deyomanna. Tabeya' isab saga a'a bay ma deyoman mma' sigām. Ya sadja halam tabeya' kamanahutan maka ba'anan hayop sigām. Tabba maina'an ma Gosen.",
        9: "Aniya' pagapi' ma sigām saga a'a magkakaritun sampay saga a'a magkukura'. Jari landu' aheka sigām bay maglurukan angubul mma' si Yusup.",
        10: "Ta'abut pa'in sigām paggi'ikan pai ma Atad, ma bihing sapa' Jordan, magkarukka'an sigām ma mma' si Yusup. Akosog sidda pagdukka sigām. Jari pitumbahangi ya t'ggol paghinang si Yusup ma mma'na ma atag ina'an.",
        11: "Na pag'nda' paghinang itu e' saga bangsa Kana'an ya maglahat maina'an, yuk sigām, “Kaheya du pa'in karukka'an saga bangsa Misil e'.” Angkan kaōnan lahat inān Abel Misraim.",
        12: "Na, bineya' e' saga anak si Yakub buwat bay panoho'anna ma sigām.",
        13: "Binowa bangkayna ni lahat Kana'an bo' kinubul e' sigām ma deyom songab batu ma tana' Makpela ya ma anggopan Mamre. Tana' inān bay tab'lli asal e' si Ibrahim min si Epron bangsa Hīt bo' pagkubulan.",
        14: "Na, takubul pa'in, pabalik na disi Yusup ni lahat Misil, iya maka saga danakanna sampay sigām kamemon bay amunyugan mma'na he'.",
        15: "Na, pagka amatay na mma' sigām, magisun-isun saga danakan si Yusup. Yuk sigām, “Kalu aniya' akon-akon tatau' e' si Yusup ma deyom atayna pasal kala'atan kamemon bay tahinangtam ma iya. Painay bang kitam binalosan e'na?”",
        16: "Manjari anambuku sigām pehē' ni si Yusup, yuk-i, “Tuwan, ma halam lagi' amatay Mma'tam, aniya' bay panoho'anna.",
        17: "Sinō' ka tinambukuhan buwattitu: ‘Ampunun dauranakannu ma pasal dusa maka kala'atan bay tahinang sigām ma ka'a.’ Ya du ilu panambuku si Mma' ma ka'a. Manjari, Tuwan, itiya' kami parahing ma ka'a bang pa'in kami ampunnu, pagka in kami itu ata Tuhan ya pagtuhanan mma'tam.” Na, pagkale lapal itu e' si Yusup, magtūy iya tatangis.",
        18: "Puwas e', patampal saga danakanna ni si Yusup bo' yampa sigām pak'ppang ni tana' ma munda'anna. Ya lling sigām ma iya, “Tuwan, itiya' kami magpatiata ma ka'a.”",
        19: "Sagō' ya sambung si Yusup ma sigām, “Da'a kam tināw ma aku. Ngga'i ka aku ya magbaya', luwal Tuhan.",
        20: "B'nnal, ala'at asal bay maksudbi, sagō' kahāpan ya pangangganti' e' Tuhan, ya angkan tahinang hinangku itu angalappasan manusiya' aheka min kamatay.",
        21: "Angkan yukku ma ka'am, da'a kam agawa. Akuhanku balanja'bi sampay saga ka'anakanbi.” Sakali asannang na pangatayan sigām ma sabab kahanunut bissala si Yusup e'.",
        22: "Manjari maina'an na pa'in si Yusup pat'nna' ma lahat Misil maka saga a'a kamemon bay ma okoman mma'na. Allum iya sampay dahatus maka sangpū' tahun umulna.",
        23: "Ta'abutna saga anak-mpu si Epra'im, maka tagibana isab mpu si Manasse min anakna si Makil.",
        24: "Na, angabtang na si Yusup ma saga danakanna, yukna, “Aku itu arai' na ta'abut, sagō' ka'am ilu tinabang du e' Tuhan. Ma waktu sinōng binowa kam e'na paluwas min lahat itu tudju ni lahat bay panganjanji'na ma kamatto'ahantam disi Ibrahim, si Isa'ak maka si Yakub.”",
        25: "Jari pinasapa e' si Yusup saga pagkahina panubu' si Isra'il (ya kaōnan isab si Yakub). “Sapahinbi aku,” yukna, “in to'olangku bowabi du bang ta'abut waktu panabang Tuhan ma ka'am paluwas min lahat itu.”",
        26: "Manjari awapat na si Yusup maina'an ma Misil, dahatus maka sangpū' tahun umulna. Kinapul bangkayna bo' yampa ni'isi ni deyom lalungan.",
    },
}
